function fmtWait(sec) {
  const s = Math.max(0, Number(sec || 0));
  if (!Number.isFinite(s) || s <= 0) return 'несколько секунд';
  if (s < 60) return `${Math.ceil(s)} сек.`;
  if (s < 3600) return `${Math.ceil(s / 60)} мин.`;
  return `${Math.ceil(s / 3600)} ч.`;
}

// Small numeric helper (used in callback parsing)
function num(v, def = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.trunc(n) : def;
}

// Unique string array (trim + dedupe, preserves order)
function uniqStrArr(arr) {
  if (!Array.isArray(arr)) return [];
  const out = [];
  const seen = new Set();
  for (const x of arr) {
    const s = String(x ?? '').trim();
    if (!s || seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

// Brand-facing: sanitize creator display name (no @, no t.me links) to prevent contact leaks
function safeCreatorDisplayName(ws) {
  const title = String(ws?.title || '').trim();
  const unameRaw = String(ws?.username || ws?.channel_username || '').trim();
  const uname = unameRaw.replace(/^@/, '');
  // prefer title, fallback to username, then generic
  let base = (title || uname || 'Креатор');
  // strip t.me links and @ mentions
  base = base.replace(/https?:\/\/t\.me\/[A-Za-z0-9_]+/gi, '');
  base = base.replace(/@/g, '');
  base = base.replace(/\s+/g, ' ').trim();
  if (base.length > 80) base = base.slice(0, 80).trim();
  return base || 'Креатор';
}

// Sponsors helpers (Jobs-style clarity)
function normalizeSponsorsList(raw) {
  if (!Array.isArray(raw)) return [];
  const out = [];
  for (const item of raw) {
    if (!item) continue;
    if (typeof item === 'string') {
      const s = item.trim();
      if (s) out.push(s);
      continue;
    }
    if (typeof item === 'object') {
      const s = String(item.sponsor_text ?? item.sponsorText ?? item.sponsor ?? item.text ?? item.handle ?? item.username ?? '').trim();
      if (s) out.push(s);
      continue;
    }
    const s = String(item).trim();
    if (s) out.push(s);
  }
  // unique preserve order
  return [...new Set(out)];
}

function fmtSponsorHandle(raw) {
  const item = raw && typeof raw === 'object'
    ? (raw.sponsor_text ?? raw.sponsorText ?? raw.sponsor ?? raw.text ?? raw.handle ?? raw.username)
    : raw;
  const handle = sponsorToChatId(item);
  return handle || String(item || '').trim();
}

function sponsorUrlFromHandle(handle) {
  const h = String(handle || '').trim();
  if (!h) return null;
  if (h.startsWith('@') && h.length > 1) return `https://t.me/${h.slice(1)}`;
  if (/^https?:\/\//i.test(h)) return h;
  return null;
}

function sponsorsInlineText(rawSponsors, max = 3) {
  const handles = normalizeSponsorsList(rawSponsors).map(fmtSponsorHandle).filter(Boolean);
  if (!handles.length) return '';
  const shown = handles.slice(0, max);
  const rest = handles.length - shown.length;
  const inline = shown.join(', ');
  return rest > 0 ? `${inline} +${rest}` : inline;
}

function ruPlural(n, one, few, many) {
  const x = Math.abs(Number(n) || 0);
  const mod10 = x % 10;
  const mod100 = x % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && !(mod100 >= 12 && mod100 <= 14)) return few;
  return many;
}

function sponsorsBulletText(rawSponsors, max = 5) {
  const handles = normalizeSponsorsList(rawSponsors).map(fmtSponsorHandle).filter(Boolean);
  if (!handles.length) return '';
  const shown = handles.slice(0, max);
  const rest = handles.length - shown.length;
  const bullets = shown.map((h) => `• ${escapeHtml(h)}`).join(' ');
  return rest > 0 ? `${bullets} +${rest}` : bullets;
}

function sponsorsCountText(rawSponsors) {
  const handles = normalizeSponsorsList(rawSponsors).map(fmtSponsorHandle).filter(Boolean);
  const n = handles.length;
  if (!n) return '';
  const word = ruPlural(n, 'канал', 'канала', 'каналов');
  return `подписка на <b>${n}</b> ${word}`;
}

function sponsorStateIcon(state) {
  if (state === 'ok') return '✅';
  if (state === 'no') return '❌';
  if (state === 'unknown') return '⚠️';
  return '⚪';
}

// Giveaway winners formatting (Jobs-style: compact for small, truncated for big)
const GW_WINNERS_ONE_LINE_MAX = 3;
const GW_WINNERS_MAX_LINES = 10;

function fmtGwWinnerName(w) {
  const uname = w && w.username ? '@' + escapeHtml(String(w.username)) : null;
  if (uname) return uname;
  const id = w && (w.tg_id ?? w.tgId ?? w.user_id ?? w.userId);
  return `id:${Number(id || 0)}`;
}

/**
 * Formats winners list for channel text.
 * - If total winners <= oneLineMax: returns a single line "1) @a · 2) @b"
 * - Else returns multiline "1. @a\n2. @b" (truncated to maxLines) + "... +N ещё (см. в боте)"
 */
function formatGwWinners(winners, { oneLineMax = GW_WINNERS_ONE_LINE_MAX, maxLines = GW_WINNERS_MAX_LINES } = {}) {
  const items = (Array.isArray(winners) ? winners : []).map(w => ({
    place: Number(w.place || 0) || 0,
    name: fmtGwWinnerName(w),
  }));

  const total = items.length;
  if (!total) return { mode: 'none', text: '', total: 0, truncated: false, shown: 0 };

  // Ensure stable order by place if present
  items.sort((a, b) => (a.place || 0) - (b.place || 0));

  if (total <= oneLineMax) {
    const line = items.map(i => `${i.place || ''}`.trim()
      ? `${i.place}) ${i.name}`
      : i.name
    ).join(' · ');
    return { mode: 'one', text: line, total, truncated: false, shown: total };
  }

  const cap = Number.isFinite(maxLines) && maxLines > 0 ? Math.trunc(maxLines) : GW_WINNERS_MAX_LINES;
  const shownItems = items.slice(0, cap);
  const rest = total - shownItems.length;

  let body = shownItems.map(i => `${i.place || ''}`.trim()
    ? `${i.place}. ${i.name}`
    : i.name
  ).join('\n');

  if (rest > 0) {
    body += `\n… +${rest} ещё (см. в боте)`;
  }
  return { mode: 'lines', text: body, total, truncated: rest > 0, shown: shownItems.length };
}

// Giveaway winners formatting for owner-card (same pin-format + truncation, but with user links when no @username)
function fmtGwWinnerNameOwner(w) {
  const uname = w && w.username ? '@' + escapeHtml(String(w.username)) : null;
  if (uname) return uname;
  const id = w && (w.tg_id ?? w.tgId ?? w.user_id ?? w.userId);
  const uid = Number(id || 0);
  if (uid > 0) return `<a href="tg://user?id=${uid}">участник</a>`;
  return 'участник';
}

function formatGwWinnersOwner(winners, { oneLineMax = GW_WINNERS_ONE_LINE_MAX, maxLines = GW_WINNERS_MAX_LINES } = {}) {
  const items = (Array.isArray(winners) ? winners : []).map(w => ({
    place: Number(w.place || 0) || 0,
    name: fmtGwWinnerNameOwner(w),
  }));

  const total = items.length;
  if (!total) return { mode: 'none', text: '', total: 0, truncated: false, shown: 0 };

  // Ensure stable order by place if present
  items.sort((a, b) => (a.place || 0) - (b.place || 0));

  if (total <= oneLineMax) {
    const line = items.map(i => `${i.place || ''}`.trim()
      ? `${i.place}) ${i.name}`
      : i.name
    ).join(' · ');
    return { mode: 'one', text: line, total, truncated: false, shown: total };
  }

  const cap = Number.isFinite(maxLines) && maxLines > 0 ? Math.trunc(maxLines) : GW_WINNERS_MAX_LINES;
  const shownItems = items.slice(0, cap);
  const rest = total - shownItems.length;

  let body = shownItems.map(i => `${i.place || ''}`.trim()
    ? `${i.place}. ${i.name}`
    : i.name
  ).join('\n');

  if (rest > 0) {
    body += `\n… +${rest} ещё (см. в боте)`;
  }
  return { mode: 'lines', text: body, total, truncated: rest > 0, shown: shownItems.length };
}



// Runtime toggles (stored in Redis, editable from Admin)
const SYS_KEYS = {
  pay_accept: k(['sys', 'pay_accept']),
  pay_auto_apply: k(['sys', 'pay_auto_apply']),
  matchfeat_auto_apply: k(['sys', 'matchfeat_auto_apply']),
  broadcast_qstash_fanout: k(['sys', 'broadcast_qstash_fanout']),
  // Founder Sale runtime overrides (Admin -> Redis)
  founder_sale: k(['sys', 'founder_sale']),
  sys_notice: k(['sys', 'notice']),
  admin_dm_templates: k(['sys', 'admin_dm_templates']),
};


// UI banners (optional): send banner image no more than once per N hours per slot per user
async function maybeSendBanner(ctx, slot, fileId) {
  try {
    const fid = String(fileId || '').trim();
    if (!fid) return;
    const uid = ctx?.from?.id ? Number(ctx.from.id) : 0;
    if (!uid) return;

    const hours = Number(CFG.BANNER_COOLDOWN_HOURS || 24);
    const ttlSec = (Number.isFinite(hours) && hours > 0 ? hours : 24) * 3600;

    const key = k(['ui_banner', slot || 'default', uid]);
    const seen = await redis.get(key);
    if (seen) return;

    await redis.set(key, '1', { ex: ttlSec });
    await ctx.replyWithPhoto(fid);
  } catch (_) {
    // ignore banner failures
  }
}

async function getSysBool(key, defaultValue = false) {
  try {
    const v = await redis.get(key);
    if (v === null || v === undefined) return Boolean(defaultValue);
    const s = String(v).toLowerCase();
    if (s === '1' || s === 'true' || s === 'on' || s === 'yes') return true;
    if (s === '0' || s === 'false' || s === 'off' || s === 'no') return false;
    return Boolean(defaultValue);
  } catch {
    return Boolean(defaultValue);
  }
}

async function setSysBool(key, value) {
  try {
    // TTL-LINT: allow-persistent — runtime system flags are intentionally stored without TTL.
    await redis.set(key, value ? '1' : '0');
    return true;
  } catch {
    return false;
  }
}

async function getSysObj(key) {
  try {
    const v = await redis.get(key);
    if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
    return v;
  } catch {
    return null;
  }
}

async function setSysObj(key, obj) {
  try {
    if (!obj || typeof obj !== 'object') return false;
    // TTL-LINT: allow-persistent — runtime system objects are intentionally stored without TTL.
    await redis.set(key, obj);
    return true;
  } catch {
    return false;
  }
}

async function delSysKey(key) {
  try {
    await redis.del(key);
    return true;
  } catch {
    return false;
  }
}

async function getPaymentsRuntimeFlags() {
  const accept = await getSysBool(SYS_KEYS.pay_accept, CFG.PAYMENTS_ACCEPT_DEFAULT);
  const autoApply = await getSysBool(SYS_KEYS.pay_auto_apply, CFG.PAYMENTS_AUTO_APPLY_DEFAULT);
  return { accept, autoApply };
}

async function getMatchFeatAutoApplyRuntime() {
  // Match/Feat auto-apply kill-switch (Redis). Default: ON.
  return await getSysBool(SYS_KEYS.matchfeat_auto_apply, true);
}


// Backward-compatible alias (some flows call getPaymentMode)
async function getPaymentMode() {
  return getPaymentsRuntimeFlags();
}

// -----------------------------
// System Notice (Admin → Redis) — STEP188
// -----------------------------
// Design: this is NOT a broadcast.
// It's a passive one-time (per version) notice shown when users enter Menu/Home hub.
// Storage: Redis-only (SYS_KEYS.sys_notice object). No DB.
// Seen markers: Redis-only key per tg_id × version.
const SYS_NOTICE_SEEN_TTL_SEC = 180 * 24 * 60 * 60; // 180 days
// Telegram message hard limit is 4096 chars. We keep a safer body budget for messages that add headers/footers.
const TG_TEXT_MAX = 4096;
const TG_SAFE_BODY_MAX = 3500;

// CTA field limits (keep UI clean; also below Telegram limits).
const CTA_LABEL_MAX = 32;
const CTA_URL_MAX = 512;


function normalizeNoticeSeverity(v) {
  const s = String(v || '').toLowerCase().trim();
  if (s === 'warn' || s === 'warning') return 'warn';
  if (s === 'critical' || s === 'crit' || s === 'alarm') return 'critical';
  return 'info';
}

function normalizeNoticeTarget(v) {
  const s = String(v || '').toLowerCase().trim();
  if (s === 'brand' || s === 'brands') return 'brand';
  if (s === 'creator' || s === 'creators') return 'creator';
  return 'all';
}

function normalizeNoticeCtaLabel(v) {
  const raw0 = String(v || '').replace(/\r/g, '').trim();
  if (!raw0) return '';
  // Keep label compact: one line, no ellipsis in button text.
  const raw = raw0.replace(/\s+/g, ' ').trim();
  return clipCodepoints(raw, CTA_LABEL_MAX, { ellipsis: '' }).text;
}



function normalizeNoticeCtaUrl(v) {
  const raw = String(v || '').trim();
  if (!raw) return '';
  const low = raw.toLowerCase();
  if (!(low.startsWith('https://') || low.startsWith('http://'))) return '';
  // Keep URL reasonably short to avoid Telegram limits / weird UI (no ellipsis).
  return clipCodepoints(raw, CTA_URL_MAX, { ellipsis: '' }).text;
}


function normalizeNoticeExpiresAtSec(v) {
  if (v == null) return null;
  // Epoch seconds (preferred)
  if (typeof v === 'number' && Number.isFinite(v) && v > 0) {
    return Math.trunc(v);
  }
  const s = String(v || '').trim();
  if (!s) return null;
  if (/^\d{9,}$/.test(s)) {
    const n = Number(s);
    if (Number.isFinite(n) && n > 0) return Math.trunc(n);
  }
  // ISO date-time (must include timezone to be unambiguous; but we accept best-effort)
  const ms = Date.parse(s);
  if (!Number.isFinite(ms) || ms <= 0) return null;
  return Math.trunc(ms / 1000);
}

function noticeIcon(sev) {
  const s = normalizeNoticeSeverity(sev);
  if (s === 'critical') return '🚨';
  if (s === 'warn') return '⚠️';
  return 'ℹ️';
}

function noticeTitle(sev) {
  const s = normalizeNoticeSeverity(sev);
  if (s === 'critical') return 'СРОЧНОЕ ОБЪЯВЛЕНИЕ';
  if (s === 'warn') return 'ВАЖНОЕ ОБЪЯВЛЕНИЕ';
  return 'ОБЪЯВЛЕНИЕ';
}

function normalizeSysNotice(obj) {
  const src = (obj && typeof obj === 'object' && !Array.isArray(obj)) ? obj : {};
  const active = !!src.active;
  const severity = normalizeNoticeSeverity(src.severity);
  const target = normalizeNoticeTarget(src.target ?? src.audience ?? src.role ?? 'all');

  let version = Number(src.version || 0);
  if (!Number.isFinite(version) || version < 0) version = 0;
  version = Math.trunc(version);

  // Keep text as plain user-facing content (no HTML), we escape it on send.
  // Hard-clip to Telegram limit (safe for emoji).
  const text0 = String(src.text || '').replace(/\r\n/g, '\n').trim();
  const text = clipCodepoints(text0, TG_TEXT_MAX).text;

  const ctaLabelRaw = src.ctaLabel ?? src.cta_label ?? (src.cta && src.cta.label) ?? '';
  const ctaUrlRaw = src.ctaUrl ?? src.cta_url ?? (src.cta && src.cta.url) ?? '';
  const ctaUrl = normalizeNoticeCtaUrl(ctaUrlRaw);
  const ctaLabel = ctaUrl ? (normalizeNoticeCtaLabel(ctaLabelRaw) || '🔗 Подробнее') : '';

  const expiresAtRaw = src.expiresAt ?? src.expires_at ?? src.expireAt ?? src.expire_at ?? null;
  const expiresAt = normalizeNoticeExpiresAtSec(expiresAtRaw);

  const updatedAt = src.updatedAt ? String(src.updatedAt) : null;

  return { active, severity, target, version, text, ctaLabel, ctaUrl, expiresAt, updatedAt };
}

async function getSysNotice() {
  const obj = await getSysObj(SYS_KEYS.sys_notice);
  return normalizeSysNotice(obj);
}

async function setSysNotice(next) {
  const obj = normalizeSysNotice(next);
  return await setSysObj(SYS_KEYS.sys_notice, obj);
}

