// --- Admin DM placeholders (STEP191) ---
// Strict allowlist for templates and free text. Unknown placeholders are left as-is.
const ADMIN_DM_PLACEHOLDERS = [
  { key: 'username', token: '{{username}}', desc: 'Юзернейм получателя (например @name). Если нет — пусто.' },
  { key: 'user_id', token: '{{user_id}}', desc: 'TG ID получателя (цифры).' },
  { key: 'first_name', token: '{{first_name}}', desc: 'Имя (Telegram first_name), best-effort. Если нет — пусто.' },
  { key: 'role', token: '{{role}}', desc: 'Роль по Redis ui_mode: brand/creator/unknown.' },
  { key: 'bot_name', token: '{{bot_name}}', desc: 'Название проекта (Collabka PR).' },
];

const ADMIN_DM_PLACEHOLDER_KEYS = new Set(ADMIN_DM_PLACEHOLDERS.map((x) => x.key));

function adminDmPlaceholdersHelpHtml() {
  let t = '📎 <b>Плейсхолдеры</b>\n\n';
  t += 'Вставляй в шаблоны / свободный текст. При предпросмотре и отправке будут подставлены значения.\n\n';
  for (const p of ADMIN_DM_PLACEHOLDERS) {
    t += `• <code>${escapeHtml(p.token)}</code> — ${escapeHtml(p.desc)}\n`;
  }
  t += '\nПример:\n<pre>Привет, {{first_name}}!\nТвой username: {{username}}\nID: {{user_id}}</pre>';
  return t;
}

async function buildAdminDmPlaceholderValues(ctx, targetTgId, opts = {}) {
  const tgId = Number(targetTgId || 0);
  const storedUsername = String(opts.username || '').replace(/^@/, '').trim();
  const storedFirstName = String(opts.firstName || '').trim();

  let chatUsername = '';
  let chatFirstName = '';
  try {
    const chat = await ctx.api.getChat(tgId);
    chatUsername = chat?.username ? String(chat.username).replace(/^@/, '').trim() : '';
    chatFirstName = chat?.first_name ? String(chat.first_name).trim() : '';
  } catch {}

  const usernameRaw = (chatUsername || storedUsername || '').trim();
  const username = usernameRaw ? '@' + usernameRaw : '';
  const first_name = (chatFirstName || storedFirstName || '').trim();

  let role = 'unknown';
  try {
    const mode = await resolveUiMode(tgId);
    const m = normalizeUiMode(mode);
    role = (m === UI_MODES.BRAND) ? 'brand' : 'creator';
  } catch {}

  return {
    username,
    user_id: String(tgId || ''),
    first_name,
    role,
    bot_name: 'Collabka PR',
  };
}

function applyAdminDmPlaceholders(input, values = {}) {
  const src = String(input ?? '');
  const used = new Set();
  const unknown = new Set();

  const out = src.replace(/{{\s*([a-z_]+)\s*}}/gi, (m, k0) => {
    const key = String(k0 || '').toLowerCase().trim();
    if (!ADMIN_DM_PLACEHOLDER_KEYS.has(key)) {
      unknown.add(key);
      return m;
    }
    used.add(key);
    const v = values?.[key];
    if (v === undefined || v === null) return '';
    return String(v);
  });

  return { text: out, used: [...used], unknown: [...unknown] };
}


function normalizeAdminDmTemplates(obj) {
  const out = {
    version: Math.max(0, Number(obj?.version || 0) || 0),
    updatedAt: String(obj?.updatedAt || ''),
    items: [],
  };

  const src = Array.isArray(obj?.items) ? obj.items : [];
  for (const it of src) {
    const id = String(it?.id || '').trim();
    const label = String(it?.label || '').trim();
const text0 = String(it?.text || '').trim();
if (!id || !label || !text0) continue;
if (id.length > 48 || label.length > 48) continue;
const text = clipCodepoints(text0, TG_SAFE_BODY_MAX).text;
if (!text) continue;
out.items.push({ id, label, text });
  }

  // Hard guarantee: always have at least defaults.
  if (!out.items.length) {
    out.items = DEFAULT_ADMIN_DM_TEMPLATES.map((t) => ({ ...t }));
  }

  return out;
}

async function getAdminDmTemplatesWithMeta() {
  // We intentionally read Redis directly here to detect whether a custom set exists.
  let raw = null;
  try { raw = await redis.get(SYS_KEYS.admin_dm_templates); } catch { raw = null; }

  const isCustom = !!(raw && typeof raw === 'object' && !Array.isArray(raw) && Array.isArray(raw.items));
  const tpls = normalizeAdminDmTemplates(raw);

  // If key existed but was malformed/empty — treat as defaults + not custom.
  const customOk = isCustom && Array.isArray(raw?.items) && raw.items.length > 0;

  return { tpls, isCustom: customOk };
}

async function setAdminDmTemplates(next) {
  const obj = normalizeAdminDmTemplates(next);
  // IMPORTANT: keep items as-is (normalize ensures non-empty). This makes "add" persist defaults too.
  return await setSysObj(SYS_KEYS.admin_dm_templates, {
    version: Math.max(0, Number(next?.version || obj.version || 0) || 0),
    updatedAt: String(next?.updatedAt || obj.updatedAt || ''),
    items: obj.items,
  });
}

async function resetAdminDmTemplates() {
  return await delSysKey(SYS_KEYS.admin_dm_templates);
}

function findAdminDmTemplate(items, tplId) {
  const id = String(tplId || '').trim();
  if (!id) return null;
  return (Array.isArray(items) ? items : []).find((t) => String(t?.id || '') === id) || null;
}

function parseAdminDmTemplateFromText(rawText) {
  const raw = String(rawText || '').replace(/\r/g, '').trim();
  const lines = raw.split('\n');
  const label = String(lines.shift() || '').trim();
  const text = lines.join('\n').trim();
  return { label, text };
}

// --- Admin: Outbox log (Redis-only) (STEP193) ---
// Stores last N admin DM sends (ok/failed) with short snippet. No DB writes.
const ADMIN_OUTBOX_MAX = 200;

function adminOutboxKey() {
  return k(['admin_outbox']);
}

function safeJsonParse(s) {
  if (!s) return null;
  if (typeof s === 'object') return s;
  try { return JSON.parse(String(s)); } catch { return null; }
}

async function appendAdminOutbox(entry) {
  const key = adminOutboxKey();
  const e = (entry && typeof entry === 'object' && !Array.isArray(entry)) ? { ...entry } : {};
  if (!e.ts) e.ts = new Date().toISOString();
  if (!e.id) e.id = 'o' + randomToken(6);
  const payload = JSON.stringify(e);
  try {
    return await lpushTrim(key, payload, ADMIN_OUTBOX_MAX);
  } catch {
    return false;
  }
}

async function getAdminOutboxPage(page = 0, perPage = 8) {
  const key = adminOutboxKey();
  const p = Math.max(0, Number(page) || 0);
  const lim = Math.max(1, Math.min(20, Number(perPage) || 8));
  const start = p * lim;
  const stop = start + lim - 1;
  let total = 0;
  let raw = [];
  try { total = Number(await redis.llen(key)) || 0; } catch { total = 0; }
  try { raw = await redis.lrange(key, start, stop); } catch { raw = []; }
  const items = (Array.isArray(raw) ? raw : []).map((x) => safeJsonParse(x)).filter(Boolean);
  const pages = Math.max(1, Math.ceil((total || 0) / lim));
  return { items, total, page: Math.min(p, pages - 1), pages, perPage: lim, startIndex: start };
}

async function getAdminOutboxItemByIndex(index) {
  const key = adminOutboxKey();
  const i = Math.max(0, Number(index) || 0);
  try {
    if (typeof redis.lindex === 'function') {
      const v = await redis.lindex(key, i);
      return safeJsonParse(v);
    }
  } catch {}
  try {
    const arr = await redis.lrange(key, i, i);
    return safeJsonParse(Array.isArray(arr) ? arr[0] : null);
  } catch {
    return null;
  }
}

async function clearAdminOutbox() {
  try { await redis.del(adminOutboxKey()); return true; } catch { return false; }
}


// --- Admin: User note return context (Redis-only) (STEP204) ---
// Allows opening admin note from contexts like Outbox and returning back without polluting callback data.
// Stored per-admin for short TTL.
function adminUserNoteReturnKey(adminTgId) {
  return k(['adm_unote_ret', String(adminTgId || 0)]);
}

async function setAdminUserNoteReturn(adminTgId, obj, ttlSec = 10 * 60) {
  const aid = Number(adminTgId || 0);
  if (!aid) return false;
  try {
    await redis.set(adminUserNoteReturnKey(aid), obj, { ex: Math.max(60, Number(ttlSec) || 600) });
    return true;
  } catch {
    return false;
  }
}

async function getAdminUserNoteReturn(adminTgId) {
  const aid = Number(adminTgId || 0);
  if (!aid) return null;
  try {
    const v = await redis.get(adminUserNoteReturnKey(aid));
    if (v && typeof v === 'object') return v;
    return safeJsonParse(v);
  } catch {
    return null;
  }
}

async function clearAdminUserNoteReturn(adminTgId) {
  const aid = Number(adminTgId || 0);
  if (!aid) return false;
  try { await redis.del(adminUserNoteReturnKey(aid)); return true; } catch { return false; }
}


function fmtOutboxBtnTime(ts) {
  if (!ts) return '';
  const d = new Date(ts);
  if (!Number.isFinite(d.getTime())) return '';
  try {
    const fmt = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Europe/Moscow', hour: '2-digit', minute: '2-digit', hour12: false });
    return fmt.format(d);
  } catch {
    return '';
  }
}


// --- Admin: User Notes (Redis-only) (STEP194) ---
// Per-user internal note visible only to super-admins. Stored in Redis; no DB tables/migrations.
const ADMIN_USER_NOTE_MAX = 1400;

// Strict allowlist for admin note tags (STEP195). Stored in Redis together with note.
const ADMIN_USER_NOTE_TAGS = [
  { id: 'vip', title: 'VIP' },
  { id: 'suspect_spam', title: 'SPAM?' },
  { id: 'needs_followup', title: 'FOLLOW' },
  { id: 'payments_sensitive', title: 'PAY' },
];

function adminUserNoteTagTitle(id) {
  const t = ADMIN_USER_NOTE_TAGS.find(x => x.id === id);
  return t ? t.title : '';
}

function normalizeAdminUserNoteTags(tags) {
  const arr = Array.isArray(tags) ? tags.map(x => String(x || '').trim()).filter(Boolean) : [];
  const out = [];
  for (const t of ADMIN_USER_NOTE_TAGS) {
    if (arr.includes(t.id)) out.push(t.id);
  }
  // keep any unexpected tags out (strict allowlist)
  return out;
}

function hasAdminUserNoteData(note) {
  if (!note) return false;
  const txt = String(note.text || '').trim();
  const tags = Array.isArray(note.tags) ? note.tags : [];
  return !!txt || tags.length > 0;
}

function adminUserNoteKey(userId) {
  const uid = Number(userId || 0);
  if (!uid) return k(['adm_user_note', '0']);
  return k(['adm_user_note', String(uid)]);
}

function normalizeAdminUserNote(v) {
  if (!v) return null;

  // Backward-compatible: allow plain string (text-only, no tags)
  if (typeof v === 'string') {
    const t = String(v).replace(/\r/g, '').trim();
    if (!t) return null;
    return { text: t, tags: [], updatedAt: '', byAdminTgId: 0, byAdminUsername: '' };
  }

  if (typeof v === 'object' && !Array.isArray(v)) {
    const rawTxt = String(v.text || '').replace(/\r/g, '').trim();
    const tags = normalizeAdminUserNoteTags(v.tags);

    if (!rawTxt && tags.length === 0) return null;

    const text = rawTxt
      ? (rawTxt.length > ADMIN_USER_NOTE_MAX ? (rawTxt.slice(0, ADMIN_USER_NOTE_MAX) + '…') : rawTxt)
      : '';

    return {
      text,
      tags,
      updatedAt: String(v.updatedAt || ''),
      byAdminTgId: Number(v.byAdminTgId || 0) || 0,
      byAdminUsername: String(v.byAdminUsername || ''),
    };
  }

  return null;
}

async function getAdminUserNote(userId) {
  const uid = Number(userId || 0);
  if (!uid) return null;
  try {
    const v = await redis.get(adminUserNoteKey(uid));
    return normalizeAdminUserNote(v);
  } catch {
    return null;
  }
}

// Bulk loader for admin user notes (Redis-only).
// Returns Map<userId, note> only for non-empty notes/tags.
// Best effort: uses MGET if supported, otherwise falls back to per-key GET.
async function getAdminUserNotesBulk(userIds = []) {
  const ids = Array.from(
    new Set(
      (Array.isArray(userIds) ? userIds : [])
        .map((x) => Number(x || 0))
        .filter((x) => Number.isFinite(x) && x > 0)
    )
  );

  const out = new Map();
  if (!ids.length) return out;

  const keys = ids.map((id) => adminUserNoteKey(id));

  try {
    let vals = null;
    if (typeof redis.mget === 'function') {
      vals = await redis.mget(keys);
    } else {
      // Fallback to sequential GET (admin directory page is small).
      vals = [];
      for (const kk of keys) {
        // eslint-disable-next-line no-await-in-loop
        vals.push(await redis.get(kk));
      }
    }

    for (let i = 0; i < ids.length; i++) {
      const note = normalizeAdminUserNote(vals?.[i]);
      if (hasAdminUserNoteData(note)) out.set(ids[i], note);
    }
    return out;
  } catch {
    // Best-effort fallback: per user.
    for (const id of ids) {
      try {
        // eslint-disable-next-line no-await-in-loop
        const note = await getAdminUserNote(id);
        if (hasAdminUserNoteData(note)) out.set(id, note);
      } catch {
        // ignore
      }
    }
    return out;
  }
}

async function upsertAdminUserNote(userId, patch = {}, meta = {}) {
  const uid = Number(userId || 0);
  if (!uid) return false;

  // Load existing (best-effort) to preserve fields not being updated.
  let cur = null;
  try { cur = await getAdminUserNote(uid); } catch { cur = null; }

  let text = cur?.text ? String(cur.text) : '';
  let tags = Array.isArray(cur?.tags) ? cur.tags.map(String) : [];

  if (patch && Object.prototype.hasOwnProperty.call(patch, 'text')) {
    const raw = String(patch.text || '').replace(/\r/g, '').trim();
    text = raw ? (raw.length > ADMIN_USER_NOTE_MAX ? (raw.slice(0, ADMIN_USER_NOTE_MAX) + '…') : raw) : '';
  }

  if (patch && Object.prototype.hasOwnProperty.call(patch, 'tags')) {
    tags = normalizeAdminUserNoteTags(patch.tags);
  } else {
    tags = normalizeAdminUserNoteTags(tags);
  }

  // If everything is empty — delete key (clean state).
  if (!String(text || '').trim() && (!Array.isArray(tags) || tags.length === 0)) {
    try { await redis.del(adminUserNoteKey(uid)); return true; } catch { return false; }
  }

  const obj = {
    text,
    tags,
    updatedAt: new Date().toISOString(),
    byAdminTgId: Number(meta.byAdminTgId || 0) || 0,
    byAdminUsername: String(meta.byAdminUsername || ''),
  };

  try {
    // TTL-LINT: allow-persistent — admin user notes are intended to persist (manual clear).
    await redis.set(adminUserNoteKey(uid), obj);
    return true;
  } catch {
    return false;
  }
}

async function setAdminUserNote(userId, noteText, meta = {}) {
  const raw = String(noteText || '').replace(/\r/g, '').trim();
  if (!raw) return false;
  return await upsertAdminUserNote(userId, { text: raw }, meta);
}

async function toggleAdminUserNoteTag(userId, tagId, meta = {}) {
  const tid = String(tagId || '').trim();
  if (!tid) return false;
  if (!ADMIN_USER_NOTE_TAGS.some(t => t.id === tid)) return false;

  let cur = null;
  try { cur = await getAdminUserNote(userId); } catch { cur = null; }
  const text = cur?.text ? String(cur.text) : '';
  let tags = Array.isArray(cur?.tags) ? cur.tags.map(String) : [];

  if (tags.includes(tid)) tags = tags.filter(x => x !== tid);
  else tags.push(tid);

  tags = normalizeAdminUserNoteTags(tags);
  return await upsertAdminUserNote(userId, { text, tags }, meta);
}

async function clearAdminUserNote(userId) {
  const uid = Number(userId || 0);
  if (!uid) return false;
  try {
    await redis.del(adminUserNoteKey(uid));
    return true;
  } catch {
    return false;
  }
}

function sysNoticeSeenKey(tgId, version) {
  return k(['sys', 'notice', 'seen', String(tgId || 0), String(version || 0)]);
}

async function getSysNoticeAvailabilityForUser(tgId, n) {
  const uid = Number(tgId || 0);
  if (!uid) return { ok: false, audience: 'unknown', reason: 'no_tg_id' };

  const notice = (n && typeof n === 'object') ? n : null;
  if (!notice || !notice.active) return { ok: false, audience: 'unknown', reason: 'inactive' };

  const ver = Number(notice.version || 0);
  if (!Number.isFinite(ver) || ver <= 0) return { ok: false, audience: 'unknown', reason: 'bad_version' };
  if (!notice.text) return { ok: false, audience: 'unknown', reason: 'no_text' };

  // Auto-expire (best-effort): do not show after deadline.
  const nowSec = Math.floor(Date.now() / 1000);
  const expSec = Number(notice.expiresAt || 0);
  if (Number.isFinite(expSec) && expSec > 0 && nowSec >= expSec) return { ok: false, audience: 'unknown', reason: 'expired' };

  // Targeting: all / brand / creator (Redis-only)
  const target = normalizeNoticeTarget(notice.target);
  if (target !== 'all') {
    let ui = 'creator';
    try {
      const raw = await redis.get(k(['ui_mode', uid]));
      ui = String(raw || '').toLowerCase().trim() === 'brand' ? 'brand' : 'creator';
    } catch {
      // If Redis is degraded, fail-closed (avoid accidental spam)
      return { ok: false, audience: 'unknown', reason: 'redis_degraded' };
    }

    let bm = false;
    try { bm = await getBrandManagerMode(uid); } catch { bm = false; }

    const audience = (ui === 'brand' || bm) ? 'brand' : 'creator';
    if (audience !== target) return { ok: false, audience, reason: 'not_target' };

    return { ok: true, audience, reason: '' };
  }

  return { ok: true, audience: 'unknown', reason: '' };
}

async function maybeSendSystemNotice(ctx, cached = {}) {
  try {
    const tgId = Number(ctx?.from?.id || 0);
    if (!tgId) return;

    const chatType = String(ctx?.chat?.type || '');
    if (chatType && chatType !== 'private') return;

    const n = cached?.notice || await getSysNotice();
    const avail = cached?.avail || await getSysNoticeAvailabilityForUser(tgId, n);
    if (!avail.ok) return;

    const ver = Number(n.version || 0);

    const seenKey = sysNoticeSeenKey(tgId, ver);
    try {
      const seen = await redis.get(seenKey);
      if (seen) return;
    } catch {
      // If Redis is degraded, do not spam notices (fail-closed here).
      return;
    }

    // Mark seen BEFORE sending (to keep the promise "once per version" even if send fails/retries).
    try { await redis.set(seenKey, '1', { ex: SYS_NOTICE_SEEN_TTL_SEC }); } catch {}

    const icon = noticeIcon(n.severity);
    const title = noticeTitle(n.severity);
    const safeText = clipCodepoints(String(n.text || ''), TG_SAFE_BODY_MAX).text;

    const msg =
      `${icon} <b>${title}</b>

${escapeHtml(safeText)}` +
      `

<i>Чтобы открыть ещё раз: 📋 Меню → 📣 Актуальное объявление.</i>` +
      `
<i>v${escapeHtml(String(ver))}</i>`;

    const kb = new InlineKeyboard();
    if (n.ctaUrl) {
      const label = clipCodepoints(String(n.ctaLabel || '🔗 Подробнее'), CTA_LABEL_MAX, { ellipsis: '' }).text;
      kb.url(label, String(n.ctaUrl)).row();
    }
    kb.text('📋 Меню', 'a:menu').text('💬 Поддержка', 'a:support').row();
    kb.text('✅ Понятно', 'a:usr_ack|src:admmsg');

    await ctx.reply(msg, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true }).catch(() => {});
  } catch {
    // never block UI on notice failures
  }
}

async function sendStarsInvoice(ctx, { title, description, payload, amount, backCb }) {
  // Stars payments: currency XTR, prices must contain exactly one item.
  const chatId = ctx?.chat?.id;
  const userId = ctx?.from?.id;

  // Put the "cancel/help" hint into the invoice description to avoid sending a second message.
  // Keep it on a new paragraph to make Telegram UI readable.
  const fullDescription = `${description}

Если передумал — жми «📋 Меню».`;

  // Prices must contain exactly one item for Stars.
  // Telegram invoice UI shows it as: ⭐ <amount> <label>
  // Use a clean label to avoid "debug" look.
  const prices = [{ label: 'Stars', amount: Number(amount) }];

  try {
    // IMPORTANT: For sendInvoice, if reply_markup is present and non-empty,
    // the FIRST button MUST be a Pay button (otherwise Telegram returns REPLY_MARKUP_BUY_EMPTY).
    // We'll keep everything in ONE invoice message:
    //   row1: Pay
    //   row2: Back/Menu (regular callback buttons)
    const navRow = [];
    if (backCb && backCb !== 'a:menu' && backCb !== 'a:home') navRow.push({ text: '⬅️ Назад', callback_data: backCb });
    navRow.push({ text: '📋 Меню', callback_data: 'a:menu' });
    navRow.push({ text: '🏠 Home', callback_data: 'a:home' });

    const invoiceMarkup = {
      inline_keyboard: [
        [{ text: `⭐️ Оплатить ${Number(amount)}`, pay: true }],
        navRow,
      ],
    };

    // Stars: currency XTR, provider_token must be empty string
    await ctx.api.raw.sendInvoice({
      chat_id: chatId,
      title,
      description: fullDescription,
      payload,
      provider_token: '',
      currency: 'XTR',
      prices,
      reply_markup: invoiceMarkup,
    });

    return true;
  } catch (e) {
    const desc = String(e?.description || e?.error?.description || e?.message || e);
    console.error('[PAY] sendInvoice(stars) failed', {
      chat_id: chatId ?? null,
      from_id: userId ?? null,
      payload: String(payload || '').slice(0, 64),
      error: desc,
    });

    const isAdmin = isSuperAdminTg(userId);
    const text = isAdmin
      ? `❌ Не удалось отправить Stars-инвойс.
Причина: ${desc}

Проверь:
• Telegram клиент обновлён
• Тестируешь НЕ с аккаунта владельца бота
• Валидный Stars прайс (целое число Stars)
`
      : 'Не удалось отправить инвойс. Проверь, что Telegram обновлён и Stars доступны.';
    try {
      const kb = backCb ? navKb(backCb) : navKb('a:menu');
      await ctx.reply(text, { reply_markup: kb });
    } catch {}
    return false;
  }
}

// -----------------------------
// Payments hardening (Stars)
// -----------------------------

function _isSafeInvoicePayload(payload) {
  const s = String(payload || '');
  // Telegram payload limit is 128 bytes; keep strict and predictable.
  if (!s || s.length > 128) return false;
  // Only allow ASCII alnum + underscore (our payloads are underscore-separated).
  return /^[A-Za-z0-9_]+$/.test(s);
}

function _paymentsPayloadHmacSigHex(payloadNoSig) {
  const key = String(CFG.PAYMENTS_PAYLOAD_HMAC_KEY || '').trim();
  if (!key) return '';
  try {
    return crypto.createHmac('sha256', key).update(String(payloadNoSig || '')).digest('hex');
  } catch {
    return '';
  }
}

function _signStarsInvoiceToken(payloadPrefix, tokenRaw) {
  const key = String(CFG.PAYMENTS_PAYLOAD_HMAC_KEY || '').trim();
  if (!key) return String(tokenRaw || '');
  const sigLen = Math.max(6, Math.min(Number(CFG.PAYMENTS_PAYLOAD_HMAC_LEN || 10) || 10, 16));
  const token = String(tokenRaw || '');
  const payloadNoSig = `${String(payloadPrefix || '')}${token}`;
  const hex = _paymentsPayloadHmacSigHex(payloadNoSig);
  const sig = String(hex || '').slice(0, sigLen);
  if (!sig) return token;
  return `${token}${sig}`;
}


function _parseIntStrict(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  const i = Math.trunc(n);
  if (String(i) !== String(n) && !Number.isInteger(n)) return null;
  return i;
}

function _safeKindFromPayload(payload) {
  const s = String(payload || '');
  if (s.startsWith('founder_')) return 'founder';
  if (s.startsWith('pro_')) return 'pro';
  if (s.startsWith('brand_')) return 'brand_pass';
  if (s.startsWith('bplan_')) return 'brand_plan';
  if (s.startsWith('match_')) return 'matching';
  if (s.startsWith('feat_')) return 'featured';
  if (s.startsWith('offpub_')) return 'official_publish';
  return 'unknown';
}

async function _expectedStarsForInvoicePayload(payload) {
  const s = String(payload || '');
  if (!_isSafeInvoicePayload(s)) return { ok: false, reason: 'bad_payload_chars', expected: 0, kind: _safeKindFromPayload(s) };

  // Split once; validate structure per-kind.
  const parts = s.split('_');
  const kind = _safeKindFromPayload(s);

  // founder_brand_3m_<userId>_<token>
  if (kind === 'founder') {
    if (parts.length < 5) return { ok: false, reason: 'bad_payload_format', expected: 0, kind };
    const productId = parts.slice(0, 3).join('_');
    const userId = _parseIntStrict(parts[3]);
    if (!userId || userId <= 0) return { ok: false, reason: 'bad_user', expected: 0, kind };

    try {
      const st = await getFounderSaleConfig();
      const prod = (st?.products || []).find((x) => String(x.id) === String(productId)) || null;
      const expected = _parseIntStrict(prod?.stars);
      if (!expected || expected <= 0) return { ok: false, reason: 'unknown_product', expected: 0, kind };
      return { ok: true, expected, kind, meta: { productId, userId } };
    } catch {
      // Safe fallback: use base config (no Redis overrides)
      const base = FOUNDER_PRODUCT_DEFS.find((x) => x.id === productId) || null;
      const expected = _parseIntStrict(
        productId === 'founder_brand_3m' ? CFG.FOUNDER_BRAND_3M_PRICE :
        productId === 'founder_brand_12m' ? CFG.FOUNDER_BRAND_12M_PRICE :
        productId === 'founder_creator_12m' ? CFG.FOUNDER_CREATOR_12M_PRICE :
        0
      );
      if (!base || !expected || expected <= 0) return { ok: false, reason: 'unknown_product', expected: 0, kind };
      return { ok: true, expected, kind, meta: { productId, userId } };
    }
  }

  // pro_<wsId>_<userId>_<token> OR legacy pro_<wsId>_<token>
  if (kind === 'pro') {
    if (parts.length < 3) return { ok: false, reason: 'bad_payload_format', expected: 0, kind };
    const wsId = _parseIntStrict(parts[1]);
    if (!wsId || wsId <= 0) return { ok: false, reason: 'bad_ws', expected: 0, kind };
    const expected = _parseIntStrict(CFG.PRO_STARS_PRICE);
    if (!expected || expected <= 0) return { ok: false, reason: 'bad_price', expected: 0, kind };
    // Optional payer userId in new format
    let userId = null;
    if (parts.length >= 4 && /^\d+$/.test(String(parts[2] || ''))) userId = _parseIntStrict(parts[2]);
    return { ok: true, expected, kind, meta: { wsId, userId } };
  }

  
// brand_<userId>_<S|M|L>_<token> (legacy supported: numeric credits token)
if (kind === 'brand_pass') {
  if (parts.length < 4) return { ok: false, reason: 'bad_payload_format', expected: 0, kind };
  const userId = _parseIntStrict(parts[1]);
  if (!userId || userId <= 0) return { ok: false, reason: 'bad_user', expected: 0, kind };

  const packTokenRaw = String(parts[2] || '').trim();
  const packTokenUp = packTokenRaw.toUpperCase();

  // Canonical packs: S/M/L. Legacy: numeric credits token (only if matches known packs).
  let pack = getBrandPack(packTokenUp);
  let legacyCredits = null;
  if (!pack && /^\d+$/.test(packTokenRaw)) {
    legacyCredits = _parseIntStrict(packTokenRaw);
    if (legacyCredits && legacyCredits > 0) {
      pack = BRAND_PACKS.find((p) => Number(_parseIntStrict(p.credits) || 0) === Number(legacyCredits)) || null;
    }
  }

  const expected = _parseIntStrict(pack?.stars);
  if (!expected || expected <= 0) return { ok: false, reason: 'bad_pack', expected: 0, kind };

  return {
    ok: true,
    expected,
    kind,
    meta: {
      userId,
      packId: String(pack?.id || packTokenUp),
      ...(legacyCredits ? { legacyCreditsToken: true, legacyCredits } : {}),
    },
  };
}

// bplan_<userId>_<start|pro>_<token> (legacy supported: basic/max)
if (kind === 'brand_plan') {
  if (parts.length < 4) return { ok: false, reason: 'bad_payload_format', expected: 0, kind };
  const userId = _parseIntStrict(parts[1]);
  if (!userId || userId <= 0) return { ok: false, reason: 'bad_user', expected: 0, kind };

  const planRaw = String(parts[2] || 'start').toLowerCase();
  const plan = (planRaw === 'basic') ? 'start' : (planRaw === 'max') ? 'pro' : planRaw;

  const planDef = BRAND_PLANS.find((pl) => String(pl.id) === String(plan)) || null;
  const expected = _parseIntStrict(planDef?.stars);
  if (!expected || expected <= 0) return { ok: false, reason: 'bad_plan', expected: 0, kind };

  return { ok: true, expected, kind, meta: { userId, plan } };
}
// match_<userId>_<S|M|L>_<token>
  if (kind === 'matching') {
    if (parts.length < 4) return { ok: false, reason: 'bad_payload_format', expected: 0, kind };
    const userId = _parseIntStrict(parts[1]);
    if (!userId || userId <= 0) return { ok: false, reason: 'bad_user', expected: 0, kind };
    const tierId = String(parts[2] || '').toUpperCase();
    const tier = MATCH_TIERS.find((t) => String(t.id) === String(tierId)) || null;
    const expected = _parseIntStrict(tier?.stars);
    if (!expected || expected <= 0) return { ok: false, reason: 'bad_tier', expected: 0, kind };
    return { ok: true, expected, kind, meta: { userId, tierId } };
  }

  // feat_<userId>_<days>_<token>
  if (kind === 'featured') {
    if (parts.length < 4) return { ok: false, reason: 'bad_payload_format', expected: 0, kind };
    const userId = _parseIntStrict(parts[1]);
    if (!userId || userId <= 0) return { ok: false, reason: 'bad_user', expected: 0, kind };
    const days = _parseIntStrict(parts[2]);
    if (!days || days <= 0) return { ok: false, reason: 'bad_days', expected: 0, kind };
    const d = FEATURED_DURATIONS.find((x) => Number(x.days) === Number(days)) || null;
    const expected = _parseIntStrict(d?.stars);
    if (!expected || expected <= 0) return { ok: false, reason: 'bad_duration', expected: 0, kind };
    return { ok: true, expected, kind, meta: { userId, days } };
  }

  // offpub_<userId>_<offerId>_<days>_<token>
  if (kind === 'official_publish') {
    if (parts.length < 5) return { ok: false, reason: 'bad_payload_format', expected: 0, kind };
    const userId = _parseIntStrict(parts[1]);
    const offerId = _parseIntStrict(parts[2]);
    const days = _parseIntStrict(parts[3]);
    if (!userId || userId <= 0) return { ok: false, reason: 'bad_user', expected: 0, kind };
    if (!offerId || offerId <= 0) return { ok: false, reason: 'bad_offer', expected: 0, kind };
    if (!days || days <= 0) return { ok: false, reason: 'bad_days', expected: 0, kind };
    const d = OFFICIAL_DURATIONS.find((x) => Number(x.days) === Number(days)) || null;
    const expected = _parseIntStrict(d?.price);
    if (!expected || expected <= 0) return { ok: false, reason: 'bad_duration', expected: 0, kind };
    return { ok: true, expected, kind, meta: { userId, offerId, days } };
  }

  return { ok: false, reason: 'unknown_kind', expected: 0, kind };
}

export async function _validateStarsPaymentStrict({ payload, currency, totalAmount, payerUserId = null }) {
  const cur = String(currency || 'XTR').toUpperCase();
  if (cur !== 'XTR') return { ok: false, reason: 'bad_currency', expected: 0, kind: _safeKindFromPayload(payload) };

  const paid = _parseIntStrict(totalAmount);
  if (!paid || paid <= 0) return { ok: false, reason: 'bad_amount', expected: 0, kind: _safeKindFromPayload(payload) };

  const exp = await _expectedStarsForInvoicePayload(payload);
  if (!exp.ok) return exp;

  // Optional: verify payload-embedded userId matches the payer.
  if (payerUserId && exp.meta && exp.meta.userId && Number(exp.meta.userId) !== Number(payerUserId)) {
    return { ok: false, reason: 'payer_mismatch', expected: exp.expected, kind: exp.kind, meta: exp.meta };
  }

  if (Number(paid) !== Number(exp.expected)) {
    return { ok: false, reason: 'amount_mismatch', expected: exp.expected, kind: exp.kind, meta: exp.meta, paid };
  }

  return { ok: true, expected: exp.expected, kind: exp.kind, meta: exp.meta, paid };
}

