// STEP308: Hydration tokens for oversized callback_data (>64 bytes).
// - Some flows build long navigation callbacks (filters/return paths) that can exceed Telegram's 64-byte limit.
// - We automatically replace oversized callback_data with a short `a:h|h:<token>` and store the full callback in Redis.
// - Navigation is fail-open: if Redis set/get fails or token is missing, we fall back to Menu/Home and show "Кнопка устарела".
// - Tokens are per-user scoped (key includes tgId) to reduce cross-user reuse.
const TG_CB_MAX_BYTES = 64;
const CB_HYDRATION_TTL_SEC = envInt('CB_HYDRATION_TTL_SEC', 2 * 60 * 60, { min: 60, max: 7 * 24 * 60 * 60 });

function cbByteLen(s) {
  try { return Buffer.byteLength(String(s || ''), 'utf8'); } catch { return String(s || '').length; }
}

function cbHydrationKey(tgId, token) {
  const uid = Number(tgId || 0);
  const t = String(token || '').trim();
  return k(['cbh', uid || 0, t]);
}

function isHydrationToken(token) {
  const t = String(token || '').trim();
  // hex tokens from randomToken(nBytes) => 2*nBytes chars
  return /^[a-f0-9]{8,64}$/i.test(t);
}

async function getHydratedCallbackData(tgId, token) {
  const uid = Number(tgId || 0);
  if (!uid) return null;
  if (!isHydrationToken(token)) return null;
  const key = cbHydrationKey(uid, token);
  try {
    const v = await redis.get(key);
    if (!v) return null;
    return String(v);
  } catch {
    return null;
  }
}

// Best-effort: mutate reply_markup.inline_keyboard in-place (works for grammy InlineKeyboard objects).
async function hydrateReplyMarkupCallbacks(ctx, replyMarkup) {
  const tgId = Number(ctx?.from?.id || 0);
  if (!tgId || !replyMarkup) return replyMarkup;

  const ik = replyMarkup?.inline_keyboard;
  if (!Array.isArray(ik)) return replyMarkup;

  let changed = false;
  for (const row of ik) {
    if (!Array.isArray(row)) continue;
    for (const btn of row) {
      if (!btn || typeof btn !== 'object') continue;
      const cd = btn.callback_data;
      if (!cd) continue;
      const cdStr = String(cd);
      if (cbByteLen(cdStr) <= TG_CB_MAX_BYTES) continue;
      if (cdStr.startsWith('a:h|h:')) continue;

      const token = randomToken(6); // 12 hex chars
      const shortCd = `a:h|h:${token}`;

      // Short cd must always fit.
      if (cbByteLen(shortCd) > TG_CB_MAX_BYTES) {
        btn.callback_data = 'a:menu';
        changed = true;
        continue;
      }

      try {
        await redis.set(cbHydrationKey(tgId, token), cdStr, { ex: CB_HYDRATION_TTL_SEC });
        btn.callback_data = shortCd;
        changed = true;
      } catch {
        // Fail-open: if we can't hydrate, fall back to menu to avoid "button_data_invalid".
        btn.callback_data = 'a:menu';
        changed = true;
      }
    }
  }

  if (changed) {
    try { logger?.info?.({ cid: ctx?.state?.cid, tgId, kind: 'cb_hydrate' }, 'cb_hydrate'); } catch {}
  }

  return replyMarkup;
}

async function safeEditOrReply(ctx, text, extra = {}, preferEdit = true) {
  // STEP308: auto-hydrate oversized callback_data to avoid Telegram 64-byte limit.
  try {
    if (extra && extra.reply_markup) {
      extra = { ...extra, reply_markup: await hydrateReplyMarkupCallbacks(ctx, extra.reply_markup) };
    }
  } catch {}

  // Telegram sometimes rejects edits (old message, deleted message, not modified, etc.).
  // We never want the UI to "do nothing": fallback to sending a new message.
  if (preferEdit && ctx?.callbackQuery?.message) {
    try {
      return await ctx.editMessageText(text, extra);
    } catch (e) {
      const msg = String(e?.description || e?.message || e);
      // If nothing changes — treat as success.
      if (msg.includes('message is not modified')) return;
      // Some messages can't be edited (invoice/service) — fallthrough to reply.
    }
  }
  try {
    return await ctx.reply(text, extra);
  } catch (e) {
    // Last resort: try edit again if reply is blocked (rare).
    if (ctx?.callbackQuery?.message) {
      try {
        return await ctx.editMessageText(text, extra);
      } catch (_) {}
    }
    throw e;
  }
}

// Render helpers: target a specific message as UI surface.
// This avoids overwriting “receipt” messages (admin/system DMs), while keeping edit-based renderers working.
function makeUiCtxForMessage(baseCtx, uiMsg) {
  const chatId = uiMsg?.chat?.id || baseCtx?.chat?.id || baseCtx?.from?.id;
  const messageId = uiMsg?.message_id;
  const chatType = uiMsg?.chat?.type || baseCtx?.chat?.type || 'private';

  const uiMessage = {
    chat: { id: chatId, type: chatType },
    message_id: messageId,
  };

  return {
    api: baseCtx.api,
    from: baseCtx.from,
    chat: { id: chatId, type: chatType },
    state: baseCtx.state,
    // Force safeEditOrReply to edit THIS message.
    callbackQuery: { message: uiMessage, data: 'ui:surface' },
    editMessageText: async (text, extra) => baseCtx.api.editMessageText(chatId, messageId, text, extra),
    editMessageReplyMarkup: async (extra) => baseCtx.api.editMessageReplyMarkup(chatId, messageId, extra),
    reply: async (text, extra) => baseCtx.api.sendMessage(chatId, text, extra),
    answerCallbackQuery: async () => {},
  };
}

// STEP128: Stateless fallback navigation (Redis-degraded safe UI)
// - No DB calls
// - UI-only escape hatch when Redis is degraded.
// - Best-effort: silently clear input-mode state (expectText/draft) to avoid "stuck in input" UX.
//   If Redis is down this is a no-op (errors are swallowed).
const DEGRADED_COPY = Object.freeze({
  line: 'Сейчас кеш/сессии временно недоступны.',
  tips: `Быстрые действия:
• Нажми <code>/start</code> (перезапуск)
• Повтори действие через 1–2 минуты`,
  tipsShort: `Что можно сделать:
• Нажми <code>/start</code> чуть позже
• Повтори действие после восстановления`,
});
function kbStatelessFallback(kind = 'menu') {
  const kb = new InlineKeyboard();
  const showAll = kind === 'all';
  if (showAll || kind !== 'menu') kb.text('📋 Меню', 's:menu');
  if (showAll || kind !== 'home') kb.text('🏠 Home', 's:home');
  if (showAll || kind !== 'help') kb.text('🧭 Помощь', 's:help');
  kb.row().text('🔄 Сбросить ввод', 's:reset_input');
  return kb;
}

async function clearInputState(tgId) {
  const uid = Number(tgId || 0);
  if (!uid) return { ok: true, uid: 0 };
  let ok1 = true;
  let ok2 = true;
  try { await redis.del(k(['expectText', uid])); } catch { ok1 = false; }
  try { await redis.del(k(['draft', uid])); } catch { ok2 = false; }
  return { ok: ok1 && ok2, uid, ok1, ok2 };
}

async function handleStatelessCallback(ctx, p) {
  const a = String(p?.a || '');
  if (!a.startsWith('s:')) return false;

  const tgId = Number(ctx?.from?.id || 0);
  const clr = await clearInputState(tgId);

  const key = a.slice(2);

  if (key === 'reset_input') {
    const ok = !!(clr && clr.ok);
    const msg = ok
      ? `✅ <b>Ввод сброшен</b>

📋 <b>Меню (безопасный режим)</b>

${DEGRADED_COPY.line}

${DEGRADED_COPY.tips}`
      : `⚠️ <b>Сброс не выполнен</b>

${DEGRADED_COPY.line}

${DEGRADED_COPY.tipsShort}`;

    await safeEditOrReply(ctx, msg, { parse_mode: 'HTML', reply_markup: kbStatelessFallback('menu') });
    return true;
  }

  if (key === 'home') {
    await safeEditOrReply(
      ctx,
      `🏠 <b>Home (безопасный режим)</b>

${DEGRADED_COPY.line}

${DEGRADED_COPY.tips}

Навигация:
• Открой «Меню (безопасный режим)»`,
      { parse_mode: 'HTML', reply_markup: kbStatelessFallback('home') }
    );
    return true;
  }

  if (key === 'help') {
    await safeEditOrReply(
      ctx,
      `🧭 <b>Помощь (безопасный режим)</b>

Почему так:
• ${DEGRADED_COPY.line} Поэтому опасные действия блокируются.

Как вернуться к обычной работе:
1) Подожди 1–2 минуты
2) Нажми <code>/start</code>

Если ты админ и нужно срочно:
• Открой админку и используй break-glass только по необходимости`,
      { parse_mode: 'HTML', reply_markup: kbStatelessFallback('help') }
    );
    return true;
  }

  // default: menu
  await safeEditOrReply(
    ctx,
    `📋 <b>Меню (безопасный режим)</b>

${DEGRADED_COPY.line}

${DEGRADED_COPY.tips}`,
    { parse_mode: 'HTML', reply_markup: kbStatelessFallback('menu') }
  );
  return true;
}








async function safeDeleteIncomingUserMessage(ctx) {
  // Best-effort: remove the incoming user message after we consumed it
  // to keep the chat clean in text-input flows.
  //
  // Telegram allows bots to delete incoming messages in private chats
  // (see deleteMessage limitations in Bot API docs). We still treat this
  // as "best effort" and never fail the UX if deletion is not possible.
  try {
    const msg =
      ctx?.message ||
      ctx?.msg ||
      ctx?.update?.message ||
      ctx?.update?.edited_message ||
      null;

    const chat = msg?.chat || ctx?.chat || null;
    const chatId = chat?.id || null;
    const mid = msg?.message_id || null;

    if (!chatId || !mid) return false;

    // Only attempt cleanup in private chats (or when chat.type is missing).
    const ctype = String(chat?.type || '').toLowerCase();
    if (ctype && ctype !== 'private') return false;

    // Prefer grammY helper when available (targets the update message).
    try {
      if (typeof ctx.deleteMessage === 'function') {
        await ctx.deleteMessage();
        return true;
      }
    } catch (_) {}

    // Raw Bot API fallbacks
    try {
      await ctx.api.deleteMessage(chatId, mid);
      return true;
    } catch (_) {}

    try {
      if (typeof ctx.api.deleteMessages === 'function') {
        await ctx.api.deleteMessages(chatId, [mid]);
        return true;
      }
    } catch (_) {}

    // Business connection fallback (if present)
    try {
      const bcid = msg?.business_connection_id || msg?.businessConnectionId || null;
      if (bcid && typeof ctx.api.deleteBusinessMessages === 'function') {
        await ctx.api.deleteBusinessMessages(bcid, [mid]);
        return true;
      }
    } catch (_) {}

    return false;
  } catch (_) {
    return false;
  }
}





async function uiGuard(ctx, tag, fn) {
  try {
    return await fn();
  } catch (e) {
    console.error(`[UI:${tag}]`, e);
    try {
      await safeEditOrReply(ctx, `⚠️ <b>Ошибка</b>

Что-то пошло не так. Нажми «📋 Меню» и попробуй ещё раз.`, {
        parse_mode: 'HTML',
        reply_markup: navKb('a:menu'),
        disable_web_page_preview: true,
      });
    } catch (_) {}
  }
}


// -----------------------------
// BX Navigation helpers (home/return context)
// h: home anchor (mm=main_menu, mn=role hub, bo=bx_open)
// r: return anchor for nested screens (bf=bx_feed, mm/mn/bo)
// -----------------------------

const BX_HOME = { MAIN_MENU: 'mm', MENU: 'mn', BX_OPEN: 'bo' };

const UI_HOME_TTL_SEC = 7 * 24 * 3600;

function uiHomeKey(uid) {
  return k(['ui_home', Number(uid || 0)]);
}

async function setUiHome(uid, home) {
  try {
    const id = Number(uid || 0);
    if (!id) return;
    const h = normBxHome(home, BX_HOME.MENU);
    await redis.set(uiHomeKey(id), h, { ex: UI_HOME_TTL_SEC });
  } catch {
    // ignore
  }
}

async function getUiHome(uid) {
  try {
    const id = Number(uid || 0);
    if (!id) return null;
    const v = await redis.get(uiHomeKey(id));
    const s = String(v || '').trim();
    if (!s) return null;
    return normBxHome(s, BX_HOME.MENU);
  } catch {
    return null;
  }
}

async function resolveBxHomeFromUi(ctx, wsId, rawH, fallback) {
  const direct = String(rawH || '').trim();
  if (direct) return normBxHome(direct, fallback);
  const uid = ctx?.from?.id ? Number(ctx.from.id) : 0;
  if (uid) {
    const saved = await getUiHome(uid);
    if (saved) return normBxHome(saved, fallback);
  }
  // Last-resort default
  return normBxHome(fallback, BX_HOME.MENU);
}

function normBxHome(h, fallback = BX_HOME.MENU) {
  const v = String(h || '').trim().toLowerCase();
  if (v === BX_HOME.MAIN_MENU || v === BX_HOME.MENU || v === BX_HOME.BX_OPEN) return v;
  return fallback;
}

function normBxRet(r, fallback = BX_HOME.BX_OPEN) {
  const v = String(r || '').trim().toLowerCase();
  if (v === 'bf' || v === 'bs' || v === BX_HOME.MAIN_MENU || v === BX_HOME.MENU || v === BX_HOME.BX_OPEN) return v;
  return fallback;
}


function normBxTagFilterKey(raw) {
  const v = String(raw || '').trim().toLowerCase();
  if (!v) return '';
  if (v in {'goals':1,'goal':1,'goalstags':1,'goals_tags':1,'goals-tags':1}) return 'goals';
  if (v in {'req':1,'reqs':1,'requirement':1,'requirements':1,'reqtags':1,'req_tags':1,'req-tags':1}) return 'req';
  return '';
}

function bxHomeCb(wsId, h) {
  const home = normBxHome(h, BX_HOME.MENU);
  if (home === BX_HOME.MAIN_MENU) return 'a:main_menu';
  if (home === BX_HOME.BX_OPEN) return `a:bx_open|ws:${Number(wsId || 0)}`;
  return 'a:menu';
}

function bxReturnCb(wsId, page, h, r) {
  const home = normBxHome(h, BX_HOME.MENU);
  const ret = normBxRet(r, home === BX_HOME.BX_OPEN ? BX_HOME.BX_OPEN : home);
  if (ret === 'bf') return `a:bx_feed|ws:${Number(wsId || 0)}|p:${Number(page || 0)}|h:${home}`;
  if (ret === 'bs') return `a:bx_smart|ws:${Number(wsId || 0)}|h:${home}`;
  if (ret === BX_HOME.MAIN_MENU) return 'a:main_menu';
  if (ret === BX_HOME.BX_OPEN) return `a:bx_open|ws:${Number(wsId || 0)}`;
  return 'a:menu';
}

function expectBackCb(exp) {
  if (!exp || !exp.type) return 'a:menu';
  if (exp.backCb) return String(exp.backCb);
  if (exp.back) return String(exp.back);
  const t = String(exp.type || '');
  const wsId = exp.wsId ? Number(exp.wsId) : null;
  const gwId = exp.gwId ? Number(exp.gwId) : null;

  if (t === 'curator_username') return wsId ? `a:cur_manage|ws:${wsId}` : 'a:menu';
  if (t === 'bm_username') return 'a:brand_team|ws:0';
  if (t === 'curator_note') return (wsId && gwId) ? `a:cur_gw_open|ws:${wsId}|i:${gwId}` : 'a:cur_home';

  if (t.startsWith('folder_')) return wsId ? `a:folders_home|ws:${wsId}` : 'a:menu';

  if (t.startsWith('brand_')) return 'a:bx_open|ws:0';
  if (t.startsWith('verify_')) return 'a:verify_home';

  if (t.startsWith('wsp_')) return wsId ? `a:wsp_open|ws:${wsId}` : 'a:ws_list';
  if (t.startsWith('gw_')) return wsId ? `a:gw_list_ws|ws:${wsId}` : 'a:gw_list';
  if (t.startsWith('bx_')) return exp.back ? String(exp.back) : 'a:bx_open|ws:0';

  if (t.startsWith('mod_verif_')) return 'a:mod_home';

  return 'a:menu';
}

async function setActiveWorkspace(tgId, wsId) {
  try {
    await redis.set(k(['active_ws', tgId]), String(wsId), { ex: 30 * 24 * 3600 });
  } catch {
    // ignore
  }
}
async function getActiveWorkspace(tgId) {
  try {
    const v = await redis.get(k(['active_ws', tgId]));
    const n = Number(v);
    return n > 0 ? n : null;
  } catch {
    return null;
  }
}


async function resolveCurrentWorkspaceForOwner(ownerUserId, tgId, opts = {}) {
  let wsList = Array.isArray(opts.wsList) ? opts.wsList : await listWorkspacesCached(ownerUserId);
  if (!wsList.length) {
    try { wsList = await db.listWorkspaces(ownerUserId); } catch { wsList = []; }
  }
  const activeWsList = (wsList || []).filter((w) => !isWorkspaceDisconnected(w));
  if (!activeWsList.length) return { wsList, activeWsList, current: null };

  const preferred = Number(opts.preferredWsId || 0);
  let current = null;
  if (preferred > 0) {
    current = activeWsList.find((w) => Number(w.id) === preferred) || null;
  }
  if (!current) {
    const active = await getActiveWorkspace(tgId);
    if (active) current = activeWsList.find((w) => Number(w.id) === Number(active)) || null;
  }
  if (!current) {
    current = activeWsList[0] || null;
  }
  if (current && Number(current.id) > 0) {
    await setActiveWorkspace(tgId, Number(current.id));
  }
  return { wsList, activeWsList, current };
}

