  try { isPro = await db.isWorkspacePro(Number(wsId)); } catch { isPro = false; }
  const maxFree = Number(CFG.WORKSPACE_CURATORS_MAX_FREE || 1);
  const maxPro = Number(CFG.WORKSPACE_CURATORS_MAX_PRO || 5);
