// Brand Team access: unlock after basic profile + Brand Pass / Brand Plan
function brandTeamLockedKb(st, backCb = 'a:menu', wsId = 0, ret = 'menu') {
  const kb = new InlineKeyboard();

  const profileIncomplete = !!(st?.missingBasic && st.missingBasic.length);
  const planInactive = !st?.teamPaid;

  if (profileIncomplete) {
    kb.text('🧩 Заполнить профиль бренда', `a:brand_profile_edit|ws:${wsId}|ret:${ret === 'bx' ? 'brand_team_bx' : 'brand_team'}`).row();
  } else {
    kb.text('🏷 Профиль бренда', 'a:brand_profile|ws:0|ret:brand_team').row();
  }

  if (planInactive) {
    kb.text('⭐️ Подключить Brand Plan', `a:brand_plan|ws:${wsId}|ret:${ret === 'bx' ? 'brand_team_bx' : 'brand_team'}`).row();
  }

  kb.row()
    .text('🔄 Проверить снова', `a:brand_team|ws:${wsId}|ret:${ret}`)
    .text('ℹ️ Почему так?', `a:brand_team_help|ws:${wsId}|ret:${ret}`);

  kb.row().text('⬅️ Назад', backCb).text('🏠 Home', 'a:home');
  return kb;
}


async function getBrandTeamGateState(ownerUserId) {
  const prof = await safeBrandProfiles(
    () => db.getBrandProfile(ownerUserId),
    async () => ({ __missing_relation: true })
  );

  if (prof && prof.__missing_relation) {
    return {
      ok: false,
      missingRelation: true,
      basicDone: 0,
      missingBasic: ['Название', 'Ниши', 'Контакт', 'Ссылка'],
      teamPaid: false
    };
  }

  const p = prof || {};
  const meta = parseBrandMeta(p.meta);
  const hasNicheKey = !!String(meta?.niche_key || '').trim();
  const hasNicheText = !!String(p.niche || '').trim();
  const nicheDone = hasNicheKey || hasNicheText;
  const basic = [
    { key: 'brand_name', label: 'Название' },
    { key: 'niche', label: 'Ниши' },
    { key: 'contact', label: 'Контакт' },
    { key: 'brand_link', label: 'Ссылка' }
  ];

  const basicDone = [
    !!String(p.brand_name || '').trim(),
    nicheDone,
    !!String(p.contact || '').trim(),
    !!String(p.brand_link || '').trim()
  ].filter(Boolean).length;
  const missingBasic = [
    !String(p.brand_name || '').trim() ? 'Название' : null,
    !nicheDone ? 'Ниши' : null,
    !String(p.contact || '').trim() ? 'Контакт' : null,
    !String(p.brand_link || '').trim() ? 'Ссылка' : null,
  ].filter(Boolean);

  let teamPaid = false;
  try {
    teamPaid = await db.hasBrandTeamUnlockPurchase(ownerUserId);
  } catch {
    teamPaid = false;
  }
  if (!teamPaid) {
    try {
      teamPaid = await db.isBrandPlanActive(ownerUserId);
    } catch {
      teamPaid = false;
    }
  }

  const ok = isBrandBasicComplete(p) && teamPaid;
  return { ok, p, basicDone, missingBasic, teamPaid };
}

/**
 * Manager limit: 3 for any brand with a purchase.
 */
async function brandManagerLimitInfo(brandUserId) {
  const max = 3;
  let count = 0;
  try { count = (await db.listBrandManagers(brandUserId)).length; } catch {}
  return { max, count, canAdd: count < max };
}

async function ensureBrandTeamUnlocked(ctx, u, { edit = true, backCb = 'a:menu', wsId = 0, ret = 'menu' } = {}) {
  // Owner-only: managers cannot manage team
  const bm = await resolveBmBrandContext(ctx, u, { requirePickWhenMissingActive: false });

  if (bm.dbMissing) {
    const kb = navKb('a:menu');
    const text = `⚠️ <b>Нужна миграция 026_brand_managers</b>\n\nВ Neon должна быть таблица <code>brand_managers</code>.`;
    if (edit) await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
    else await ctx.reply(text, { parse_mode: 'HTML', reply_markup: kb });
    return null;
  }

  if (bm.enabled && bm.brandUserId !== u.id) {
    const kb = navKb('a:menu');
    const text = `⛔ <b>Только владелец бренда</b>\n\nМенеджер не может управлять «👔 Менеджеры бренда».`;
    if (edit) await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
    else await ctx.reply(text, { parse_mode: 'HTML', reply_markup: kb });
    return null;
  }

  const st = await getBrandTeamGateState(u.id);

  if (st.missingRelation) {
    const kb = navKb('a:menu');
    const text = `⚠️ <b>Нужна миграция 024_brand_profiles</b>\n\nВ Neon должна быть таблица <code>brand_profiles</code>.`;
    if (edit) await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
    else await ctx.reply(text, { parse_mode: 'HTML', reply_markup: kb });
    return null;
  }

  if (!st.ok) {
    const profileOk = !(st.missingBasic && st.missingBasic.length);
    const planOk = !!st.teamPaid;

    const profileLine = profileOk
      ? '✅ Профиль бренда: <b>готов</b> (4/4)'
      : `❌ Профиль бренда: <b>${st.basicDone}/4</b> — не хватает: <b>${escapeHtml(st.missingBasic.join(', '))}</b>`;

    const planLine = planOk
      ? '✅ Brand Plan: <b>активен</b> (покупка или подаренный)'
      : '❌ Brand Plan: <b>не активен</b>';

    const text = `👔 <b>Менеджеры бренда</b>

` +
      `<i>Кнопка всегда видна.</i> Доступ откроется, когда выполнены условия:

` +
      `${profileLine}
${planLine}

` +
      `Нажми кнопку ниже — я открою нужный экран.

<i>После оплаты или заполнения профиля вернись сюда и нажми «🔄 Проверить снова» — или просто открой «👔 Менеджеры бренда» ещё раз.</i>`;

    const kb = brandTeamLockedKb(st, backCb, wsId, ret);
    if (edit) await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
    else await ctx.reply(text, { parse_mode: 'HTML', reply_markup: kb });
    return null;
  }

  return st;
}

