function normalizeIgHandle(input) {
  const raw = String(input || '').trim();
  if (!raw) return null;
  let s = raw.replace(/\s+/g, '');
  s = s.replace(/^@/, '');

  // instagram.com/<handle>
  const m = s.match(/instagram\.com\/([^\/\?\#]+)/i);
  if (m) {
    const seg = String(m[1] || '').trim();
    const bad = ['reel', 'p', 'tv', 'stories', 'explore'].includes(seg.toLowerCase());
    if (bad) return null;
    const hm = seg.replace(/^@/, '').match(/^([A-Za-z0-9._]{2,30})$/);
    return hm ? hm[1] : null;
  }

  // If it's some other URL — reject
  if (/^https?:\/\//i.test(s)) return null;

  // plain handle
  const hm = s.match(/^([A-Za-z0-9._]{2,30})$/);
  if (!hm) return null;
  const bad = ['reel', 'p', 'tv', 'stories', 'explore'].includes(hm[1].toLowerCase());
  if (bad) return null;
  return hm[1];
}


// STEP106: Structured contacts (profile_contacts) — validation/normalization helpers.
const PROFILE_CONTACTS_KEYS_V1 = ['tg', 'email', 'phone', 'site', 'other', 'ig'];

function wsProfileContactsObj(ws) {
  const raw = ws?.profile_contacts;
  let o = {};
  if (raw && typeof raw === 'object') o = raw;
  else if (typeof raw === 'string') {
    try { o = JSON.parse(raw); } catch { o = {}; }
  }

  const out = {};
  for (const k of PROFILE_CONTACTS_KEYS_V1) {
    const v = o?.[k];
    if (v === null || v === undefined) continue;

    // Preserve IG verification subtree (object) so editing tg/email/phone/site won't wipe it.
    if (k === 'ig') {
      if (v && typeof v === 'object') {
        const ig = {};
        const handle = v.handle ? normalizeIgHandle(v.handle) : null;
        if (handle) ig.handle = handle;

        // URL is derived from handle if not provided
        if (v.url) {
          const url = String(v.url || '').trim();
          if (url) ig.url = url;
        } else if (handle) {
          ig.url = `https://www.instagram.com/${handle}/`;
        }

        if (v.verified === true) ig.verified = true;
        if (v.verified_at) ig.verified_at = String(v.verified_at);
        if (v.verified_method) ig.verified_method = String(v.verified_method);

        if (v.pending && typeof v.pending === 'object') {
          const code = String(v.pending.code || '').trim().toUpperCase();
          const expiresAt = String(v.pending.expires_at || '').trim();
          if (code && expiresAt) ig.pending = { code, expires_at: expiresAt };
        }

        // Keep Level A subtree as-is (tokens are stored encrypted).
        if (v.graph && typeof v.graph === 'object') {
          ig.graph = v.graph;
        }

        if (Object.keys(ig).length) out.ig = ig;
      }
      continue;
    }

    const s = String(v).trim();
    if (!s) continue;
    out[k] = s;
  }
  return out;
}

function wsProfileContactsCount(o, keys = ['tg', 'email', 'phone', 'site']) {
  const obj = o && typeof o === 'object' ? o : {};
  let n = 0;
  for (const k of keys) {
    const v = obj[k];
    if (v !== null && v !== undefined && String(v).trim().length) n++;
  }
  return n;
}

function normalizeTgUsername(input) {
  const raw = String(input || '').trim();
  if (!raw) return null;
  let s = raw.replace(/\s+/g, '');
  s = s.replace(/^@/, '');

  // t.me/<username>
  const tm = s.match(/(?:https?:\/\/)?t\.me\/([A-Za-z0-9_]{5,32})/i);
  if (tm) s = String(tm[1] || '').trim();

  const m = s.match(/^([A-Za-z0-9_]{5,32})$/);
  if (!m) return null;
  // Avoid obviously invalid leading underscore
  if (m[1].startsWith('_')) return null;
  return m[1].toLowerCase();
}

function normalizeEmailAddr(input) {
  const raw = String(input || '').trim();
  if (!raw) return null;
  const s = raw.replace(/\s+/g, '').toLowerCase();
  if (s.length > 120) return null;
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s)) return null;
  return s;
}

function normalizePhoneE164Like(input) {
  const raw = String(input || '').trim();
  if (!raw) return null;
  const digits = raw.replace(/[^\d]+/g, '');
  if (digits.length < 10 || digits.length > 15) return null;
  return '+' + digits;
}

function normalizeWebsiteUrl(input) {
  const raw = String(input || '').trim();
  if (!raw) return { ok: false, err: 'empty' };

  let s = raw.replace(/\s+/g, '');
  s = s.replace(/^[<]+|[>]+$/g, '');
  // Avoid storing telegram deep links or t.me here.
  if (s.startsWith('@') || /^tg:\/\//i.test(s) || /(?:^|\/\/)t\.me\//i.test(s) || /telegram\.me\//i.test(s)) {
    return { ok: false, err: 'telegram' };
  }

  // If no scheme, add https://
  if (!/^https?:\/\//i.test(s)) {
    // If has another scheme — reject (javascript:, ftp:, etc)
    if (/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(s)) return { ok: false, err: 'scheme' };
    s = 'https://' + s.replace(/^\/+/, '');
  }

  if (s.length > 300) return { ok: false, err: 'too_long' };

  try {
    const u = new URL(s);
    if (!['http:', 'https:'].includes(u.protocol)) return { ok: false, err: 'scheme' };
    if (!u.hostname) return { ok: false, err: 'host' };
    // normalize trailing slash (keep root slash)
    let out = u.toString();
    if (out.endsWith('/') && u.pathname === '/' && !u.search && !u.hash) out = out.slice(0, -1);
    return { ok: true, value: out };
  } catch {
    return { ok: false, err: 'invalid' };
  }
}

function parseUrlsFromText(input, max = 3) {
  const text = String(input || '');
  const re = /(https?:\/\/[^\s<>"']+)/gi;
  const out = [];
  let m;
  while ((m = re.exec(text))) {
    let u = String(m[1] || '').trim();
    // strip trailing punctuation
    u = u.replace(/[)\],.!?]+$/g, '');
    if (!u) continue;
    if (!out.includes(u)) out.push(u);
    if (out.length >= max) break;
  }
  return out;
}

function detectLegacyContactForMigration(legacyInput) {
  const raw = String(legacyInput || '').trim();
  if (!raw) return { ok: false, reason: 'empty' };
  if (raw.length > 600) return { ok: false, reason: 'too_long' };

  // Collect candidates. We avoid "smart" extraction: if multiple different types found → ambiguous.
  const tg = new Set();
  const email = new Set();
  const phone = new Set();
  const site = new Set();

  // Telegram: @user and t.me/user
  {
    const reAt = /@([A-Za-z0-9_]{5,32})/g;
    let m;
    while ((m = reAt.exec(raw))) {
      const v = normalizeTgUsername('@' + (m[1] || ''));
      if (v) tg.add(v);
    }
    const reTm = /(?:https?:\/\/)?(?:t\.me|telegram\.me)\/([A-Za-z0-9_]{5,32})/gi;
    while ((m = reTm.exec(raw))) {
      const v = normalizeTgUsername('https://t.me/' + (m[1] || ''));
      if (v) tg.add(v);
    }
  }

  // Email
  {
    const re = /\b[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']{2,}\b/g;
    const ms = raw.match(re) || [];
    for (const x of ms) {
      const v = normalizeEmailAddr(x);
      if (v) email.add(v);
    }
  }

  // Phone-like (we validate via normalizePhoneE164Like)
  {
    const re = /(\+?\d[\d\s().-]{8,}\d)/g;
    let m;
    while ((m = re.exec(raw))) {
      const v = normalizePhoneE164Like(m[1]);
      if (v) phone.add(v);
    }
  }

  // Website: urls with scheme, plus simple domain tokens (no scheme)
  {
    const urls = parseUrlsFromText(raw, 5);
    for (const u of urls) {
      const r = normalizeWebsiteUrl(u);
      if (r.ok) site.add(r.value);
    }

    // If no explicit urls, allow a single domain token like example.com
    if (!site.size) {
      const tokens = raw.split(/\s+/).filter(Boolean);
      const domainish = tokens.filter(t => /\.[A-Za-z]{2,}/.test(t) && !t.startsWith('@'));
      if (domainish.length === 1) {
        const r = normalizeWebsiteUrl(domainish[0]);
        if (r.ok) site.add(r.value);
      }
    }
  }

  const counts = {
    tg: tg.size,
    email: email.size,
    phone: phone.size,
    site: site.size,
  };
  const nonZero = Object.entries(counts).filter(([, n]) => n > 0);

  if (!nonZero.length) return { ok: false, reason: 'no_match' };
  if (nonZero.length > 1) return { ok: false, reason: 'ambiguous_multi_types', counts };

  const [kind, n] = nonZero[0];
  if (n !== 1) return { ok: false, reason: 'ambiguous_multi_values', kind, count: n };

  const pick = (set) => Array.from(set.values())[0];
  if (kind === 'tg') return { ok: true, key: 'tg', value: pick(tg) };
  if (kind === 'email') return { ok: true, key: 'email', value: pick(email) };
  if (kind === 'phone') return { ok: true, key: 'phone', value: pick(phone) };
  if (kind === 'site') return { ok: true, key: 'site', value: pick(site) };
  return { ok: false, reason: 'unknown' };
}

function extractFirstContact(input) {
  const text = String(input || '');
  const m = text.match(/@([a-zA-Z0-9_]{5,})/);
  if (m) return '@' + m[1];
  const tm = text.match(/(?:https?:\/\/)?t\.me\/([a-zA-Z0-9_]{5,})/i);
  if (tm) return '@' + tm[1];
  const urls = parseUrlsFromText(text, 1);
  if (urls.length) return urls[0];
  return null;
}

function wsProfileKb(wsId, ws) {
  const vCount = Array.isArray(ws.profile_verticals) ? ws.profile_verticals.length : 0;
  const fCount = Array.isArray(ws.profile_formats) ? ws.profile_formats.length : 0;
  const contactsObj = wsProfileContactsObj(ws);
  const cCount = wsProfileContactsCount(contactsObj, ['tg', 'email', 'phone', 'site']);

  // UX: "Предпросмотр" — главный CTA, дальше парные кнопки по смыслу.
  const kb = new InlineKeyboard()
    .text('👁 Предпросмотр', `a:wsp_preview|ws:${wsId}`)
    .row()
    .text(`🏷 Ниши (${vCount}/3)`, `a:ws_prof_verticals|ws:${wsId}`)
    .text(`🎬 Форматы (${fCount}/5)`, `a:ws_prof_formats|ws:${wsId}`)
    .row()
    .text('✏️ Название', `a:ws_prof_edit|ws:${wsId}|f:title`)
    .text('✏️ Контакт', `a:ws_prof_edit|ws:${wsId}|f:contact`)
    .row()
    .text(`📇 Контакты (${cCount}/4)`, `a:ws_prof_contacts|ws:${wsId}`)
    .row()
    .text('📸 Instagram', `a:ws_prof_edit|ws:${wsId}|f:ig`)
    .text('🔗 Портфолио', `a:ws_prof_edit|ws:${wsId}|f:portfolio`)
    .row()
    .text('✏️ Гео', `a:ws_prof_edit|ws:${wsId}|f:geo`)
    .text('📝 Описание', `a:ws_prof_edit|ws:${wsId}|f:about`)
    .row()
    .text('🧹 Сбросить витрину', `a:ws_prof_reset|ws:${wsId}`)
    .row()
    .text('🧩 Режим', `a:ws_prof_mode|ws:${wsId}`)
    .text('📌 IG шаблоны', `a:ws_ig_templates|ws:${wsId}`)
    .row()
    .text('⬅️ Назад', `a:ws_open|ws:${wsId}`).text('📋 Меню', 'a:menu')
    .row()
    .text('🏠 Home', 'a:home');

  return kb;
}

