async function renderWsIgVerifyStatus(ctx, ownerUserId, wsId, opts = {}) {
  const ret = String(opts.ret || 'ws_profile');
  const ws = isSuperAdminTg(ctx.from?.id) ? await db.getWorkspaceAny(wsId) : await db.getWorkspace(ownerUserId, wsId);
  if (!ws) {
    await safeEditOrReply(ctx, '⚠️ Канал не найден или нет доступа.', { reply_markup: navKb('a:ws_list') });
    return;
  }

  const igMeta = wsIgMeta(ws) || {};
  const verified = igMeta.verified === true;
  const pending = (igMeta.pending && typeof igMeta.pending === 'object') ? igMeta.pending : null;

  if (verified) {
    try { await ctx.answerCallbackQuery({ text: '✅ IG verified', show_alert: false }); } catch {}
  } else if (pending?.code) {
    try { await ctx.answerCallbackQuery({ text: '⏳ Ожидаем подтверждение', show_alert: false }); } catch {}
  } else {
    try { await ctx.answerCallbackQuery({ text: 'Статус: —', show_alert: false }); } catch {}
  }

  // NOTE: In this STEP we do NOT call IG API and do NOT auto-verify.
  // Real check will be done in a cron tick (next STEP).

  await renderWsIgVerifyStart(ctx, ownerUserId, wsId, { ret, handleHint: opts?.handleHint || null });
}



function hasText(v) {
  return v !== null && v !== undefined && String(v).trim().length > 0 && String(v).trim() !== '—';
}

function calcWsProfileProgress(ws) {
  // Core fields that most сильно влияют на конверсию
  const igOk = hasText(ws.profile_ig);
  const contactsObj = wsProfileContactsObj(ws);
  const structuredOk = wsProfileContactsCount(contactsObj, ['tg', 'email', 'phone', 'site']) > 0;
  const contactOk = structuredOk || hasText(ws.profile_contact);
  const verticalsOk = Array.isArray(ws.profile_verticals) && ws.profile_verticals.length > 0;
  const formatsOk = Array.isArray(ws.profile_formats) && ws.profile_formats.length > 0;
  const portsRaw = Array.isArray(ws.profile_portfolio_urls) ? ws.profile_portfolio_urls : [];
  const ports = portsRaw.map((x) => String(x || '').trim()).filter(Boolean);
  const portfolioOk = ports.length > 0;
  const aboutOk = hasText(ws.profile_about);

  const checks = [
    { key: 'ig', ok: igOk },
    { key: 'contact', ok: contactOk },
    { key: 'verticals', ok: verticalsOk },
    { key: 'formats', ok: formatsOk },
    { key: 'portfolio', ok: portfolioOk },
    { key: 'about', ok: aboutOk },
  ];

  const total = checks.length;
  const done = checks.filter(x => x.ok).length;
  const percent = Math.round((done / total) * 100);

  const missing = [];
  if (!portfolioOk) missing.push('🔗 Портфолио: добавь 1–3 ссылки — <b>самый сильный буст конверсии</b>');
  if (!formatsOk) missing.push('🎬 Форматы: выбери 3–5 (брендам проще выбрать)');
  if (!verticalsOk) missing.push('🏷 Ниши: выбери до 3 (точнее матчи)');
  if (!igOk) missing.push('📸 Instagram: укажи @ или ссылку (доверие)');
  if (!contactOk) missing.push('✉️ Контакты: заполни «📇 Контакты (структурно)» или «Контакт»');
  if (!aboutOk) missing.push('📝 Описание: 1–2 строки, что именно ты снимаешь');

  const nextHint = !portfolioOk
    ? '💡 Добавь 1 ссылку портфолио — это обычно сильнее всего повышает конверсию.'
    : '💡 Держи 1–3 лучших ссылок в портфолио — бренд решает по примерам.';

  return { total, done, percent, missing, portfolioOk, igOk, contactOk, verticalsOk, formatsOk, aboutOk, nextHint };
}


async function renderWsProfile(ctx, ownerUserId, wsId, opts = {}) {
  const isAdmin = isSuperAdminTg(ctx.from?.id);

  let ws0 = null;
  try {
    ws0 = isAdmin ? await db.getWorkspaceAny(wsId) : await db.getWorkspace(ownerUserId, wsId);
  } catch (_) {
    ws0 = null;
  }
  if (!ws0) { await safeEditOrReply(ctx, '⚠️ Канал не найден или нет доступа. Открой 📋 Меню → выбери канал и повтори.', { parse_mode: 'HTML', reply_markup: navKb('a:ws_list') }); return; }

  try { await db.ensureWorkspaceSettings(wsId); } catch {}

  const ws = isAdmin ? await db.getWorkspaceAny(wsId) : await db.getWorkspace(ownerUserId, wsId);
  if (!ws) { await safeEditOrReply(ctx, '⚠️ Канал не найден или нет доступа. Открой 📋 Меню → выбери канал и повтори.', { parse_mode: 'HTML', reply_markup: navKb('a:ws_list') }); return; }

  let isPro = false;
  try { isPro = await db.isWorkspacePro(wsId); } catch {}

  const channel = ws.channel_username ? '@' + ws.channel_username : ws.title;
  const name = ws.profile_title || channel;
  const mode = String(ws.profile_mode || 'both');
  const ig = ws.profile_ig ? String(ws.profile_ig) : null;

  const verticalsTxt = fmtMatrix(ws.profile_verticals, PROFILE_VERTICALS);
  const formatsTxt = fmtMatrix(ws.profile_formats, PROFILE_FORMATS);

  const geoRaw = ws.profile_geo ? String(ws.profile_geo).trim() : '';
  const contactRawTxt = ws.profile_contact ? String(ws.profile_contact).trim() : '';
  const aboutRaw = ws.profile_about ? String(ws.profile_about).trim() : '';

  const canUnlockContacts = !!contactRawTxt || !!ws.channel_username;

  const link = wsBrandLink(wsId);

  let igLine = '—';
  if (ig) {
    igLine =
      `<a href="https://instagram.com/${escapeHtml(ig)}">instagram.com/${escapeHtml(ig)}</a>\n` +
      `<code>@${escapeHtml(ig)}</code>`;
  }

  let portLine = '—';
  const portsRaw = Array.isArray(ws.profile_portfolio_urls) ? ws.profile_portfolio_urls : [];
  const ports = portsRaw.map((x) => String(x || '').trim()).filter(Boolean);
  if (ports.length) {
    portLine = ports
      .slice(0, 3)
      .map(u => `• <a href="${escapeHtml(String(u))}">${escapeHtml(shortUrl(u))}</a>`)
      .join('\n');
    if (ports.length > 3) portLine += `\n• <i>+ ещё ${ports.length - 3}</i>`;
  }

  const proLine = isPro ? '⭐️ PRO: <b>активен</b>' : '⭐️ PRO: <b>free</b>';
  const modeLine = PROFILE_MODE_LABELS[mode] || PROFILE_MODE_LABELS.both;

  const prog = calcWsProfileProgress(ws);
  const progressLine = `📈 Заполнено: <b>${prog.percent}%</b> (${prog.done}/${prog.total})`;

  const statusLines = [];
  statusLines.push(`<b>Статус</b>`);
  statusLines.push(`• Канал: <b>${escapeHtml(channel)}</b>`);
  statusLines.push(`• ${proLine}`);
  statusLines.push(`• ${progressLine}`);
  if (prog?.nextHint) statusLines.push(`• <i>${escapeHtml(String(prog.nextHint))}</i>`);

  if (prog?.missing?.length) {
    const missing = prog.missing.slice(0, 5);
    statusLines.push('');
    statusLines.push(`⚡️ <b>Что добавить, чтобы заявки шли чаще</b>`);
    statusLines.push(...missing.map(x => `• ${x}`));
    if (prog.missing.length > 5) statusLines.push(`• <i>+ ещё ${prog.missing.length - 5}</i>`);
  } else {
    statusLines.push('');
    statusLines.push(`✅ Профиль выглядит 🔥 — можно лить трафик из IG.`);
  }

  const blocks = [];
  blocks.push(`👤 <b>Профиль</b>`);
  blocks.push('');
  blocks.push(`Это твоя <b>витрина для брендов</b>. Заполни поля ниже и открой <b>предпросмотр</b>, чтобы увидеть, как она выглядит.`);
  blocks.push('');
  blocks.push(statusLines.join('\n'));

  // Основное
  {
    const lines = [];
    lines.push(`<b>Основное</b>`);
    lines.push(`• Название/витрина: <b>${escapeHtml(String(name || '—'))}</b>`);
    lines.push(`• Режим: <b>${escapeHtml(String(modeLine || '—'))}</b>`);
    lines.push(`• Ниши: <code>${escapeHtml(String(verticalsTxt || '—'))}</code>`);
    lines.push(`• Гео: <b>${escapeHtml(geoRaw || '—')}</b>`);
    blocks.push('');
    blocks.push(lines.join('\n'));
  }

  // Контент
  {
    const lines = [];
    lines.push(`<b>Контент</b>`);
    lines.push(`• Форматы: <code>${escapeHtml(String(formatsTxt || '—'))}</code>`);
    lines.push(`• Описание: ${escapeHtml(aboutRaw ? clipText(aboutRaw, 320) : '—')}`);
    blocks.push('');
    blocks.push(lines.join('\n'));
  }

  // Портфолио
  {
    const lines = [];
    lines.push(`<b>Портфолио</b>`);
    lines.push(`• Instagram:\n${igLine}`);
    lines.push(`• Ссылки/кейсы:\n${portLine}`);
    blocks.push('');
    blocks.push(lines.join('\n'));
  }

  // Контакты
  {
    const lines = [];
    const contactsObj = wsProfileContactsObj(ws);
    const cCount = wsProfileContactsCount(contactsObj, ['tg', 'email', 'phone', 'site']);
    lines.push(`<b>Контакты</b>`);
    lines.push(`• Контакты (структурно): <b>${cCount}/4</b>`);
    lines.push(`• Контакт: <b>${escapeHtml(contactRawTxt || '—')}</b>`);
    lines.push(`• <i>Рекомендация: достаточно 1 контакта (обычно Telegram). Телефон не обязателен.</i>`);
    blocks.push('');
    blocks.push(lines.join('\n'));
  }

blocks.push('');
  blocks.push(
    link
      ? `🔗 <b>Ссылка для брендов</b> (вставь в IG bio / сторис):\n<code>${escapeHtml(link)}</code>`
      : `⚠️ Не задан BOT_USERNAME — ссылка для брендов недоступна.`
  );

  const text = blocks.join('\n');

  const extra = { parse_mode: 'HTML', reply_markup: wsProfileKb(wsId, ws), disable_web_page_preview: true };

  const et = opts && opts.editTarget ? opts.editTarget : null;
  if (et && et.chatId && et.messageId) {
    try {
      await ctx.api.editMessageText(Number(et.chatId), Number(et.messageId), text, extra);
      return;
    } catch {}
  }

  try {
    await safeEditOrReply(ctx, text, extra);
  } catch {
    await ctx.reply(text, extra);
  }
}



// STEP106: Structured contacts editor (opt-in).
async function renderWsProfileContactsStructured(ctx, ownerUserId, wsId, opts = {}) {
  const isAdmin = isSuperAdminTg(ctx.from?.id);

  const ws = isAdmin ? await db.getWorkspaceAny(wsId) : await db.getWorkspace(ownerUserId, wsId);
  if (!ws) { await safeEditOrReply(ctx, '⚠️ Канал не найден или нет доступа.', { parse_mode: 'HTML', reply_markup: navKb('a:ws_list') }); return; }

  const o = wsProfileContactsObj(ws);
  const tg = o.tg ? String(o.tg).replace(/^@/, '') : '';
  const email = o.email ? String(o.email) : '';
  const phone = o.phone ? String(o.phone) : '';
  const site = o.site ? String(o.site) : '';

  const legacyRaw = ws.profile_contact ? String(ws.profile_contact).trim() : '';
  const legacyHas = legacyRaw && legacyRaw !== '—';

  const cCount = wsProfileContactsCount(o, ['tg', 'email', 'phone', 'site']);

  const lines = [];
  lines.push(`📇 <b>Контакты (структурно)</b>`);
  if (opts && opts.flashHtml) {
    lines.push('');
    lines.push(String(opts.flashHtml));
  }
  lines.push('');
  lines.push(`Эти поля <b>показываются бренду только после</b> «${escapeHtml(contactUnlockBtnLabel())}».`);
  lines.push(`💡 Достаточно <b>1</b> контакта — обычно <b>Telegram</b>. Телефон <i>не обязателен</i>.`);
  lines.push(`Приоритет после разлока: <b>структурные</b> → (если пусто) <b>Контакт</b>.`);
  lines.push('');
  lines.push(`Заполнено: <b>${cCount}/4</b>`);
  lines.push('');
  lines.push(`<b>Текущие значения</b>`);
  lines.push(`• Telegram: ${tg ? `<code>@${escapeHtml(deLinkifyText(tg))}</code>` : '—'}`);
  lines.push(`• Email: ${email ? `<code>${escapeHtml(deLinkifyText(email))}</code>` : '—'}`);
  lines.push(`• Phone: ${phone ? `<code>${escapeHtml(deLinkifyText(phone))}</code>` : '—'}`);
  lines.push(`• Website: ${site ? `<code>${escapeHtml(deLinkifyText(site))}</code>` : '—'}`);
  if (legacyHas) lines.push(`• Контакт (текст): <code>${escapeHtml(deLinkifyText(legacyRaw))}</code>`);
  lines.push('');
  lines.push(`Чтобы очистить поле — используй «🧹 Очистить поле».`);

  const text = lines.join('\n');

  const kb = new InlineKeyboard()
    .text('✍️ Telegram username', `a:ws_prof_contacts_edit|ws:${wsId}|k:tg`)
    .row()
    .text('✍️ Email', `a:ws_prof_contacts_edit|ws:${wsId}|k:email`)
    .text('✍️ Phone', `a:ws_prof_contacts_edit|ws:${wsId}|k:phone`)
    .row()
    .text('✍️ Website', `a:ws_prof_contacts_edit|ws:${wsId}|k:site`);

  if (legacyHas) kb.row().text('✨ Перенести из «Контакт»', `a:ws_prof_contacts_migrate|ws:${wsId}`);

  kb.row()
    .text('🧹 Очистить поле', `a:ws_prof_contacts_clear|ws:${wsId}`)
    .row()
    .text('⬅️ Назад', `a:ws_profile|ws:${wsId}`)
    .text('📋 Меню', 'a:menu')
    .row()
    .text('🏠 Home', 'a:home');

  const extra = { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true };

  const et = opts && opts.editTarget ? opts.editTarget : null;
  if (et && et.chatId && et.messageId) {
    try {
      await ctx.api.editMessageText(Number(et.chatId), Number(et.messageId), text, extra);
      return;
    } catch {}
  }

  try { await safeEditOrReply(ctx, text, extra); } catch { await ctx.reply(text, extra); }
}

async function renderWsProfileContactsClearMenu(ctx, ownerUserId, wsId) {
  const isAdmin = isSuperAdminTg(ctx.from?.id);
  const ws = isAdmin ? await db.getWorkspaceAny(wsId) : await db.getWorkspace(ownerUserId, wsId);
  if (!ws) { await safeEditOrReply(ctx, '⚠️ Канал не найден или нет доступа.', { parse_mode: 'HTML', reply_markup: navKb('a:ws_list') }); return; }

  const o = wsProfileContactsObj(ws);
  const items = [
    { k: 'tg', label: 'Telegram', v: o.tg ? ('@' + String(o.tg).replace(/^@/, '')) : '' },
    { k: 'email', label: 'Email', v: o.email ? String(o.email) : '' },
    { k: 'phone', label: 'Phone', v: o.phone ? String(o.phone) : '' },
    { k: 'site', label: 'Website', v: o.site ? String(o.site) : '' },
  ].filter(x => x.v);

  const lines = [];
  lines.push(`🧹 <b>Очистить поле</b>`);
  lines.push('');
  if (!items.length) {
    lines.push('Нечего очищать — все поля пустые.');
  } else {
    lines.push('Выбери, что очистить:');
    lines.push('');
    for (const it of items) {
      lines.push(`• ${escapeHtml(it.label)}: <code>${escapeHtml(deLinkifyText(it.v))}</code>`);
    }
  }

  const kb = new InlineKeyboard();
  if (items.length) {
    for (const it of items) {
      kb.text(`🧹 ${it.label}`, `a:ws_prof_contacts_clear_k|ws:${wsId}|k:${it.k}`).row();
    }
  }
  kb.text('⬅️ Назад', `a:ws_prof_contacts|ws:${wsId}`).text('👤 Профиль', `a:ws_profile|ws:${wsId}`);
  kb.row().text('📋 Меню', 'a:menu').text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, lines.join('\n'), { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
}




