async function renderWsPublicProfile(ctx, wsId, opts = {}) {
  const ws = await withTimeout(db.getWorkspaceAny(wsId), 4500, 'ws.get');
  if (!ws) return ctx.reply('Профиль не найден.');

  const viewer = ctx?.from ? await db.upsertUser(ctx.from.id, ctx.from.username ?? null) : null;
  const isOwner = viewer && Number(viewer.id) === Number(ws.owner_user_id);

  let curatorUi = false;
  try {
    if (viewer && ctx?.from?.id) {
      const flags = await getRoleFlags(viewer, ctx.from.id);
      if (flags?.isCurator) curatorUi = await getCuratorMode(ctx.from.id);
    }
  } catch {}

  const isPreview = !!isOwner || !!curatorUi;

  const isCuratorPreview = !!curatorUi && !isOwner;

  // Brand Pass: show current balance прямо в витрине/диалоге (brand-facing UX).
  // If credits fetch fails — keep null to avoid неправильные подсказки.
  let brandCredits = null;
  if (!isPreview && viewer) {
    try {
      brandCredits = await withTimeout(getBrandCreditsRedisOnly(viewer.id), 2500, 'brand.credits.redis');
    } catch {
      brandCredits = null;
    }
  }

  const hideApply = !!opts?.hideApply;
  const contactCbExtra = String(opts?.contactCbExtra || '');
  const brandLeadId = Math.max(0, Number(opts?.brandLeadId || 0));
  const brandLeadCtx = !!opts?.dialogCb && hideApply;
  const dialogEntryLabel = brandLeadCtx ? brandLeadDialogButtonLabel(brandLeadId) : '💬 Диалог';
  const profileEntryLabel = brandLeadCtx ? brandLeadProfileButtonLabel() : '🪟 Витрина';
  const contactsEntryLabel = brandLeadCtx ? brandLeadContactUnlockButtonLabel() : contactUnlockBtnLabel();

  // Public view: hide direct contacts/channel by default to prevent bypassing the bot.
  // Contacts can be revealed via paid unlock (Brand Pass credits) and cached in Redis.
  let unlocked = false;
  if (!isPreview && viewer) {
    const key = k(['wsp_contact', wsId, viewer.id]);
    let redisOk = true;
    try {
      unlocked = !!(await redis.get(key));
    } catch {
      unlocked = false;
      redisOk = false;
    }

    // DB fallback ONLY when Redis is unavailable.
    if (!unlocked && !redisOk) {
      try {
        unlocked = !!(await withTimeout(db.isWorkspaceContactsUnlocked(viewer.id, wsId), 2500, 'wsp.unlock.db'));
      } catch {
        unlocked = false;
      }
      // Heal Redis cache best-effort (if it comes back).
      if (unlocked) {
        try { await redis.set(key, 1, { ex: CONTACT_UNLOCK_TTL_SEC }); } catch {}
      }
    }
  }
  const revealContacts = !!isPreview || !!unlocked || !!opts?.revealContacts;

  const linksEnabled = !!revealContacts && !isCuratorPreview;

  const channel = ws.channel_username ? '@' + ws.channel_username : ws.title;
  const publicName = ws.profile_title || ws.title || 'UGC Creator';
  const name = revealContacts ? (ws.profile_title || channel) : publicName;
  const mode = String(ws.profile_mode || 'both');
  const ig = ws.profile_ig ? String(ws.profile_ig) : null;

  const verticalsTxt = fmtMatrix(ws.profile_verticals, PROFILE_VERTICALS);
  const formatsTxt = fmtMatrix(ws.profile_formats, PROFILE_FORMATS);
  const geoRaw = ws.profile_geo ? String(ws.profile_geo).trim() : '';
  const contactRawTxt = ws.profile_contact ? String(ws.profile_contact).trim() : '';

  // STEP105: optional structured contacts (read-only support).
  // Source of truth remains legacy fields until creators start filling structured contacts.
  const contactsObj = (ws.profile_contacts && typeof ws.profile_contacts === 'object') ? ws.profile_contacts : null;
  // IG Trust badge (OAuth-only): stored in structured contacts meta to avoid leaking handle.
  const igMeta = (contactsObj?.ig && typeof contactsObj.ig === 'object') ? contactsObj.ig : null;
  const igVerified = igMeta?.verified === true;
  const cTgRaw = contactsObj?.tg ? String(contactsObj.tg).trim() : '';
  const cTg = cTgRaw.replace(/^@/, '');
  const cEmail = contactsObj?.email ? String(contactsObj.email).trim() : '';
  const cPhone = contactsObj?.phone ? String(contactsObj.phone).trim() : '';
  const cSiteRaw = contactsObj?.site ? String(contactsObj.site).trim() : '';
  const cSite = cSiteRaw && !/^https?:\/\//i.test(cSiteRaw) ? ('https://' + cSiteRaw.replace(/^\/+/, '')) : cSiteRaw;
  const cOther = contactsObj?.other ? String(contactsObj.other).trim() : '';
  const hasStructuredContacts = !!(cTg || cEmail || cPhone || cSite || cOther);

  const aboutRaw = ws.profile_about ? String(ws.profile_about).trim() : '';

  let aboutTxt = aboutRaw;
  let aboutRedacted = false;
  if (!isPreview && !revealContacts && aboutRaw) {
    try {
      const r = redactContactsInText(aboutRaw);
      aboutTxt = r.text;
      aboutRedacted = r.redacted;
    } catch {
      aboutTxt = aboutRaw;
      aboutRedacted = false;
    }
  } else if (isCuratorPreview && aboutRaw) {
    aboutTxt = deLinkifyText(aboutRaw);
  }

  const portsRaw = Array.isArray(ws.profile_portfolio_urls) ? ws.profile_portfolio_urls : [];
  const ports = portsRaw.map((x) => String(x || '').trim()).filter(Boolean);

  // Contacts unlock also gates any external links (IG/portfolio) to prevent bypassing monetization.
  const canUnlockContacts = hasStructuredContacts || !!contactRawTxt || !!ws.channel_username || !!ig || (ports && ports.length);

  // STEP175: anti-spam UI — if token-lock exists, show "pending" and hide unlock CTA until it resolves.
  let contactUnlockPending = false;
  if (!isPreview && viewer && canUnlockContacts && !revealContacts) {
    const lockKey = k(['mon', 'lock', 'wsp_contact_unlock', wsId, viewer.id]);
    try {
      contactUnlockPending = !!(await withTimeout(redis.get(lockKey), 1200, 'mon.lock'));
    } catch {
      contactUnlockPending = false;
    }
  }

  const contactUrlLegacy = (() => {
    const contactRaw = contactRawTxt;
    if (!contactRaw) return null;
    const tg = wsTgUrlFromContact(contactRaw);
    if (tg) return tg;
    if (/^https?:\/\//i.test(contactRaw)) return contactRaw;
    if (/^t\.me\//i.test(contactRaw)) return 'https://' + contactRaw;
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactRaw)) return 'mailto:' + contactRaw;
    return null;
  })();

  // Primary contact URL for brand-facing "💬 Написать".
  // Prefer structured Telegram username, then legacy, then structured site.
  const primaryContactUrl = (() => {
    if (cTg) return `https://t.me/${cTg}`;
    if (contactUrlLegacy) return contactUrlLegacy;
    if (cSite) return cSite;
    return null;
  })();

  // Trust layer: verified badge is allowed BEFORE unlock, but handle/url are paywalled (contacts).
  let igLine = '';
  if (ig) {
    if (linksEnabled) {
      igLine =
        `${igVerified ? '✅ <b>verified</b>\n' : ''}` +
        `<a href="https://instagram.com/${escapeHtml(ig)}">instagram.com/${escapeHtml(ig)}</a>\n` +
        `<code>@${escapeHtml(ig)}</code>`;
    } else {
      if (isPreview) {
        // Curator preview: show as plain text (not clickable) to assist moderation/review.
        const igPlain = deLinkifyText(`instagram.com/${ig} • @${ig}`);
        igLine = `${igVerified ? '✅ verified • ' : ''}<code>${escapeHtml(igPlain)}</code>`;
      } else {
        igLine = `${igVerified ? '✅ <b>verified</b> · ' : ''}<b>🔒 скрыто</b> (открывается через «${escapeHtml(contactUnlockBtnLabel())}»)`;
      }
    }
  } else if (igVerified) {
    // Verified but handle is not stored in legacy field yet — show only the badge.
    igLine = `✅ <b>verified</b>`;
  }

  let portLine = '';
  if (ports.length) {
    if (linksEnabled) {
      portLine = ports
        .slice(0, 3)
        .map(u => `• <a href="${escapeHtml(String(u))}">${escapeHtml(shortUrl(u))}</a>`)
        .join('\n');
    } else {
      if (isPreview) {
        portLine = ports
          .slice(0, 3)
          .map(u => `• <code>${escapeHtml(deLinkifyText(String(u)))}</code>`)
          .join('\n');
      } else {
        portLine = `<b>🔒 скрыто</b> (открывается через «${escapeHtml(contactUnlockBtnLabel())}»)`;
      }
    }
    // Only show extra count when links are revealed (avoid teasing exact URLs in locked state).
    if (ports.length > 3 && (linksEnabled || isPreview)) portLine += `\n• <i>+ ещё ${ports.length - 3}</i>`;
  }

  const modeLine = PROFILE_MODE_LABELS[mode] || PROFILE_MODE_LABELS.both;
  const prog = isOwner ? calcWsProfileProgress(ws) : null;

  const isPro = (() => {
    const plan = String(ws.plan || 'free');
    if (plan !== 'pro') return false;
    const until = ws.pro_until;
    if (!until) return true;
    return new Date(until).getTime() > Date.now();
  })();

  const blocks = [];
  const badge = isPro ? ' ⭐️ <b>PRO</b>' : '';
  blocks.push(`✨ <b>${escapeHtml(name)}</b>${badge}`);
  blocks.push('');
  if (isPreview) {
    blocks.push(`👁 <b>Предпросмотр</b>: так бренды видят твою витрину.`);
    if (isOwner) blocks.push(`🔗 Чтобы поделиться витриной — нажми «🔗 Поделиться» ниже. Для Instagram — «📌 IG шаблоны».`);
  } else {
    if (hideApply) blocks.push(`${profileEntryLabel} (read-only): продолжай через «${dialogEntryLabel}». Контакты на витрине — через «${contactsEntryLabel}».`);
    else blocks.push(`${profileEntryLabel}: нажми «📝 Оставить заявку». Контакты на витрине — через «${contactsEntryLabel}».`);

    if (viewer) {
      for (const line of brandPassCreditsBlockLines(brandCredits)) blocks.push(line);
      if (brandCredits !== null && canUnlockContacts && !revealContacts) {
        const needLine = brandPassContactsNeedLineHtml(brandCredits);
        if (needLine) blocks.push(needLine);
      }
    }


    if (canUnlockContacts && revealContacts) {
      blocks.push('✅ <b>Контакты открыты</b>');
    } else if (canUnlockContacts && contactUnlockPending) {
      blocks.push('⏳ <b>В обработке…</b> (контакты в очереди)');
    }
  }

  // Основное
  {
    const lines = [];
    lines.push(`<b>Основное</b>`);
    const channelHtml = (() => {
      if (!revealContacts) return `<b>🔒 скрыто</b>`;
      if (linksEnabled && ws.channel_username) {
        const un = String(ws.channel_username).replace(/^@/, '');
        return `<a href="https://t.me/${escapeHtml(un)}">@${escapeHtml(un)}</a>`;
      }
      return `<b>${escapeHtml(channel)}</b>`;
    })();
    lines.push(`• Канал: ${channelHtml}`);
    lines.push(`• Режим: <b>${escapeHtml(modeLine)}</b>`);
    if (geoRaw) lines.push(`• Гео: <b>${escapeHtml(geoRaw)}</b>`);
    if (verticalsTxt && verticalsTxt !== '—') lines.push(`• Ниши: <code>${escapeHtml(clipText(verticalsTxt, 180))}</code>`);
    blocks.push('');
    blocks.push(lines.join('\n'));
  }

  // Контент
  {
    const lines = [];
    if ((formatsTxt && formatsTxt !== '—') || aboutTxt) {
      lines.push(`<b>Контент</b>`);
      if (formatsTxt && formatsTxt !== '—') lines.push(`• Форматы: <code>${escapeHtml(clipText(formatsTxt, 220))}</code>`);
      if (aboutTxt) lines.push(`• Описание: ${escapeHtml(clipText(aboutTxt, 320))}`);
      if (aboutRedacted) lines.push(`• <i>Контакты в тексте скрыты до разблокировки</i>`);
      blocks.push('');
      blocks.push(lines.join('\n'));
    }
  }

  // Портфолио
  {
    const lines = [];
    if (igLine || portLine) {
      lines.push(`<b>Портфолио</b>`);
      if (igLine) lines.push(`• Instagram:\n${igLine}`);
      if (portLine) lines.push(`• Ссылки/кейсы:\n${portLine}`);
      blocks.push('');
      blocks.push(lines.join('\n'));
    }
  }

  // Контакты
  {
    const lines = [];
    if (canUnlockContacts) {
      lines.push(`<b>Контакты</b>`);
      if (revealContacts) {
        // Full contact pack after paid unlock
        if (linksEnabled && ws.channel_username) {
          const un = String(ws.channel_username).replace(/^@/, '');
          lines.push(`• Telegram: <a href="https://t.me/${escapeHtml(un)}">@${escapeHtml(un)}</a>`);
        }
        if (hasStructuredContacts) {
          if (cTg) {
            if (linksEnabled) lines.push(`• TG username: <a href="https://t.me/${escapeHtml(cTg)}">@${escapeHtml(cTg)}</a>`);
            else lines.push(`• TG username: <b>${escapeHtml(deLinkifyText('@' + cTg))}</b>`);
          }
          if (cEmail) {
            if (linksEnabled) lines.push(`• Email: <a href="mailto:${escapeHtml(cEmail)}">${escapeHtml(cEmail)}</a>`);
            else lines.push(`• Email: <b>${escapeHtml(deLinkifyText(cEmail))}</b>`);
          }
          if (cPhone) {
            lines.push(`• Phone: <b>${escapeHtml(deLinkifyText(cPhone))}</b>`);
          }
          if (cSite) {
            if (linksEnabled) lines.push(`• Website: <a href="${escapeHtml(cSite)}">${escapeHtml(shortUrl(cSite))}</a>`);
            else lines.push(`• Website: <b>${escapeHtml(deLinkifyText(cSite))}</b>`);
          }
          if (cOther) {
            lines.push(`• Доп.: <b>${escapeHtml(deLinkifyText(cOther))}</b>`);
          }
        }
        if (contactRawTxt) {
          if (linksEnabled && contactUrlLegacy) lines.push(`• Контакт: <a href="${escapeHtml(contactUrlLegacy)}">${escapeHtml(contactRawTxt)}</a>`);
          else lines.push(`• Контакт: <b>${escapeHtml(deLinkifyText(contactRawTxt))}</b>`);
        } else if (!hasStructuredContacts) {
          lines.push(`• Контакт: —`);
        }
        if (ig && linksEnabled) {
          lines.push(`• Instagram: <a href="https://instagram.com/${escapeHtml(ig)}">@${escapeHtml(ig)}</a>`);
        }
        if (ports.length && linksEnabled) {
          const u0 = String(ports[0] || '').trim();
          if (u0) lines.push(`• Портфолио: <a href="${escapeHtml(u0)}">${escapeHtml(shortUrl(u0))}</a>${ports.length > 1 ? ` <i>+ ещё ${ports.length - 1}</i>` : ''}`);
        }
      } else if (contactUnlockPending) {
        lines.push(`• Контакты: <b>⏳ в обработке</b> (обнови витрину через 10–30 сек)`);
      } else {
        lines.push(`• Контакты: <b>🔒 скрыто</b> (открываются через «${contactsEntryLabel}»)`);
      }
      blocks.push('');
      blocks.push(lines.join('\n'));
    }
  }

  if (isPreview) {
    blocks.push('');
    blocks.push(`Это предпросмотр. Чтобы вернуться — используй «⬅️ Назад» или «📋 Меню».`);
  }

  if (isOwner && prog) {
    blocks.push('');
    blocks.push(`📈 <b>Твой профиль</b>: <b>${prog.percent}%</b>. ${prog.nextHint}`);
  }

  const text = blocks.filter((x) => x !== null && x !== undefined).join('\n');
  const kb = new InlineKeyboard();

  // CTA row
  if (!isPreview) {
    const dialogCb = opts?.dialogCb ? String(opts.dialogCb) : '';

    // Row 1: dialog (if any) + apply (public)
    let rowHas = false;
    if (dialogCb) {
      kb.text(dialogEntryLabel, dialogCb);
      rowHas = true;
    }
    if (!hideApply) {
      kb.text('📝 Оставить заявку', `a:wsp_lead_new|ws:${wsId}`);
      rowHas = true;
    }
    if (rowHas) kb.row();

    // Row 2: contacts gate (or direct contact once unlocked)
    const hasHidden = hasStructuredContacts || !!contactRawTxt || !!ws.channel_username || !!contactUrlLegacy || !!ig || (ports && ports.length);
    if (linksEnabled) {
      if (primaryContactUrl) {
        kb.url('💬 Написать', primaryContactUrl);
        kb.row();
      }
    } else if (hasHidden) {
      const openCb = `a:wsp_open|ws:${wsId}${hideApply ? '|m:ro' : ''}${contactCbExtra}`;
      if (contactUnlockPending) {
        kb.text('🔄 Обновить', openCb);
        if (CONTACT_UNLOCK_COST > 0) kb.text('💳 Купить ещё', `a:brand_pass|ws:0|ret:wsp|rws:${wsId}`);
        kb.row();
      } else {
      // Brand-facing UX: если кредитов нет — сразу ведём на покупку.
      // Если кредитов мало — оставляем и «Контакты», и «Купить», чтобы путь был очевиден.
      const balNum = (brandCredits === null || brandCredits === undefined) ? null : Number(brandCredits || 0);
      if (CONTACT_UNLOCK_COST <= 0) {
        kb.text(contactsEntryLabel, `a:wsp_contact_req|ws:${wsId}${contactCbExtra}`);
      } else if (balNum !== null) {
        if (balNum <= 0) {
          // STEP213: keep «Контакты» visible even when Redis balance is 0/stale.
          kb.text(contactsEntryLabel, `a:wsp_contact_req|ws:${wsId}${contactCbExtra}`)
            .text('💳 Купить ещё', `a:brand_pass|ws:0|ret:wsp|rws:${wsId}`);
        } else if (balNum < CONTACT_UNLOCK_COST) {
          kb.text(contactsEntryLabel, `a:wsp_contact_req|ws:${wsId}${contactCbExtra}`)
            .text('💳 Купить ещё', `a:brand_pass|ws:0|ret:wsp|rws:${wsId}`);
        } else {
          kb.text(contactsEntryLabel, `a:wsp_contact_req|ws:${wsId}${contactCbExtra}`);
        }
      } else {
        kb.text(contactsEntryLabel, `a:wsp_contact_req|ws:${wsId}${contactCbExtra}`);
        if (CONTACT_UNLOCK_COST > 0) kb.text('💳 Купить ещё', `a:brand_pass|ws:0|ret:wsp|rws:${wsId}`);
      }
      kb.row();
      }
    }
  } else {
    // Preview: keep buttons minimal (no direct contact links).
  }

  // Preview/owner actions (separate from platforms)
  if (isOwner) {
    kb
      .text('🔗 Поделиться', `a:ws_share|ws:${wsId}`)
      .text('📌 IG шаблоны', `a:ws_ig_templates|ws:${wsId}`)
      .row();
  }

  // Platforms (only when links are enabled)
  if (linksEnabled) {
    const plats = [];
    if (ws.channel_username) plats.push({ t: (isOwner ? '📣 Мои каналы' : '📣 Telegram канал'), u: `https://t.me/${String(ws.channel_username).replace(/^@/, '')}` });
    if (ig) plats.push({ t: '📸 Instagram', u: `https://instagram.com/${ig}` });
    if (ports.length) {
      const u0 = String(ports[0] || '').trim();
      if (u0) plats.push({ t: '🗂 Портфолио', u: u0 });
    }

    for (let i = 0; i < plats.length; i++) {
      kb.url(plats[i].t, plats[i].u);
      if (i % 2 === 1) kb.row();
    }
  }

  const backCb = opts?.backCb || (isOwner ? `a:ws_profile|ws:${wsId}` : null);
  kb.row();
  if (backCb) kb.text('⬅️ Назад', backCb);
  kb.text('📋 Меню', 'a:menu').text('🏠 Home', 'a:home');

  const extra = { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true };
  if (ctx.callbackQuery) await safeEditOrReply(ctx, text, extra);
  else await ctx.reply(text, extra);

}

async function renderWsLeadCompose(ctx, wsId, step = 1, draft = {}) {
  const ws = await db.getWorkspaceAny(wsId);
  if (!ws) return ctx.answerCallbackQuery({ text: 'Профиль не найден.' });

  const channelTitle = ws.title || 'канал';
  const link = wsBrandLink(wsId);

  const to = String(ws.profile_title || channelTitle);

  let text =
    `📩 <b>Запрос бренда</b>\n\n` +
    `Кому: <b>${escapeHtml(to)}</b>
` +
    `Канал: <b>${escapeHtml(channelTitle)}</b>
` +
    (link ? `Витрина: <a href="${escapeHtml(link)}">${escapeHtml(link)}</a>\n\n` : `\n`);

  if (Number(step) === 2) {
    const contact = String(draft?.contact || '').trim();
    text +=
      `✅ <b>Шаг 2/2</b>\n` +
      (contact ? `Контакт бренда: <b>${escapeHtml(contact)}</b>\n\n` : `\n`) +
      `Опиши запрос коротко:\n` +
      `• тип: UGC или интеграция\n` +
      `• объём (1/3/5 видео, серия, пак)\n` +
      `• бюджет или бартер\n` +
      `• сроки/дедлайн\n` +
      `• 1 строка про продукт/бренд\n\n` +
      `После отправки я мгновенно уведомлю владельца канала.`;
  } else {
    text +=
      `🧩 <b>Шаг 1/2</b>\n` +
      `Пришли контакт бренда (IG / @username / ссылка / сайт).\n` +
      `Пример: <code>@brand</code> или <code>https://instagram.com/brand</code>\n\n` +
      `Дальше я спрошу детали (что нужно + условия + дедлайн).`;
  }

  const kb = new InlineKeyboard()
    .text('⬅️ Назад', `a:wsp_open|ws:${wsId}`)
    .text('📋 Меню', 'a:menu').text('🏠 Home', 'a:home');

  try {
    await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
  } catch {
    await ctx.reply(text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
  }
}
function leadListTabsKb(wsId, counts, active, ret) {
  // Tabs for Creator Inbox (brand leads). Make them self-explanatory, like Brand Inbox.
  const a = normLeadStatus(active);

  const rPart = ret ? retPartShort(ret) : '';

  const kb = new InlineKeyboard()
    .text(`🆕 Новые ${counts.new ?? 0}`, `a:ws_leads|w:${wsId}|s:n|p:0${rPart}`)
    .text(`💬 В работе ${counts.in_progress ?? 0}`, `a:ws_leads|w:${wsId}|s:ip|p:0${rPart}`)
    .row()
    .text(`✅ Закрыты ${counts.closed ?? 0}`, `a:ws_leads|w:${wsId}|s:cl|p:0${rPart}`)
    .text(`⛔ Спам ${counts.spam ?? 0}`, `a:ws_leads|w:${wsId}|s:sp|p:0${rPart}`);

  // Mark active with a dot
  for (const row of kb.inline_keyboard) {
    for (const btn of row) {
      const d = String(btn.callback_data || '');
      const aCb = leadStatusToCb(a);
      if (d.includes(`|s:${aCb}|`) || d.includes(`|s:${a}|`)) btn.text = '• ' + btn.text;
    }
  }
  return kb;
}


function creatorLeadWhatNow(status, opts = {}) {
  const st = normLeadStatus(status);
  const canManualReply = !!opts.canManualReply;
  if (st === 'new') {
    return canManualReply
      ? 'Новая заявка: ответь бренду, возьми в работу или добавь заметку.'
      : 'Новая заявка: возьми её себе, отправь шаблон и поставь статус.';
  }
  if (st === 'in_progress') {
    return canManualReply
      ? 'Диалог уже в работе: смотри последние сообщения и двигай заявку дальше.'
      : 'Заявка уже в работе: продолжай диалог, статус и заметки держи в этой карточке.';
  }
  if (st === 'closed') {
    return canManualReply
      ? 'Заявка закрыта: смотри историю и при необходимости открой новый ответ.'
      : 'Заявка закрыта: можно посмотреть историю или вернуть внимание через заметку.';
  }
  if (st === 'spam') {
    return canManualReply
      ? 'Заявка помечена как спам: история сохранена внутри карточки.'
      : 'Спам: карточка сохранена для внутренней проверки и заметок.';
  }
  return 'Открой карточку и продолжай работу по заявке.';
}

function formatCreatorLeadThread(items, limit = 3) {
  const arr = Array.isArray(items) ? items : [];
  const tail = arr.slice(Math.max(0, arr.length - limit));
  if (!tail.length) return '';

  const whoTitle = (by) => {
    if (by === 'brand') return 'Бренд';
    if (by === 'creator') return 'Вы';
    if (by === 'curator') return 'Вы';
    return 'Система';
  };

  return tail.map((x) => {
    const who = whoTitle(String(x?.by || 'system').trim().toLowerCase());
    const t = String(x?.text || '').replace(/\s+/g, ' ').trim();
    const snippet = clipText(t || '—', 180);
    return `• <b>${escapeHtml(who)}:</b> ${escapeHtml(snippet)}`;
  }).join('\n');
}

async function renderWsLeadsList(ctx, ownerUserId, wsId, status = 'new', page = 0, ret = null) {
  const actorUserId = ownerUserId;
  const isAdmin = isSuperAdminTg(ctx.from?.id);
  const ws = await db.getWorkspaceAny(wsId);
  if (!ws) {
    await safeEditOrReply(ctx, '⚠️ Канал не найден. Открой 📋 Меню → выбери канал и повтори.', { parse_mode: 'HTML', reply_markup: navKb('a:ws_list') });
    return;
  }

  const isOwner = Number(ws.owner_user_id) === Number(actorUserId);
  if (!isAdmin && isOwner && isWorkspaceDisconnected(ws)) {
    await renderWsDisconnected(ctx, ownerUserId, wsId, { backCb: 'a:ws_list', source: 'workspace_leads' });
    return;
  }
  let isCurator = false;
  if (!isAdmin && !isOwner) {
    try { isCurator = await db.isCuratorForWorkspace(Number(wsId), Number(actorUserId)); } catch {}
  }
  if (!isAdmin && !isOwner && !isCurator) {
    await safeEditOrReply(ctx, '⚠️ Нет доступа. Открой 📋 Меню → выбери канал заново.', { parse_mode: 'HTML', reply_markup: navKb('a:ws_list') });
    return;
  }

  const st = normLeadStatus(status);
  const p = Math.max(0, Number(page) || 0);
  const limit = 10;
  const offset = p * limit;

  const counts = await db.countBrandLeadsByStatus(wsId);
  const leads = await db.listBrandLeads(wsId, st, limit, offset);
  const total = Number(counts?.[st] || 0);
  const hasMultiplePages = total > limit;

  const channel = ws.channel_username ? '@' + ws.channel_username : ws.title;
  const roleHint = (!isOwner && isCurator && !isAdmin)
    ? 'ℹ️ <i>Ты куратор: можешь отвечать шаблонами, ставить статусы и заметки. Владелец видит все изменения.</i>'
    : '';

  let text = `📨 <b>Заявки брендов</b>`;
  text += `
Последние входящие заявки в этот канал.`;
  const summaryMeta = hasMultiplePages
    ? `${escapeHtml(channel)} · ${escapeHtml((LEAD_STATUSES[st] || LEAD_STATUSES.new).title)} · всего ${total} · стр ${p + 1}`
    : `${escapeHtml(channel)} · ${escapeHtml((LEAD_STATUSES[st] || LEAD_STATUSES.new).title)} · всего ${total}`;
  text += `
<i>${summaryMeta}</i>`;
  if (roleHint) text += `
${roleHint}`;

  if (leads.length) {
    text += `

Открой заявку: там статус, последние сообщения, заметки и действия.`;
  } else {
    text += `

Пока пусто. Заявки появятся, когда бренд нажмёт кнопку на витрине.`;
  }

  const kb = leadListTabsKb(wsId, counts, st, ret);
  const retKey = String(ret || '').trim();
  const rPart = retKey ? retPartShort(retKey) : '';

  for (const l of leads.slice(0, 8)) {
    const whoBtn = l.brand_username ? '@' + String(l.brand_username).replace(/^@/, '') : (String(l.brand_name || '').trim() || 'Бренд');
    const whoShort = clipText(whoBtn, 18);
    const btnLabel = clipText(`${leadStatusIcon(l.status)} ${whoShort} · #${l.id}`, 50);
    kb.row().text(btnLabel, `a:lead_view|id:${l.id}|w:${wsId}|s:${leadStatusToCb(st)}|p:${p}${rPart}`);
  }

  if (p > 0) kb.row().text('⬅️ Назад', `a:ws_leads|w:${wsId}|s:${leadStatusToCb(st)}|p:${p - 1}${rPart}`);
  if (leads.length === limit) {
    if (p > 0) kb.text('➡️ Далее', `a:ws_leads|w:${wsId}|s:${leadStatusToCb(st)}|p:${p + 1}${rPart}`);
    else kb.row().text('➡️ Далее', `a:ws_leads|w:${wsId}|s:${leadStatusToCb(st)}|p:${p + 1}${rPart}`);
  }

  let backCb = `a:ws_profile|ws:${wsId}`;
  if (retKey === 'ws_open') backCb = `a:ws_open|ws:${wsId}`;
  else if (retKey === 'cw') backCb = `a:cur_ws|ws:${wsId}`;
  else if (retKey === 'ws_list') backCb = 'a:ws_list';
  else if (retKey === 'menu') backCb = 'a:menu';
  else if (retKey === 'home') backCb = 'a:home';
  else if (!retKey && isCurator && !isOwner && !isAdmin) backCb = `a:cur_ws|ws:${wsId}`;
  kbNavRow(kb, backCb);

  try {
    await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
  } catch {
    await ctx.reply(text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
  }
}


// -----------------------------
// Curator Inbox (aggregate leads across all workspaces)
// -----------------------------

function curatorInboxTabsKb(counts, active, page = 0, assignFilter = 'all') {
  const a = normLeadStatus(active);
  const af = String(assignFilter || 'all');
  const kb = new InlineKeyboard()
    .text(`🆕 Новые ${counts.new ?? 0}`, `a:cur_inbox|s:n|p:0|af:${af}`)
    .text(`💬 В работе ${counts.in_progress ?? 0}`, `a:cur_inbox|s:ip|p:0|af:${af}`)
    .row()
    .text(`✅ Закрыты ${counts.closed ?? 0}`, `a:cur_inbox|s:cl|p:0|af:${af}`)
    .text(`⛔ Спам ${counts.spam ?? 0}`, `a:cur_inbox|s:sp|p:0|af:${af}`);

  // Mark active status
  for (const row of kb.inline_keyboard) {
    for (const btn of row) {
      const d = String(btn.callback_data || '');
      const aCb = leadStatusToCb(a);
      if (d.includes(`|s:${aCb}|`) || d.includes(`|s:${a}|`)) btn.text = '• ' + btn.text;
    }
  }

  // Assignment filter row
  const afAll = af === 'all' ? '• 📋 Все' : '📋 Все';
  const afMy = af === 'my' ? '• 👤 Мои' : '👤 Мои';
  const afFree = af === 'free' ? '• 🆓 Свободные' : '🆓 Свободные';
  kb.row()
    .text(afAll, `a:cur_inbox|s:${leadStatusToCb(a)}|p:0|af:all`)
    .text(afMy, `a:cur_inbox|s:${leadStatusToCb(a)}|p:0|af:my`)
    .text(afFree, `a:cur_inbox|s:${leadStatusToCb(a)}|p:0|af:free`);

  return kb;
}

async function renderCuratorInbox(ctx, userId, status = 'new', page = 0, assignFilter = 'all') {
  const st = normLeadStatus(status);
  const af = ['all', 'my', 'free'].includes(String(assignFilter)) ? String(assignFilter) : 'all';
  const p = Math.max(0, Number(page) || 0);
  const limit = 10;
  const offset = p * limit;

  const counts = await db.countBrandLeadsForCuratorByStatus(userId);

  let leads;
  try {
    leads = await db.listBrandLeadsForCuratorFiltered(userId, st, af, limit, offset);
  } catch (e) {
    // Fallback: column may not exist yet (pre-migration)
    if (String(e?.message || '').includes('assigned_user_id')) {
      leads = await db.listBrandLeadsForCurator(userId, st, limit, offset);
    } else throw e;
  }

  const afLabel = af === 'my' ? ' (👤 Мои)' : af === 'free' ? ' (🆓 Свободные)' : '';

  const whatNext =
    `<b>Что дальше:</b>\n` +
    `1) Открой заявку ниже.\n` +
    `2) Нажми «👤 Взять себе» — чтобы закрепить.\n` +
    `3) Ответь шаблоном (✅/🧾/❌) и поставь статус.\n` +
    `4) Добавь 📝 заметку — её увидит владелец.\n\n` +
    `<i>Легенда: 👤 — назначено на тебя, 📌 — назначено на другого куратора.</i>\n\n`;

  const textHeader =
    `📨 <b>Очередь заявок</b>${afLabel}\n\n` +
    `Заявки брендов по всем каналам, где ты куратор.\n` +
    `Статус: <b>${escapeHtml((LEAD_STATUSES[st] || LEAD_STATUSES.new).title)}</b>\n\n` +
    whatNext;

  const lines = leads.map((l) => {
    const wsUser = String(l.workspace_username || '').trim();
    const wsTitle = wsUser
      ? ('@' + wsUser.replace(/^@/, ''))
      : String(l.workspace_title || '').trim();
    const wsShortRaw = wsTitle ? clipText(wsTitle, 18) : `#${l.workspace_id}`;
    const wsShort = deLinkifyText(wsShortRaw);
    const whoRaw = l.brand_username ? '@' + String(l.brand_username).replace(/^@/, '') : (l.brand_name || 'brand');
    const who = deLinkifyText(String(whoRaw));
    const snippet = String(l.message || '').replace(/\s+/g, ' ').slice(0, 52);
    const assignTag = l.assigned_user_id
      ? (Number(l.assigned_user_id) === Number(userId) ? ' 👤' : ` 📌${l.assigned_username ? '@' + l.assigned_username : ''}`)
      : '';
    return `${leadStatusIcon(l.status)} <b>#${l.id}</b>${assignTag} — ${escapeHtml(wsShort)} — ${escapeHtml(who)} — <i>${escapeHtml(snippet)}${String(l.message || '').length > 52 ? '…' : ''}</i>`;
  });

  const body = lines.length ? lines.join('\n') : 'Пока пусто. Заявки появятся, когда бренд нажмёт кнопку на витрине.';

  const kb = curatorInboxTabsKb(counts, st, p, af);

  // quick open buttons (max 8)
  for (const l of leads.slice(0, 8)) {
    const wsTitle = String(l.workspace_username || l.workspace_title || '').trim();
    const wsShort = wsTitle ? clipText(wsTitle.startsWith('@') ? wsTitle : ('@' + wsTitle.replace(/^@/, '')), 16) : `#${l.workspace_id}`;
    const whoBtn = l.brand_username
      ? '@' + String(l.brand_username).replace(/^@/, '')
      : (String(l.brand_name || '').trim() || 'brand');
    const whoShort = clipText(whoBtn, 14);
    const btnLabel = clipText(`${leadStatusIcon(l.status)} #${l.id} ${wsShort} ${whoShort}`, 56);
    kb.row().text(btnLabel, `a:lead_view|id:${l.id}|w:${l.workspace_id}|s:${leadStatusToCb(st)}|p:${p}|r:ci|af:${af}`);
  }

  // pagination
  if (p > 0) kb.row().text('⬅️', `a:cur_inbox|s:${leadStatusToCb(st)}|p:${p - 1}|af:${af}`);
  if (leads.length === limit) {
    if (p > 0) kb.text('➡️', `a:cur_inbox|s:${leadStatusToCb(st)}|p:${p + 1}|af:${af}`);
    else kb.row().text('➡️', `a:cur_inbox|s:${leadStatusToCb(st)}|p:${p + 1}|af:${af}`);
  }

  kbNavRow(kb, 'a:cur_home');

  try {
    await safeEditOrReply(ctx, textHeader + body, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
  } catch {
    await ctx.reply(textHeader + body, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
  }
}

// Safe wrappers: keep ownership checks inside SQL where possible.
async function getLeadForActorSafe(ctx, actorUserId, leadId) {
  const id = Number(leadId || 0);
  if (!id) return null;
  // Super-admin can inspect any lead.
  if (isSuperAdminTg(ctx.from?.id)) return await db.getBrandLeadById(id);
  return await db.getBrandLeadForActor(id, actorUserId);
}

async function getBrandAppForActorSafe(ctx, actorUserId, appId) {
  const id = Number(appId || 0);
  if (!id) return null;
  // Super-admin can inspect any application.
  if (isSuperAdminTg(ctx.from?.id)) return await safeBrandApplications(() => db.getBrandApplicationById(id), async () => null);
  return await safeBrandApplications(() => db.getBrandApplicationForActor(id, actorUserId), async () => null);
}

async function renderLeadView(ctx, actorUserId, leadId, back = { wsId: null, status: 'new', page: 0, ret: '' }) {
  const stepId = `lead_view:${Number(leadId || 0)}`;
  const lead = await p0Await(ctx, stepId, `${stepId}:getLead`, () => getLeadForActorSafe(ctx, actorUserId, leadId), 4500);
  if (!lead) { await safeEditOrReply(ctx, '⚠️ Заявка не найдена или удалена. Открой 📨 Заявки брендов и выбери заявку ещё раз.', { parse_mode: 'HTML', reply_markup: navKb('a:menu') }); return; }

  const wsId = Number(lead.workspace_id);
  const ws = await p0Await(ctx, stepId, `${stepId}:getWs`, () => db.getWorkspaceAny(wsId), 4500);
  if (!ws) { await safeEditOrReply(ctx, '⚠️ Канал не найден или нет доступа. Открой 📋 Меню → выбери канал и повтори.', { parse_mode: 'HTML', reply_markup: navKb('a:ws_list') }); return; }

  const isOwner = Number(ws.owner_user_id) === Number(actorUserId);
  const isAdmin = isSuperAdminTg(ctx.from?.id);
  const canManualReply = isOwner || isAdmin;
  const plainUi = !canManualReply;

  const channel = ws.channel_username ? '@' + ws.channel_username : ws.title;
  const who = lead.brand_username ? '@' + String(lead.brand_username).replace(/^@/, '') : (lead.brand_name || 'brand');
  const when = lead.updated_at ? fmtTs(lead.updated_at) : (lead.created_at ? fmtTs(lead.created_at) : '—');
  const st = normLeadStatus(lead.status);
  const stTitle = (LEAD_STATUSES[st] || LEAD_STATUSES.new).title;
  const flash = String(back?.flash || '').trim();

  const link = wsBrandLink(wsId);
  const channelShown = plainUi ? deLinkifyText(channel) : channel;
  const whoShown = plainUi ? deLinkifyText(who) : who;
  const vitrinaLine = link
    ? (plainUi
        ? `🪟 <b>Витрина</b>
<code>${escapeHtml(deLinkifyText(link))}</code>`
        : `🪟 <b>Витрина</b>
<a href="${escapeHtml(link)}">${escapeHtml(link)}</a>`)
    : '';

  const msgRaw = String(lead.message || '').trim();
  const msgText = msgRaw ? clipText(msgRaw, 700) : '—';
  const msgEsc = escapeHtml(msgText) + (msgRaw && msgRaw.length > 700 ? '\n<i>(сокращено)</i>' : '');

  const replyRaw = String(lead.reply_text || '').trim();
  const replyText = replyRaw ? clipText(replyRaw, 500) : '';
  const replyEsc = replyRaw ? (escapeHtml(replyText) + (replyRaw.length > 500 ? '\n<i>(сокращено)</i>' : '')) : '';

  const notesRaw = (lead.meta && Array.isArray(lead.meta.curator_notes)) ? lead.meta.curator_notes : [];
  const notes = normalizeLeadNotes(notesRaw);
  const notesLast = notes.slice(-3).reverse();
  const thread = getBrandLeadThreadItems(lead);
  const threadBlock = formatCreatorLeadThread(thread, 3);

  let text =
    `💬 <b>Диалог по заявке #${lead.id}</b>
` +
    `<b>${escapeHtml(stTitle)}</b>
` +
    `📣 <b>${escapeHtml(channelShown)}</b> · 🏷️ <b>${escapeHtml(whoShown)}</b>
` +
    `🕒 <code>${escapeHtml(when)}</code>`;

  if (flash) text += `

✅ <b>${escapeHtml(flash)}</b>`;
  text += `

💡 <b>Сейчас</b>
${escapeHtml(creatorLeadWhatNow(st, { canManualReply }))}`;
  text += `

📌 <b>Состояние</b>
Статус: <b>${escapeHtml(stTitle)}</b>`;
  if (vitrinaLine) text += `

${vitrinaLine}`;

  const assignedId = lead.assigned_user_id ? Number(lead.assigned_user_id) : null;
  if (assignedId) {
    let assignedWho = 'id:' + assignedId;
    try {
      const au = await db.getUserById(assignedId);
      if (au?.tg_username) assignedWho = '@' + au.tg_username;
    } catch {}
    const assignIcon = assignedId === Number(actorUserId) ? '👤 Ты' : `📌 ${assignedWho}`;
    text += `
Назначена: <b>${escapeHtml(assignIcon)}</b>`;
  }

  text += `

📝 <b>Запрос бренда</b>
${msgEsc}`;
  if (replyEsc) text += `

✍️ <b>Последний ответ</b>
${replyEsc}`;
  if (threadBlock) {
    text += `

💬 <b>Последние сообщения</b>
${threadBlock}`;
    if (thread.length > 3) text += `
<i>Показаны последние 3 из ${thread.length}.</i>`;
  } else {
    text += `

💬 <b>Последние сообщения</b>
${escapeHtml(creatorLeadThreadEmptyStateText(st, { canManualReply }))}`;
  }

  if (notesLast.length) {
    const noteLines = notesLast.map((n) => {
      const by = n?.by ? `id:${n.by}` : 'id:?';
      const at = n?.at ? fmtTs(n.at) : '';
      const t = String(n?.text || '').trim();
      const clipped = clipText(t.replace(/\s+/g, ' '), 180);
      const tagsHtml = fmtLeadNoteTags(n?.tags || extractLeadNoteTags(t));
      return `• <code>${escapeHtml(by)}</code>${at ? ` • <i>${escapeHtml(at)}</i>` : ''}: ${escapeHtml(clipped)}${tagsHtml}`;
    }).join('\n');
    text += `

📝 <b>Последние заметки</b>
${noteLines}`;
    if (notes.length > 3) text += `
<i>Показаны последние 3 из ${notes.length}.</i>`;
  }

  if (canManualReply) {
    try {
      const curatorsForWs = await db.listCurators(wsId);
      const curatorIndex = buildCuratorIndexMap(curatorsForWs || []);
      const auditRows = await db.listWorkspaceAuditDetailed(wsId, {
        actionPrefix: 'lead.',
        actorUserId: 0,
        leadId: Number(lead.id),
        limit: 3,
        offset: 0,
        onlyRole: 'curator'
      });
      if (Array.isArray(auditRows) && auditRows.length) {
        const lines = auditRows.map((r) => {
          const payload = r.payload || {};
          const a = auditActorLabel(r, curatorIndex);
          const label = leadAuditActionLabel(String(r.action || ''), payload);
          return `• ${escapeHtml(fmtTs(r.created_at))} — <b>${escapeHtml(a)}</b> — ${escapeHtml(label)}`;
        }).join('\n');
        text += `

📜 <b>Последние действия</b>
${lines}`;
      }
    } catch {}
  } else {
    text += `

<i>Кураторский режим: ручной ответ недоступен — используй шаблоны, статус и заметки.</i>`;
  }

  const retKey = String(back?.ret || '').trim();
  const rPart = retKey ? retPartShort(retKey) : '';
  const af = ['all','my','free'].includes(String(back?.af || '')) ? String(back.af) : 'all';
  const listCb = (retKey === 'ci')
    ? `a:cur_inbox|s:${leadStatusToCb(back.status)}|p:${back.page}|af:${af}`
    : `a:ws_leads|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`;

  const auditCb = `a:ca|w:${wsId}|u:0|l:${lead.id}|p:0|al:0|b:lv|s:${leadStatusToCb(back.status)}|g:${back.page}${rPart}`;
  const kb = new InlineKeyboard();

  if (canManualReply) {
    kb.text('✍️ Ответить', `a:lead_reply|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .text('⚡ Шаблоны', `a:lead_tpls|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row()
      .text('💬 В работу', `a:lead_set|id:${lead.id}|st:ip|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .text('✅ Закрыть', `a:lead_set|id:${lead.id}|st:cl|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row()
      .text('⛔ Спам', `a:lead_set|id:${lead.id}|st:sp|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .text('📝 Заметка', `a:lead_note|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row();
    kb.text(`📝 Заметки (${notes.length})`, `a:lead_notes|id:${lead.id}|w:${wsId}|n:0|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .text('📜 Журнал', auditCb)
      .row();
  } else {
    kb.text('✅ Принять', `a:lead_tpl_send|id:${lead.id}|k:discuss|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .text('🧾 Детали', `a:lead_tpl_send|id:${lead.id}|k:brief|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row()
      .text('❌ Отказ', `a:lead_tpl_send|id:${lead.id}|k:decline|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .text('📝 Заметка', `a:lead_note|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row()
      .text(`📝 Заметки (${notes.length})`, `a:lead_notes|id:${lead.id}|w:${wsId}|n:0|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row()
      .text('⚡ Шаблоны', `a:lead_tpls|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .text('💬 В работу', `a:lead_set|id:${lead.id}|st:ip|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row()
      .text('✅ Закрыть', `a:lead_set|id:${lead.id}|st:cl|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`)
      .row();
  }

  const assignCbBase = `a:lead_assign|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`;
  if (assignedId === Number(actorUserId)) {
    kb.text('❌ Снять с себя', `${assignCbBase}|do:un`).row();
  } else if (assignedId) {
    kb.text('⚠️ Назначена другому', `${assignCbBase}|do:re`).row();
  } else {
    kb.text('👤 Взять себе', `${assignCbBase}|do:me`).row();
  }

  kb.text('🗑 Удалить', `a:lead_del_q|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(back.status)}|p:${back.page}${rPart}`).row();
  kb.row().text(creatorLeadListButtonLabel(), listCb).text('📋 Меню', 'a:menu').text('🏠 Home', 'a:home');

  const extra = { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true };
  try {
    await p0Await(ctx, stepId, `${stepId}:sendEdit`, () => safeEditOrReply(ctx, text, extra), 8000);
  } catch {
    await p0Await(ctx, stepId, `${stepId}:sendReply`, () => ctx.reply(text, extra), 8000);
  }
}

async function renderBrandLeadDialog(ctx, brandUserId, leadId, wsId = 0) {
  const id = Number(leadId || 0);
  if (!id) {
    await safeEditOrReply(ctx, '⚠️ Диалог не найден. Открой сообщение с ответом креатора и нажми “💬 Диалог”.', { parse_mode: 'HTML', reply_markup: navKb('a:menu') });
    return;
  }

  const lead = await getLeadForActorSafe(ctx, brandUserId, id);
  if (!lead) {
    await safeEditOrReply(ctx, '⚠️ Диалог не найден или удалён. Открой 📋 Меню и повтори.', { parse_mode: 'HTML', reply_markup: navKb('a:menu') });
    return;
  }

  const realWsId = Number(wsId || lead.workspace_id || 0);
  const ws = realWsId ? await db.getWorkspaceAny(realWsId) : null;
  const channel = ws?.channel_username ? '@' + String(ws.channel_username) : (ws?.title || 'Креатор');
  const dialogLabel = brandLeadDialogButtonLabel(id);
  const profileLabel = brandLeadProfileButtonLabel();
  const contactsLabel = brandLeadContactUnlockButtonLabel();

  // Prevent monetization bypass: do not reveal direct channel handle in the lead dialog
  // unless contacts were unlocked for this brand on this workspace.
  let contactsUnlocked = false;
  if (realWsId && ws) {
    const key = k(['wsp_contact', realWsId, brandUserId]);
    let redisOk = true;
    try {
      contactsUnlocked = !!(await redis.get(key));
    } catch {
      contactsUnlocked = false;
      redisOk = false;
    }

    // DB fallback ONLY when Redis is unavailable.
    if (!contactsUnlocked && !redisOk) {
      try {
        contactsUnlocked = !!(await withTimeout(db.isWorkspaceContactsUnlocked(brandUserId, realWsId), 2500, 'wsp.unlock.db'));
      } catch {
        contactsUnlocked = false;
      }
      if (contactsUnlocked) {
        try { await redis.set(key, 1, { ex: CONTACT_UNLOCK_TTL_SEC }); } catch {}
      }
    }
  }
  const channelShown = (ws?.channel_username && !contactsUnlocked) ? '🔒 скрыто' : channel;

  let credits = null;
  try { credits = await withTimeout(getBrandCreditsRedisOnly(brandUserId), 2500, 'brand.credits.redis'); } catch { credits = null; }
  const creditsNum = (credits === null || credits === undefined) ? 0 : Math.max(0, Math.trunc(Number(credits) || 0));

  const needContacts = Number(CONTACT_UNLOCK_COST || 0);
  const needsContactsTopup = (credits !== null) && needContacts > 0 && creditsNum < needContacts;
  const needLine = (credits !== null) ? brandPassContactsNeedLineHtml(creditsNum) : '';

  const who = ws ? safeCreatorDisplayName(ws) : 'Креатор';
  const when = lead.created_at ? fmtTs(lead.created_at) : '—';
  const st = normLeadStatus(lead.status);
  const statusTitle = (LEAD_STATUSES[st] || LEAD_STATUSES.new).title;

  const meta = normalizeJsonb(lead.meta) || {};
  const thread = Array.isArray(meta.thread) ? meta.thread : [];
  const threadBlock = fmtBrandLeadThread(thread, 6);
  const currentHint = contactsUnlocked
    ? `Продолжай через «✍️ Ответить» или ${brandLeadWhatNextText(id, 'contacts_open').replace(/^Продолжай через /, '').replace(/\.$/, '')}.`
    : `Продолжай через «✍️ Ответить», ${brandLeadWhatNextText(id).replace(/^Продолжай через /, '').replace(/\.$/, '')}.`;

  let text =
    `💬 <b>${escapeHtml(dialogLabel)}</b>\n\n` +
    `💡 <b>Сейчас:</b> ${escapeHtml(currentHint)}\n\n` +
    `Креатор: <b>${escapeHtml(who)}</b>\n` +
    `Канал: <b>${escapeHtml(channelShown)}</b>\n` +
    `Статус: <b>${escapeHtml(statusTitle)}</b>\n` +
    `Создано: <code>${escapeHtml(String(when))}</code>\n` +
    `${brandPassCreditsBlockLines(credits).join('\n')}\n` +
    (needLine ? `${needLine}\n` : ``);

  text += `\n<b>Заявка:</b>\n${escapeHtml(stripBrokenSurrogates(String(lead.message || '—')))}\n`;

  if (lead.reply_text) {
    text += `\n<b>Последний ответ:</b>\n${escapeHtml(stripBrokenSurrogates(String(lead.reply_text || '')))}\n`;
  }

  if (threadBlock) {
    text += `
<b>Последние сообщения:</b>
${threadBlock}`;
  } else {
    text += `
<b>Последние сообщения:</b>
${escapeHtml(brandLeadThreadEmptyStateText({ contactsUnlocked }))}`;
  }

  const kb = new InlineKeyboard();
  kb.text('✍️ Ответить', `a:blead_reply|id:${id}|w:${realWsId}`)
    .text(profileLabel, `a:wsp_open|ws:${realWsId}|m:ro|r:bl|l:${id}`)
    .row();

  if (needContacts <= 0) {
    kb.text(contactsLabel, `a:wsp_contact_req|ws:${realWsId}|r:bl|l:${id}`);
  } else if (credits === null) {
    kb.text(contactsLabel, `a:wsp_contact_req|ws:${realWsId}|r:bl|l:${id}`)
      .text('💳 Купить ещё', `a:brand_pass|ws:0|ret:wsp|rws:${realWsId}`);
  } else if (Number(creditsNum || 0) <= 0) {
    // STEP213: don't hide «Контакты» when balance is 0/unknown in Redis.
    kb.text(contactsLabel, `a:wsp_contact_req|ws:${realWsId}|r:bl|l:${id}`)
      .text('💳 Купить ещё', `a:brand_pass|ws:0|ret:wsp|rws:${realWsId}`);
  } else if (needsContactsTopup) {
    kb.text(contactsLabel, `a:wsp_contact_req|ws:${realWsId}|r:bl|l:${id}`)
      .text('💳 Купить ещё', `a:brand_pass|ws:0|ret:wsp|rws:${realWsId}`);
  } else {
    kb.text(contactsLabel, `a:wsp_contact_req|ws:${realWsId}|r:bl|l:${id}`);
  }

  kb.row().text(creatorLeadListButtonLabel(), `a:ws_leads|w:${realWsId}|s:${leadStatusToCb(st)}|p:0`);
  kb.row().text('📋 Меню', 'a:menu').text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
}

async function renderLeadNotesViewer(ctx, actorUserId, leadId, back = { wsId: null, status: 'new', page: 0, ret: '' }, notesPage = 0) {
  const stepId = 'lead_notes_view';
  const id = Number(leadId || 0);
  if (!id) {
    await safeEditOrReply(ctx, '⚠️ Не найдена заявка. Открой 📨 Заявки брендов и выбери заявку ещё раз.', { reply_markup: navKb('a:menu') });
    return;
  }

  const lead = await p0Await(ctx, stepId, `${stepId}:getLead`, () => getLeadForActorSafe(ctx, actorUserId, id), 4500);
  if (!lead) {
    await safeEditOrReply(ctx, '⚠️ Заявка не найдена или удалена. Открой 📨 Заявки брендов и выбери заявку ещё раз.', { reply_markup: navKb('a:menu') });
    return;
  }

  const wsId = Number(lead.workspace_id);
  const ws = await p0Await(ctx, stepId, `${stepId}:getWs`, () => db.getWorkspaceAny(wsId), 4500);
  if (!ws) {
    await safeEditOrReply(ctx, '⚠️ Канал не найден или нет доступа. Открой 📋 Меню → выбери канал заново.', { reply_markup: navKb('a:ws_list') });
    return;
  }

  const isOwner = Number(ws.owner_user_id) === Number(actorUserId);
  const isAdmin = isSuperAdminTg(ctx.from?.id);

  const channel = ws.channel_username ? '@' + ws.channel_username : ws.title;
  const notesRaw = (lead.meta && Array.isArray(lead.meta.curator_notes)) ? lead.meta.curator_notes : [];
  const notes = normalizeLeadNotes(notesRaw);
  const total = notes.length;

  const pageSize = 6;
  const ordered = notes.slice().reverse(); // newest first
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const pg = Math.max(0, Math.min(totalPages - 1, Number(notesPage || 0)));

  const slice = ordered.slice(pg * pageSize, (pg + 1) * pageSize);

  // Resolve authors (best-effort)
  const byIds = Array.from(new Set(slice.map(n => Number(n?.by || 0)).filter(Boolean)));
  const usersMap = new Map();
  if (byIds.length) {
    try {
      const rows = await db.listUsersByIds(byIds);
      for (const r of (rows || [])) usersMap.set(Number(r.id), r);
    } catch {}
  }

  const roleLabel = (byId) => {
    const row = usersMap.get(Number(byId)) || null;
    if (Number(byId) === Number(ws.owner_user_id)) return 'owner';
    if (row?.tg_id && isSuperAdminTg(Number(row.tg_id))) return 'admin';
    return 'curator';
  };

  const whoLabel = (byId, roleHint = '') => {
    const role = String(roleHint || '').trim() || (byId ? roleLabel(byId) : '—');
    const row = usersMap.get(Number(byId)) || null;
    const uname = row?.tg_username ? '@' + String(row.tg_username).replace(/^@/, '') : null;
    if (uname) return `${escapeHtml(uname)} <code>id:${escapeHtml(String(byId))}</code>${role ? ` • <i>${escapeHtml(role)}</i>` : ''}`;
    return `<code>id:${escapeHtml(String(byId || '?'))}</code>${role ? ` • <i>${escapeHtml(role)}</i>` : ''}`;
  };

  let text =
    `📝 <b>Заметки</b> • заявка #${lead.id}\n` +
    `Канал: <b>${escapeHtml(channel)}</b>\n` +
    `Всего: <b>${total}</b>\n` +
    `Стр: <b>${pg + 1}/${totalPages}</b>\n\n`;

  if (!total) {
    text += 'Пока нет заметок.\nНажми “📝 Добавить заметку”, чтобы оставить внутренний комментарий.';
  } else {
    const lines = slice.map((n, i) => {
      const by = Number(n?.by || 0);
      const at = n?.at ? fmtTs(n.at) : '';
      const t = String(n?.text || '').trim();
      const clipped = clipText(stripBrokenSurrogates(t).replace(/\s+/g, ' '), 420);
      const roleHint = String(n?.role || '').trim().toLowerCase();
      const tagsHtml = fmtLeadNoteTags(n?.tags || extractLeadNoteTags(t));
      const head = `• <b>${i + 1 + (pg * pageSize)}</b> • ${whoLabel(by, roleHint)}${at ? ` • <i>${escapeHtml(at)}</i>` : ''}`;
      return `${head}\n${escapeHtml(clipped)}${tagsHtml}`;
    }).join('\n\n');

    text += lines;
  }

  const backStatus = normLeadStatus(String(back?.status || 'new'));
  const backPage = Number(back?.page || 0);
  const retKey = String(back?.ret || '').trim();
  const rPart = retKey ? retPartShort(retKey) : '';

  const leadViewCb = `a:lead_view|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(backStatus)}|p:${backPage}${rPart}`;
  const addCb = `a:lead_note|id:${lead.id}|w:${wsId}|s:${leadStatusToCb(backStatus)}|p:${backPage}|nb:${pg}${rPart}`;

  const kb = new InlineKeyboard();

  if (totalPages > 1) {
    if (pg > 0) kb.text('⬅️', `a:lead_notes|id:${lead.id}|w:${wsId}|n:${pg - 1}|s:${leadStatusToCb(backStatus)}|p:${backPage}${rPart}`);
    if (pg < totalPages - 1) kb.text('➡️', `a:lead_notes|id:${lead.id}|w:${wsId}|n:${pg + 1}|s:${leadStatusToCb(backStatus)}|p:${backPage}${rPart}`);
    kb.row();
  }

  kb.text('📝 Добавить заметку', addCb).row();

  kbNavRow(kb, leadViewCb);

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
}




// --- Brand Applications Inbox (Creator → Brand) ---

// Deal stages (no migrations; stored in brand_applications.meta.deal_stage)
const DEAL_STAGES = {
  negotiation: { id: 'negotiation', icon: '💬', label: 'Переговоры' },
  deal: { id: 'deal', icon: '🤝', label: 'Договорились' },
  paid: { id: 'paid', icon: '💳', label: 'Оплата' },
  done: { id: 'done', icon: '✅', label: 'Завершено' },
  lost: { id: 'lost', icon: '🗑', label: 'Потеряно' },
  all: { id: 'all', icon: '📌', label: 'Все' },
};

function normDealStage(s) {
  const k = String(s || '').toLowerCase().trim();
  return DEAL_STAGES[k] ? k : 'negotiation';
}

function dealStageTitle(s) {
  const k = String(s || '').toLowerCase().trim();
  const d = DEAL_STAGES[k];
  if (!d) return '📌 Сделка';
  return `${d.icon} ${d.label}`;
}

function dealStageWhatNow(s) {
  const k = normDealStage(s);
  if (k === 'negotiation') return 'обсудить условия или отправить шаблон';
  if (k === 'deal') return 'зафиксировать договорённость и перейти к оплате';
  if (k === 'paid') return 'дождаться оплаты или подтвердить завершение';
  if (k === 'done') return 'сделка завершена';
  if (k === 'lost') return 'сделка остановлена';
  return 'продолжить работу по сделке';
}

function dealStageButtonLabel(targetStage, activeStage) {
  const title = dealStageTitle(targetStage);
  return normDealStage(targetStage) === normDealStage(activeStage) ? `• ${title}` : title;
}


function brandAppWhatNow(status, opts = {}) {
  const st = normLeadStatus(status);
  const pending = !!opts.pending;
  const dealStage = opts.dealStage ? normDealStage(opts.dealStage) : '';

  if (pending) return 'дождаться завершения принятия и нажать «Проверить заявку»';
  if (st === 'new') return 'решить, принимать ли заявку и открывать ли диалог';
  if (st === 'in_progress') {
    if (dealStage) return `продолжить диалог или открыть «${dealStageTitle(dealStage)}»`;
    return 'ответить креатору или обновить внутренний статус';
  }
  if (st === 'closed') return 'заявка закрыта; при необходимости можно вернуть её в работу';
  if (st === 'spam') return 'заявка скрыта как спам; при ошибке её можно пересмотреть';
  return 'продолжить работу по заявке';
}

function brandAppStatusActionLabel(targetStatus, activeStatus) {
  const st = normLeadStatus(targetStatus);
  const active = normLeadStatus(activeStatus);
  const base = st === 'in_progress'
    ? (st === active ? '💬 В работе' : '💬 В работу')
    : st === 'closed'
      ? (st === active ? '✅ Закрыто' : '✅ Закрыть')
      : st === 'spam'
        ? '⛔ Спам'
        : (LEAD_STATUSES[st]?.title || LEAD_STATUSES[st]?.label || st);
  return st === active ? `• ${base}` : base;
}

function brandAppOpenButtonLabel(appId = 0) {
  const id = Math.max(0, Number(appId || 0));
  return id ? `✉️ Заявка #${id}` : '✉️ Заявка';
}

function brandAppNoticeOpenButtonLabel(appId = 0, kind = 'reply') {
  const id = Math.max(0, Number(appId || 0));
  const noticeKind = String(kind || 'reply').trim().toLowerCase();
  if (noticeKind === 'new_app') return brandAppOpenButtonLabel(id);
  return id ? `💬 Диалог #${id}` : '💬 Диалог';
}

function brandAppDealButtonLabel() {
  return '📌 Стадия сделки';
}

function brandAppListReturnButtonLabel() {
  return '📨 К заявкам';
}

function brandDealsListReturnButtonLabel() {
  return '📌 К сделкам';
}

function brandAppNoticeWhatNext(appId = 0, status = 'new', dealStage = '', kind = 'reply') {
  const openLabel = brandAppNoticeOpenButtonLabel(appId, kind);
  const dealLabel = brandAppDealButtonLabel();
  const st = normLeadStatus(status);
  const ds = String(dealStage || '').trim() ? normDealStage(dealStage) : '';

  if (st === 'new') return `Открой «${openLabel}» и реши, принимать ли заявку.`;
  if (ds) return `Открой «${openLabel}» или «${dealLabel}» и продолжи работу.`;
  return `Открой «${openLabel}» и продолжи диалог.`;
}

function brandAppNoticeKb(appId = 0, opts = {}) {
  const page = Math.max(0, Number(opts.page || 0));
  const status = normLeadStatus(opts.status || 'new');
  const dealStageRaw = String(opts.dealStage || '').trim();
  const dealStage = dealStageRaw ? normDealStage(dealStageRaw) : '';
  const kind = String(opts.kind || 'reply').trim().toLowerCase();
  const dismiss = opts.dismiss !== false;
  const kb = new InlineKeyboard();

  kb.text(brandAppNoticeOpenButtonLabel(appId, kind), `a:brand_app_view|id:${Number(appId || 0)}|s:${leadStatusToCb(status)}|p:${page}`);
  if (status !== 'new' || dealStage) {
    kb.text(brandAppDealButtonLabel(), `a:brand_deal_view|id:${Number(appId || 0)}|st:${dealStage || 'negotiation'}|p:0|ab:${leadStatusToCb(status)}.${page}`);
  }
  if (dismiss) kb.row().text('🗑 Убрать', 'a:nd');
  kb.row().text('📋 Меню', 'a:menu').text('🏠 Home', 'a:home');
  return kb;
}

function buildBrandAppServiceNoticeText({ appId = 0, kind = 'reply', brandName = '', creatorName = '', body = '', status = 'new', dealStage = '' } = {}) {
  const id = Math.max(0, Number(appId || 0));
  const title = kind === 'new_app'
    ? `📝 <b>Новая заявка #${id}</b>`
    : `💬 <b>Новое сообщение по заявке #${id}</b>`;
  const bodyLabel = kind === 'new_app' ? 'Текст заявки' : 'Последнее сообщение';
  const creatorLine = creatorName ? `🧑‍🎨 Креатор: <b>${escapeHtml(String(creatorName))}</b>
` : '';
  const brandLine = brandName ? `🏷 Бренд: <b>${escapeHtml(String(brandName))}</b>
` : '';
  const stageLine = dealStage ? `📌 Сделка: <b>${escapeHtml(dealStageTitle(dealStage))}</b>
` : '';
  const preview = clipText(String(body || '').replace(/\s+/g, ' ').trim(), kind === 'new_app' ? 900 : 700);
  const whatNext = brandAppNoticeWhatNext(id, status, dealStage, kind);

  return `${title}

${creatorLine}${brandLine}${stageLine}💡 <b>Сейчас:</b> ${escapeHtml(whatNext)}

<b>${bodyLabel}:</b>
${escapeHtml(preview || '—')}`;
}


function brandAppReplyButtonLabel() {
  return '✍️ Ответить креатору';
}

function brandAppReplyRecoveryKb(opts = {}) {
  const primaryLabel = String(opts.primaryLabel || '').trim();
  const primaryCb = String(opts.primaryCb || '').trim();
  const secondaryLabel = String(opts.secondaryLabel || '').trim();
  const secondaryCb = String(opts.secondaryCb || '').trim();
  const retryLabel = String(opts.retryLabel || '').trim();
  const retryCb = String(opts.retryCb || '').trim();
  const safeMode = opts.safeMode === true;
  const showReset = opts.showReset === true;
  const showHelp = opts.showHelp === true;
  const kb = new InlineKeyboard();

  if (primaryLabel && primaryCb) kb.text(primaryLabel, primaryCb);
  if (retryLabel && retryCb) kb.text(retryLabel, retryCb);
  if ((primaryLabel && primaryCb) || (retryLabel && retryCb)) kb.row();

  if (secondaryLabel && secondaryCb) kb.text(secondaryLabel, secondaryCb);
  if (secondaryLabel && secondaryCb) kb.row();

  if (showHelp) kb.text('🧭 Помощь', 's:help');
  if (showReset) kb.text('🔄 Сбросить ввод', 's:reset_input');
  if (showHelp || showReset) kb.row();

  kb.text(safeMode ? '📋 Меню (безопасный режим)' : '📋 Меню', safeMode ? 's:menu' : 'a:menu');
  kb.text('🏠 Home', safeMode ? 's:home' : 'a:home');
  return kb;
}

function buildBrandAppReplyPromptText({ appId = 0, creatorName = '', subjectLabel = '', contextLabel = '', secondaryLabel = '' } = {}) {
  const id = Math.max(0, Number(appId || 0));
  const subject = String(subjectLabel || '').trim() || `заявке #${id}`;
  const context = String(contextLabel || '').trim() || brandAppOpenButtonLabel(id);
  const secondary = String(secondaryLabel || '').trim() || '📝 Заявки';
  const creatorLine = creatorName ? `🧑‍🎨 Креатор: <b>${escapeHtml(String(creatorName))}</b>\n` : '';

  return `✍️ <b>Ответить креатору по ${escapeHtml(subject)}</b>

${creatorLine}💡 <b>Сейчас:</b> Напиши одно сообщение — я отправлю его креатору и сохраню в текущем диалоге.

<i>Если передумаешь — открой «${escapeHtml(context)}» или вернись в «${escapeHtml(secondary)}».</i>`;
}

function buildBrandAppReplyRecoveryText({ appId = 0, kind = 'open_error', subjectLabel = '', contextLabel = '', secondaryLabel = '', replyLabel = '' } = {}) {
  const id = Math.max(0, Number(appId || 0));
  const subject = String(subjectLabel || '').trim() || `заявке #${id}`;
  const context = String(contextLabel || '').trim() || brandAppOpenButtonLabel(id);
  const secondary = String(secondaryLabel || '').trim() || '📝 Заявки';
  const reply = String(replyLabel || '').trim() || brandAppReplyButtonLabel();

  if (kind === 'not_accepted') {
    return `⏳ <b>Заявка #${id} ещё не принята</b>

💡 <b>Сейчас:</b> Открой «${escapeHtml(context)}», нажми «✅ Принять», а потом снова используй «${escapeHtml(reply)}».`;
  }

  if (kind === 'degraded') {
    return `⛔ <b>Сейчас нельзя открыть ввод ответа по ${escapeHtml(subject)}</b>

${DEGRADED_COPY.line}

💡 <b>Сейчас:</b> Открой «${escapeHtml(context)}» или вернись в «${escapeHtml(secondary)}».`;
  }

  if (kind === 'missing_id') {
    return `⚠️ <b>Не удалось открыть ввод ответа</b>

💡 <b>Сейчас:</b> Вернись в «${escapeHtml(secondary)}», открой нужный экран заново и снова нажми «${escapeHtml(reply)}».`;
  }

  if (kind === 'not_found') {
    return `⚠️ <b>${escapeHtml(subject)} больше недоступна</b>

💡 <b>Сейчас:</b> Вернись в «${escapeHtml(secondary)}» и открой актуальную карточку ещё раз.`;
  }

  if (kind === 'no_access') {
    return `⛔ <b>Нет доступа к этой заявке</b>

💡 <b>Сейчас:</b> Вернись в «${escapeHtml(secondary)}» и открой только свои рабочие заявки.`;
  }

  if (kind === 'rate_limit') {
    return `⏳ <b>Слишком часто</b>

💡 <b>Сейчас:</b> Подожди пару минут и снова отправь ответ. Текущий экран остаётся тем же: «${escapeHtml(context)}».`;
  }

  if (kind === 'too_short') {
    return `⚠️ <b>Ответ слишком короткий</b>

💡 <b>Сейчас:</b> Напиши чуть подробнее или вернись в «${escapeHtml(context)}».`;
  }

  if (kind === 'too_long') {
    return `⚠️ <b>Ответ слишком длинный</b>

💡 <b>Сейчас:</b> Укороти текст до 2000 символов и отправь снова.`;
  }

  if (kind == 'no_creator_tg') {
    return `⚠️ <b>Не удалось отправить ответ</b>

💡 <b>Сейчас:</b> У креатора нет Telegram-контакта для доставки. Открой «${escapeHtml(context)}» и проверь карточку заявки.`;
  }

  return `⚠️ <b>Не удалось открыть ввод ответа по ${escapeHtml(subject)}</b>

💡 <b>Сейчас:</b> Открой «${escapeHtml(context)}» ещё раз или вернись в «${escapeHtml(secondary)}».`;
}


function brandAppThreadEmptyStateText(status, opts = {}) {
  const st = normLeadStatus(status);
  const pending = opts.pending === true;
  const role = String(opts.role || 'app').trim().toLowerCase();
  const dealStage = opts.dealStage ? normDealStage(opts.dealStage) : '';

  if (role === 'deal') {
    if (dealStage === 'lost') return 'Истории пока нет. Сделка остановлена до первого сообщения.';
    if (dealStage === 'done') return 'Истории пока нет. Сделка завершена без переписки в этой карточке.';
    return 'Истории пока нет. Нажми «✍️ Ответить» или «⚡ Шаблоны» — первое сообщение появится здесь.';
  }

  if (pending) return 'Истории пока нет. Дождись завершения принятия и открой карточку ещё раз.';
  if (st === 'new') return 'Истории пока нет. Сначала реши, принимать ли заявку.';
  if (st === 'in_progress') return 'Истории пока нет. Нажми «✍️ Ответить креатору» или «⚡ Шаблоны» — первое сообщение появится здесь.';
  if (st === 'closed') return 'Истории пока нет. Заявка закрыта без переписки в этой карточке.';
  if (st === 'spam') return 'Истории пока нет. Заявка скрыта до начала переписки.';
  return 'Истории пока нет. Первое сообщение появится здесь.';
}

function creatorBrandAppThreadEmptyStateText(status) {
  const st = normLeadStatus(status);
  if (st === 'new') return 'Истории пока нет. Бренд ещё не принял заявку — дождись решения здесь.';
  if (st === 'in_progress') return 'Истории пока нет. Нажми «✍️ Ответить бренду» — первое сообщение появится в этом диалоге.';
  if (st === 'closed') return 'Истории пока нет. Диалог закрыт без сообщений.';
  if (st === 'spam') return 'Истории пока нет. Бренд не продолжил эту заявку.';
  return 'Истории пока нет. Первое сообщение появится здесь.';
}

function creatorLeadThreadEmptyStateText(status, opts = {}) {
  const st = normLeadStatus(status);
  const canManualReply = opts.canManualReply !== false;

  if (st === 'closed') return 'Истории пока нет. Диалог закрыт без сообщений.';
  if (st === 'spam') return 'Истории пока нет. Диалог скрыт как спам до первого сообщения.';
  if (canManualReply) return 'Истории пока нет. Нажми «✍️ Ответить» или «⚡ Шаблоны» — первое сообщение появится здесь.';
  return 'Истории пока нет. Используй шаблоны, статус или заметку — первое сообщение появится здесь.';
}

function brandLeadThreadEmptyStateText(opts = {}) {
  const contactsUnlocked = opts.contactsUnlocked === true;
  if (contactsUnlocked) return 'Истории пока нет. Нажми «✍️ Ответить» — первое сообщение появится в этом диалоге.';
  return 'Истории пока нет. Нажми «✍️ Ответить» — первое сообщение появится здесь, а витрина и контакты останутся рядом.';
}

function creatorBrandAppWhatNow(status) {
  const st = normLeadStatus(status);
  if (st === 'new') return 'дождаться решения бренда; кнопка ответа появится после принятия заявки';
  if (st === 'in_progress') return 'нажать «✍️ Ответить бренду» и отправить сообщение в этот диалог';
  if (st === 'closed') return 'диалог завершён; следи за обновлениями, если бренд вернётся';
  if (st === 'spam') return 'заявка скрыта брендом; новых сообщений по ней, скорее всего, не будет';
  return 'следить за ответом бренда по этой заявке';
}


