async function renderBxPublicView(ctx, userId, wsId, offerId, page = 0, opts = {}) {
  const o = CFG.VERIFICATION_ENABLED
    ? await safeUserVerifications(() => db.getBarterOfferPublicWithVerified(offerId), () => db.getBarterOfferPublic(offerId))
    : await db.getBarterOfferPublic(offerId);

  const fail = async (msg) => {
    if (ctx.callbackQuery) return ctx.answerCallbackQuery({ text: msg, show_alert: true });
    return ctx.reply(msg);
  };

  if (!o) return fail('Оффер не найден.');
  if (String(o.status || '').toUpperCase() !== 'ACTIVE') return fail('Оффер закрыт.');
  if (!o.network_enabled) return fail('Оффер вне сети.');

  const isOwner = Number(o.owner_user_id) === Number(userId);
  const ch = safeCreatorDisplayName({ title: o.ws_title, channel_username: o.channel_username });
  const contactRaw = (o.contact || '').trim();
  const contact = isOwner ? contactRaw : '';
  const hasContact = Boolean(contactRaw);

  // Contacts unlock (Brand Pass) also gates contact leakage in offer description.
  // Redis-first; DB fallback ONLY when Redis is unavailable.
  let unlocked = false;
  if (!isOwner && userId && wsId) {
    const key = k(['wsp_contact', wsId, userId]);
    let redisOk = true;
    try {
      unlocked = !!(await redis.get(key));
    } catch {
      unlocked = false;
      redisOk = false;
    }

    if (!unlocked && !redisOk) {
      try {
        unlocked = !!(await withTimeout(db.isWorkspaceContactsUnlocked(userId, wsId), 2500, 'wsp.unlock.db'));
      } catch {
        unlocked = false;
      }
      if (unlocked) {
        try { await redis.set(key, 1, { ex: CONTACT_UNLOCK_TTL_SEC }); } catch {}
      }
    }
  }

  // Anti-bypass: offer title/description must not leak contacts to non-owners before unlock.
  // Title redaction is conditional (unlocked => show raw); description redaction is also conditional.
  let titleTxt = String(o.title || '');
  if (!isOwner && !unlocked && titleTxt) {
    try {
      const r = redactContactsInText(titleTxt);
      titleTxt = r.text;
    } catch {
      // keep raw title
    }
  }
  const titleHtml = escapeHtml(titleTxt);

  let descTxt = String(o.description || '');
  if (!isOwner && !unlocked && descTxt) {
    try {
      const r = redactContactsInText(descTxt);
      descTxt = r.text;
    } catch {
      // keep raw description
    }
  }
  const descHtml = escapeHtml(descTxt);

  let partnerBlock = '';
  if (o.partner_folder_id) {
    try {
      const folder = await db.getChannelFolder(Number(o.partner_folder_id));
      if (folder && Number(folder.workspace_id) === Number(wsId)) {
        const items = await db.listChannelFolderItems(folder.id);
        const safeTitle = escapeHtml(String(folder.title || '').slice(0, 40));
        if (isOwner) {
          const shown = items.slice(0, 10).map((i) => i.channel_username);
          const more = items.length > shown.length ? `\n… и ещё ${items.length - shown.length}` : '';
          partnerBlock = `\n\nПартнёры (папка “${safeTitle}”, ${items.length}):\n${shown.map((x) => escapeHtml(x)).join('\n')}${more}`;
        } else {
          partnerBlock = `\n\nПартнёры (папка “${safeTitle}”, ${items.length}).`;
        }
      }
    } catch (_) {}
  }

  const metaLines = offerMetaLinesHtml(o.meta);

  const text =
    `🤝 <b>Оффер #${o.id}</b>\n\n` +
    `Категория: <b>${escapeHtml(bxCategoryLabel(o.category))}</b>\n` +
    `Формат: <b>${escapeHtml(bxTypeLabel(o.offer_type))}</b>\n` +
    `Оплата: <b>${escapeHtml(bxCompLabel(o.compensation_type))}</b>\n\n` +
    `${metaLines ? `${metaLines}\n\n` : ''}` +
    `<b>${titleHtml}</b>\n\n` +
    `${descHtml}${partnerBlock}\n\n` +
    `Канал: <b>${escapeHtml(ch)}${o.creator_verified ? ' ✅' : ''}</b>\n` +
    `${isOwner ? (contact ? `Контакт: <b>${escapeHtml(contact)}</b>\n` : '') : (hasContact ? `Контакты: <b>🔒 скрыты</b>\n` : '')}` +
    `\nЕсли бот не может проверить каналы — попроси админа добавить бота в канал-спонсор.`;

  const h = normBxHome(opts.h, Number(wsId || 0) ? BX_HOME.BX_OPEN : BX_HOME.MENU);

// STEP176: UI anti-spam for paid Intro (token-lock, Redis-only)
const asyncRetryEnabled = isMonetizationAsyncRetryEnabled();
const introLockKey = asyncRetryEnabled ? k(['mon', 'lock', 'intro_open', offerId, userId]) : '';
let introPending = false;
if (introLockKey) {
  try { introPending = !!(await redis.get(introLockKey)); } catch { introPending = false; }
}

const kb = new InlineKeyboard();
if (introPending) {
  kb.text('📥 Inbox', `a:bx_inbox|ws:${wsId}|p:0|h:${h}`)
    .text('🔄 Обновить', `a:bx_pub|ws:${wsId}|o:${offerId}|p:${page}|h:${h}`)
    .row();
} else {
  kb.text('💬 Написать', `a:bx_msg|ws:${wsId}|o:${offerId}|p:${page}|h:${h}`);
}

  let canOfficial = false;
  if (CFG.OFFICIAL_PUBLISH_ENABLED) {
    try {
      canOfficial = isOwner || (await isModerator({ id: userId }, ctx.from?.id));
    } catch {
      canOfficial = isOwner;
    }
  }

  if (canOfficial) {
    const cb = isOwner
      ? `a:off_manage|ws:${wsId}|o:${offerId}|p:${page}|back:my`
      : `a:off_manage|ws:${wsId}|o:${offerId}|p:${page}|h:${h}`;
    kb.row().text('📣 Офиц.канал', cb);
  }

  kb.row().text('🚩 Жалоба', `a:bx_report_offer|ws:${wsId}|o:${offerId}|p:${page}|h:${h}`);
  // Back: for non-owners this wsId feed is inaccessible; send them to Brand Mode feed
  const backCb = isOwner ? `a:bx_my|ws:${wsId}|p:0` : `a:bx_feed|ws:0|p:0|h:${h}`;
  kbNavRow(kb, backCb);

  const send = (text, extra) => safeEditOrReply(ctx, text, extra, true);
  await send(text, { parse_mode: 'HTML', reply_markup: kb });
}

// -----------------------------
// Official channel publishing (barter offers)
// -----------------------------

function offerDeepLink(offerId) {
  const u = String(CFG.BOT_USERNAME || '').trim();
  if (!u) return '';
  return `https://t.me/${u}?start=bxo_${offerId}`;
}


function offerShareUrl(offerId, title = '', description = '') {
  const link = offerDeepLink(offerId);
  if (!link) return '';
  let t = String(title || '').trim();
  // Anti-bypass: share text must never contain contacts (title might include them).
  if (t) {
    try {
      const r = redactContactsInText(t);
      t = r.text;
    } catch {
      // keep raw title
    }
  }
  // Anti-bypass: share only title + bot link. No description (may contain contacts).
  const text = t ? `🎬 ${t}` : 'Оффер';
  return `https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent(text)}`;
}

function truncateText(s, maxLen = 800) {
  const txt = String(s || '').trim();
  const cps = Array.from(txt);
  if (cps.length <= maxLen) return txt;
  const keep = Math.max(0, Number(maxLen) - 1);
  return cps.slice(0, keep).join('') + '…';
}

async function safeOfficialPosts(primaryFn, fallbackFn) {
  try {
    return await primaryFn();
  } catch (e) {
    if (isMissingRelationError(e, 'official_posts')) {
      return await fallbackFn();
    }
    throw e;
  }
}

async function notifyOfficialQueueAdmins(api, input = {}) {
  try {
    const admins = Array.isArray(CFG.SUPER_ADMIN_TG_IDS) ? CFG.SUPER_ADMIN_TG_IDS : [];
    if (!admins.length) return { sent: 0, skipped: 'no_admins' };

    const offerId = Number(input.offerId || 0);
    const wsId = Number(input.wsId || 0);
    if (!offerId) return { sent: 0, skipped: 'no_offer' };

    const kind = String(input.kind || 'queue').toLowerCase(); // paid | manual | queue
    const rl = await rateLimit(k(['notify', 'offq', offerId, kind]), { limit: 1, windowSec: 10 * 60 });
    if (!rl.allowed) return { sent: 0, skipped: 'rate_limited' };

    const offerTitle = String(input.offerTitle || '').trim();
    const wsTitle = String(input.wsTitle || '').trim();
    const channelUsername = String(input.channelUsername || '').trim();

    const fromTag = String(input.fromTag || '').trim();
    const days = input.days ? Number(input.days) : null;
    const paymentId = input.paymentId ? Number(input.paymentId) : null;

    const head = kind === 'paid'
      ? '💳 <b>OFFICIAL: оплата за слот</b>'
      : '📝 <b>OFFICIAL: заявка в очередь</b>';

    const offerLine = offerTitle ? `#${offerId} · ${escapeHtml(offerTitle.slice(0, 64))}` : `#${offerId}`;
    const wsLine = channelUsername
      ? `Канал: <b>@${escapeHtml(channelUsername.replace(/^@/, ''))}</b>`
      : (wsTitle ? `Канал: <b>${escapeHtml(wsTitle.slice(0, 80))}</b>` : '');

    const meta = [];
    if (days) meta.push(`Слот: <b>${days}д</b>`);
    if (paymentId) meta.push(`PaymentId: <code>${paymentId}</code>`);
    if (fromTag) meta.push(`От: <b>${escapeHtml(fromTag)}</b>`);

    const lines = [];
    lines.push(head, '');
    lines.push(`Оффер: <b>${offerLine}</b>`);
    if (wsLine) lines.push(wsLine);
    if (meta.length) {
      lines.push('');
      for (const x of meta) lines.push(x);
    }
    lines.push('', '<i>Действия: открыть карточку или опубликовать.</i>');
    const text = lines.join('\\n');

    const kb = new InlineKeyboard();
    if (wsId) kb.text('✅ Опубликовать', `a:off_pub|ws:${wsId}|o:${offerId}|p:0`).row();
    if (wsId) kb.text('📣 Карточка', `a:off_manage|ws:${wsId}|o:${offerId}|p:0`);
    kb.text('📋 Очередь', 'a:off_queue|p:0');

    let sent = 0;
    for (const a of admins) {
      const adminId = Number(a || 0);
      if (!adminId) continue;
      const res = await sendMessageWithFallback(api, adminId, text, { parse_mode: 'HTML', reply_markup: kb });
      if (res && res.ok) sent += 1;
    }
    return { sent };
  } catch (e) {
    return { sent: 0, error: String(e?.message || e) };
  }
}


// Official publish/remove idempotency: per-offer token lock (prevents duplicate posts on parallel actions).
const OFFICIAL_OFFER_LOCK_TTL_SEC = 180;

// STEP129: protect against Vercel hard-kill during slow Telegram API responses.
// grammY supports AbortSignal as the last argument for API calls.
// Keep this below typical serverless timeout to ensure we can revert DB markers.
const OFFICIAL_TG_CALL_TIMEOUT_MS = envInt('TG_HTTP_TIMEOUT_MS', 5500, { min: 1000, max: 30000 });
const OFFICIAL_TG_MEDIA_CALL_TIMEOUT_MS = envInt('TG_HTTP_MEDIA_TIMEOUT_MS', 15000, { min: 1000, max: 60000 });

// STEP214: active self-heal for "PUBLISHING" stuck states.
// In serverless, the function may die after DB reserve (status=PUBLISHING), which blocks UI.
// We schedule a delayed QStash verification job to either attach message_id (if known) or
// reset status back to PENDING (unblock queue / allow manual retry).
const OFFICIAL_PUBLISH_SELFHEAL_DELAY_SEC = envInt('OFFICIAL_PUBLISH_SELFHEAL_DELAY_SEC', 90, { min: 20, max: 900 });
const OFFICIAL_PUBLISH_SELFHEAL_MIN_AGE_SEC = envInt('OFFICIAL_PUBLISH_SELFHEAL_MIN_AGE_SEC', 75, { min: 20, max: 600 });
const OFFICIAL_PUBLISH_SELFHEAL_MSGID_TTL_SEC = envInt('OFFICIAL_PUBLISH_SELFHEAL_MSGID_TTL_SEC', 3 * 24 * 60 * 60, { min: 600, max: 14 * 24 * 60 * 60 });

function tgTimeoutSignal(ms = OFFICIAL_TG_CALL_TIMEOUT_MS) {
  const t = Math.max(1, Number(ms) || 1);
  try {
    // Node.js 20+
    return AbortSignal.timeout(t);
  } catch {
    const ac = new AbortController();
    setTimeout(() => { try { ac.abort(); } catch {} }, t);
    return ac.signal;
  }
}

function officialPublishMsgIdKey(offerId) {
  return k(['official', 'pub', 'msgid', String(offerId)]);
}

async function writeOfficialPublishMsgIdBreadcrumb(offerId, messageId, source = 'unknown') {
  try {
    const oid = Number(offerId || 0);
    const mid = Number(messageId || 0);
    if (!oid || !mid) return;
    await redis.set(officialPublishMsgIdKey(oid), String(mid), { ex: OFFICIAL_PUBLISH_SELFHEAL_MSGID_TTL_SEC });
    // Best-effort breadcrumbs for /api/health
    try {
      await redis.set(k(['mon', 'official', 'last_at']), new Date().toISOString(), { ex: 14 * 24 * 60 * 60 });
      await redis.set(k(['mon', 'official', 'last_offer_id']), String(oid), { ex: 14 * 24 * 60 * 60 });
      await redis.set(k(['mon', 'official', 'last_source']), String(source || 'unknown').slice(0, 32), { ex: 14 * 24 * 60 * 60 });
    } catch {}
  } catch {
    // ignore
  }
}

async function enqueueOfficialPublishVerifyJob(input = {}) {
  try {
    if (!CFG.OFFICIAL_PUBLISH_ENABLED) return { ok: false, skipped: 'disabled' };
    const offerId = Number(input.offerId || 0);
    if (!offerId) return { ok: false, skipped: 'no_offer' };

    const url = getQStashDeliveryUrl('/api/qstash/official-publish-verify');
    if (!url) return { ok: false, error: 'public_base_url_missing' };

    const health = getQStashLibHealth();
    if (!health.available) return { ok: false, error: 'qstash_disabled' };
    if (!process.env.QSTASH_TOKEN || !process.env.QSTASH_CURRENT_SIGNING_KEY) return { ok: false, error: 'qstash_not_configured' };

    const wsId = Number(input.wsId || 0) || 0;
    const offerTitle = String(input.offerTitle || '').trim();
    const channelChatId = Number(input.channelChatId || CFG.OFFICIAL_CHANNEL_ID || 0) || 0;

    // Dedup by (offerId + rounded minute) so multiple retries don't flood QStash.
    const minute = Math.floor(Date.now() / 60000);
    const dedupId = `offpv:${offerId}:m:${minute}`;

    const delaySec = Math.max(1, Math.min(
      900,
      Number(input.delaySec || OFFICIAL_PUBLISH_SELFHEAL_DELAY_SEC) || OFFICIAL_PUBLISH_SELFHEAL_DELAY_SEC
    ));

    await qstashPublishJSON({
      url,
      body: {
        offerId,
        wsId,
        offerTitle,
        channelChatId,
        minAgeSec: OFFICIAL_PUBLISH_SELFHEAL_MIN_AGE_SEC,
        queued_at: new Date().toISOString(),
      },
      deduplicationId: dedupId,
      delaySec,
      retries: 3,
      timeout: '20s',
    });

    return { ok: true };
  } catch (e) {
    return { ok: false, error: String(e?.message || e || 'error') };
  }
}


function parseOfficialPublishReserveEpoch(input = {}) {
  try {
    const direct = Number(input.reserveEpoch || input.reserve_epoch || 0);
    if (Number.isFinite(direct) && direct > 0) return Math.trunc(direct);
  } catch {}
  try {
    const raw = String(input.reserveAt || input.reservedAt || input.reserve_at || '').trim();
    if (!raw) return 0;
    const t = Date.parse(raw);
    if (!Number.isFinite(t) || t <= 0) return 0;
    return Math.floor(t / 1000);
  } catch {
    return 0;
  }
}


async function enqueueOfficialPublishDeliverJob(input = {}) {
  try {
    if (!CFG.OFFICIAL_PUBLISH_ENABLED) return { ok: false, skipped: 'disabled' };
    const offerId = Number(input.offerId || 0);
    if (!offerId) return { ok: false, skipped: 'no_offer' };

    const url = getQStashDeliveryUrl('/api/qstash/official-publish-deliver');
    if (!url) return { ok: false, error: 'public_base_url_missing' };

    const health = getQStashLibHealth();
    if (!health.available) return { ok: false, error: 'qstash_disabled' };
    if (!process.env.QSTASH_TOKEN || !process.env.QSTASH_CURRENT_SIGNING_KEY) return { ok: false, error: 'qstash_not_configured' };

    const wsId = Number(input.wsId || 0) || 0;
    const offerTitle = String(input.offerTitle || '').trim();
    const channelChatId = Number(input.channelChatId || CFG.OFFICIAL_CHANNEL_ID || 0) || 0;

    const prevStatus = String(input.prevStatus || '').trim();
    const attempt = Number(input.attempt || 0) || 0;

    // Prefer a stable reserve key (DB updated_at) for deduplication.
    // Fallback to minute-bucketed dedup if reserve timestamp is missing.
    const minute = Math.floor(Date.now() / 60000);
    const action = String(input.action || 'publish').slice(0, 16) || 'publish';
    const reserveEpoch = parseOfficialPublishReserveEpoch(input);
    const dedupId = reserveEpoch
      ? `offpd:${offerId}:${action}:r:${reserveEpoch}:a:${attempt}`
      : `offpd:${offerId}:${action}:m:${minute}:a:${attempt}`;

    await qstashPublishJSON({
      url,
      body: {
        offerId,
        wsId,
        offerTitle,
        channelChatId,
        prevStatus,
        attempt,
        action,
        ...(reserveEpoch ? { reserveEpoch } : {}),
        ...(input.reserveAt ? { reserveAt: String(input.reserveAt) } : {}),
        queued_at: new Date().toISOString(),
      },
      deduplicationId: dedupId,
      retries: 5,
      timeout: '20s',
    });

    return { ok: true };
  } catch (e) {
    return { ok: false, error: String(e?.message || e || 'error') };
  }
}

async function buildOfficialOfferPost(offerRow, opts = {}) {
  const forCaption = Boolean(opts.forCaption);

  const offerId = Number(offerRow.id);
  const ch = offerRow.channel_username ? `@${offerRow.channel_username}` : (offerRow.ws_title || 'канал');
  const contact = (offerRow.contact || '').trim();
  const link = offerDeepLink(offerId);

  const title = escapeHtml(String(offerRow.title || ''));
  const desc = escapeHtml(truncateText(offerRow.description || '', forCaption ? 520 : 900));
  const cat = escapeHtml(bxCategoryLabel(offerRow.category));
  const fmt = escapeHtml(bxTypeLabel(offerRow.offer_type));
  const comp = escapeHtml(bxCompLabel(offerRow.compensation_type));
  const metaLines = offerMetaLinesHtml(offerRow.meta);

  const text =
    `🤝 <b>Коллабка</b> · оффер #${offerId}

` +
    `Категория: <b>${cat}</b>
` +
    `Формат: <b>${fmt}</b>
` +
    `Оплата: <b>${comp}</b>

` +
    `${metaLines ? `${metaLines}

` : ''}` +
    `<b>${title}</b>

` +
    `${desc}

` +
    `Канал: <b>${escapeHtml(ch)}${offerRow.creator_verified ? ' ✅' : ''}</b>
` +
    `${contact ? `Контакт: <b>${escapeHtml(contact)}</b>
` : ''}` +
    `${link ? `
Открыть в боте: ${escapeHtml(link)}` : ''}`;

  const kb = new InlineKeyboard();
  if (link) kb.url('🚀 Открыть оффер', link);
  return { text, kb };
}

// STEP129: helper to parse offerId from the official channel post text/caption
function extractOfferIdFromOfficialPostText(raw) {
  const s = String(raw || '').trim();
  if (!s) return null;
  const m = /оффер\s*#\s*(\d+)/i.exec(s);
  if (!m) return null;
  const id = Number(m[1]);
  return Number.isFinite(id) && id > 0 ? id : null;
}

async function queueOfficialPublishToOfficialChannel(api, offerId, opts = {}) {
  // If QStash is not configured, fallback to the legacy synchronous publish path.
  try {
    const health = getQStashLibHealth();
    const url = getQStashDeliveryUrl('/api/qstash/official-publish-deliver');
    const ready = health.available && !!url && !!process.env.QSTASH_TOKEN && !!process.env.QSTASH_CURRENT_SIGNING_KEY;
    if (!ready) return await publishOfferToOfficialChannel(api, offerId, opts);
  } catch {
    // If anything is off, keep working in legacy mode.
    return await publishOfferToOfficialChannel(api, offerId, opts);
  }

  if (!CFG.OFFICIAL_PUBLISH_ENABLED) throw new Error('OFFICIAL_PUBLISH_ENABLED=false');

  const channelId = Number(CFG.OFFICIAL_CHANNEL_ID || 0);
  if (!channelId) throw new Error('OFFICIAL_CHANNEL_ID is missing');

  const lockKey = k(['lock', 'official', String(offerId)]);
  const lock = await acquireLock(lockKey, OFFICIAL_OFFER_LOCK_TTL_SEC);
  if (!lock) return { ok: false, locked: true, reason: 'busy' };
  try {

  // Normalize placement type.
  const placementRaw = String(opts.placementType || 'MANUAL').toUpperCase();
  const keepExpiry = !!opts.keepExpiry;

  // Existing DB record (if any).
  const existing = await safeOfficialPosts(() => db.getOfficialPostByOfferId(offerId), async () => null);
  let placementType = placementRaw;
  if (placementType === 'UPDATE') {
    placementType = existing?.placement_type ? String(existing.placement_type).toUpperCase() : 'MANUAL';
  }
  if (!['MANUAL', 'PAID'].includes(placementType)) placementType = 'MANUAL';

  const offer = CFG.VERIFICATION_ENABLED
    ? await safeUserVerifications(() => db.getBarterOfferPublicWithVerified(offerId), () => db.getBarterOfferPublic(offerId))
    : await db.getBarterOfferPublic(offerId);

  if (!offer) throw new Error('Offer not found');
  if (String(offer.status || '').toUpperCase() !== 'ACTIVE') throw new Error('Offer is not active');
  if (!offer.network_enabled) throw new Error('Offer is not in network');

  // Slot params
  const defaultDays = Math.max(1, Number(CFG.OFFICIAL_MANUAL_DEFAULT_DAYS || 3));
  const days = Math.max(
    1,
    Number(opts.days || existing?.slot_days || defaultDays)
  );

  // Expiry: keep existing if asked, otherwise (re)compute.
  let slotExpiresAt = null;
  if (keepExpiry && existing?.slot_expires_at) {
    try { slotExpiresAt = new Date(existing.slot_expires_at).toISOString(); } catch { slotExpiresAt = null; }
  }
  if (!slotExpiresAt) slotExpiresAt = new Date(Date.now() + days * 24 * 60 * 60 * 1000).toISOString();

  const paymentId = opts.paymentId ? Number(opts.paymentId) : (existing?.payment_id ? Number(existing.payment_id) : null);
  const publishedByUserId = opts.publishedByUserId ? Number(opts.publishedByUserId) : null;

  const prevStatus = existing?.status ? String(existing.status).toUpperCase() : null;

  // DB-level reserve before async delivery (safety if Redis degrades).
  const reserved = await safeOfficialPosts(
    () => db.atomicReserveOfficialPublish(offerId, {
      channelChatId: channelId,
      placementType,
      paymentId,
      slotDays: days,
      slotExpiresAt,
      publishedByUserId
    }),
    async () => null
  );
  if (!reserved) return { ok: false, locked: true, reason: 'publishing' };

  const reserveAt = reserved?.updated_at ? String(reserved.updated_at) : new Date().toISOString();

  // Schedule a delayed self-heal check to avoid long "PUBLISHING" stalls.
  try {
    await enqueueOfficialPublishVerifyJob({
      offerId,
      wsId: offer.workspace_id,
      offerTitle: offer.title,
      channelChatId: channelId,
    });
  } catch {}

  // Enqueue async delivery.
  const q = await enqueueOfficialPublishDeliverJob({
    offerId,
    wsId: offer.workspace_id,
    offerTitle: offer.title,
    channelChatId: channelId,
    prevStatus: prevStatus || 'PENDING',
    action: String(opts.placementType || 'publish'),
    reserveAt,
  });

  if (!q || !q.ok) {
    // Fail-open for UI: reset to PENDING/prevStatus so operator can retry.
    try {
      await safeOfficialPosts(
        () => db.setOfficialPostStatus(offerId, prevStatus || 'PENDING', { lastError: `enqueue_failed:${String(q?.error || 'error').slice(0, 160)}` }),
        async () => null
      );
    } catch {}
    return { ok: false, error: 'enqueue_failed' };
  }

  return { ok: true, queued: true, placementType, days, slotExpiresAt };

  } finally {
    await releaseLock(lockKey, lock.token);
  }
}


async function publishOfferToOfficialChannel(api, offerId, opts = {}) {
  if (!CFG.OFFICIAL_PUBLISH_ENABLED) throw new Error('OFFICIAL_PUBLISH_ENABLED=false');

  const channelId = Number(CFG.OFFICIAL_CHANNEL_ID || 0);
  if (!channelId) throw new Error('OFFICIAL_CHANNEL_ID is missing');

  const lockKey = k(['lock', 'official', String(offerId)]);
  const lock = await acquireLock(lockKey, OFFICIAL_OFFER_LOCK_TTL_SEC);
  if (!lock) return { ok: false, locked: true, reason: 'busy' };
  try {

  // Normalize placement type.
  const placementRaw = String(opts.placementType || 'MANUAL').toUpperCase();
  const keepExpiry = !!opts.keepExpiry;

  // Existing DB record (if any).
  const existing = await safeOfficialPosts(() => db.getOfficialPostByOfferId(offerId), async () => null);
  let placementType = placementRaw;
  if (placementType === 'UPDATE') {
    placementType = existing?.placement_type ? String(existing.placement_type).toUpperCase() : 'MANUAL';
  }
  if (!['MANUAL', 'PAID'].includes(placementType)) placementType = 'MANUAL';

  const offer = CFG.VERIFICATION_ENABLED
    ? await safeUserVerifications(() => db.getBarterOfferPublicWithVerified(offerId), () => db.getBarterOfferPublic(offerId))
    : await db.getBarterOfferPublic(offerId);

  if (!offer) throw new Error('Offer not found');
  if (String(offer.status || '').toUpperCase() !== 'ACTIVE') throw new Error('Offer is not active');
  if (!offer.network_enabled) throw new Error('Offer is not in network');

  // Slot params
  const defaultDays = Math.max(1, Number(CFG.OFFICIAL_MANUAL_DEFAULT_DAYS || 3));
  const days = Math.max(
    1,
    Number(opts.days || existing?.slot_days || defaultDays)
  );

  // Expiry: keep existing if asked, otherwise (re)compute.
  let slotExpiresAt = null;
  if (keepExpiry && existing?.slot_expires_at) {
    try { slotExpiresAt = new Date(existing.slot_expires_at).toISOString(); } catch { slotExpiresAt = null; }
  }
  if (!slotExpiresAt) slotExpiresAt = new Date(Date.now() + days * 24 * 60 * 60 * 1000).toISOString();

  const paymentId = opts.paymentId ? Number(opts.paymentId) : (existing?.payment_id ? Number(existing.payment_id) : null);
  const publishedByUserId = opts.publishedByUserId ? Number(opts.publishedByUserId) : null;

  const prevStatus = existing?.status ? String(existing.status).toUpperCase() : null;

  // DB-level reserve before sending to Telegram (safety if Redis degrades).
  const reserved = await safeOfficialPosts(
    () => db.atomicReserveOfficialPublish(offerId, {
      channelChatId: channelId,
      placementType,
      paymentId,
      slotDays: days,
      slotExpiresAt,
      publishedByUserId
    }),
    async () => null
  );
  if (!reserved) return { ok: false, locked: true, reason: 'publishing' };

  // STEP214: schedule a delayed self-heal check to avoid long "PUBLISHING" stalls.
  // Best-effort: never fail publish if QStash is not configured.
  try {
    await enqueueOfficialPublishVerifyJob({
      offerId,
      wsId: offer.workspace_id,
      offerTitle: offer.title,
      channelChatId: channelId,
    });
  } catch {}


  try {

  // Build message
  const hasMedia = !!(offer.media_file_id && String(offer.media_type || '').trim());
  const built = await buildOfficialOfferPost(offer, { forCaption: hasMedia });
  const text = built.text;
  const replyMarkup = built.kb;

  const isActive = String(existing?.status || '').toUpperCase() === 'ACTIVE' && existing?.message_id;
  let messageId = isActive ? Number(existing.message_id) : null;

  async function tryEditExisting() {
    if (!messageId) return false;
    // Try both (text vs media).
    try {
      await api.editMessageText(channelId, messageId, text, { parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
      return true;
    } catch {}
    try {
      await api.editMessageCaption(channelId, messageId, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
      return true;
    } catch {}
    return false;
  }

  const edited = await tryEditExisting();
  if (!edited) {
    // Send new message
    let sent;
    const mt = String(offer.media_type || '').toLowerCase();
    const fid = String(offer.media_file_id || '').trim();

    if (hasMedia && fid) {
      if (mt === 'photo') {
        sent = await api.sendPhoto(channelId, fid, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal(OFFICIAL_TG_MEDIA_CALL_TIMEOUT_MS));
      } else if (mt === 'video') {
        sent = await api.sendVideo(channelId, fid, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal(OFFICIAL_TG_MEDIA_CALL_TIMEOUT_MS));
      } else if (mt === 'animation' || mt === 'gif') {
        sent = await api.sendAnimation(channelId, fid, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal(OFFICIAL_TG_MEDIA_CALL_TIMEOUT_MS));
      } else {
        sent = await api.sendMessage(channelId, text, { parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
      }
    } else {
      sent = await api.sendMessage(channelId, text, { parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
    }

    const newId = sent?.message_id ? Number(sent.message_id) : null;
    if (!newId) throw new Error('Failed to publish: missing message_id');

    // STEP214: breadcrumb message_id in Redis ASAP (helps self-heal if DB write fails).
    await writeOfficialPublishMsgIdBreadcrumb(offerId, newId, 'send');

    // Remove old message (best-effort) if it existed.
    if (messageId && newId !== messageId) {
      try { await api.deleteMessage(channelId, messageId, tgTimeoutSignal()); } catch {}
    }
    messageId = newId;
  }

  // Persist ACTIVE post record
  await safeOfficialPosts(
    () => db.setOfficialPostActive(offerId, {
      channelChatId: channelId,
      messageId,
      placementType,
      paymentId,
      slotDays: days,
      slotExpiresAt,
      publishedByUserId
    }),
    async () => null
  );

  // STEP214: keep breadcrumb even after DB write (helps on webhook/DB glitches).
  await writeOfficialPublishMsgIdBreadcrumb(offerId, messageId, 'db_active');

  // If this was a paid placement, mark payment as "applied" (best-effort).
  if (placementType === 'PAID' && paymentId && publishedByUserId) {
    try {
      await db.markPaymentApplied(paymentId, publishedByUserId, `official_publish:${offerId}`);
    } catch {
      // ignore
    }
  }

  return { ok: true, messageId, placementType, days, slotExpiresAt };

  } catch (e) {
    // Best-effort revert publishing marker.
    try {
      await safeOfficialPosts(
        () => db.setOfficialPostStatus(offerId, prevStatus || 'PENDING', { lastError: String(e && (e.message || e) || 'publish_failed') }),
        async () => null
      );
    } catch {}
    throw e;
  }

  } finally {
    await releaseLock(lockKey, lock.token);
  }
}



export async function deliverOfficialPublishReserved(api, offerId, opts = {}) {
  if (!CFG.OFFICIAL_PUBLISH_ENABLED) throw new Error('OFFICIAL_PUBLISH_ENABLED=false');

  const channelIdFallback = Number(CFG.OFFICIAL_CHANNEL_ID || 0);
  if (!channelIdFallback) throw new Error('OFFICIAL_CHANNEL_ID is missing');

  const lockKey = k(['lock', 'official', String(offerId)]);
  const lock = await acquireLock(lockKey, OFFICIAL_OFFER_LOCK_TTL_SEC);
  if (!lock) return { ok: false, locked: true, reason: 'busy' };
  try {

  const prevStatus = String(opts.prevStatus || 'PENDING').toUpperCase();

  // Read current post record (DB-truth)
  const existing = await safeOfficialPosts(() => db.getOfficialPostByOfferId(offerId), async () => null);
  const st = String(existing?.status || 'NONE').toUpperCase();
  if (st !== 'PUBLISHING') return { ok: true, skipped: true, reason: 'not_publishing', status: st };

  const channelId = Number(existing?.channel_chat_id || channelIdFallback);
  const placementType = String(existing?.placement_type || 'MANUAL').toUpperCase();
  const paymentId = existing?.payment_id ? Number(existing.payment_id) : null;
  const days = Math.max(1, Number(existing?.slot_days || CFG.OFFICIAL_MANUAL_DEFAULT_DAYS || 3));

  let slotExpiresAt = null;
  if (existing?.slot_expires_at) {
    try { slotExpiresAt = new Date(existing.slot_expires_at).toISOString(); } catch { slotExpiresAt = null; }
  }
  if (!slotExpiresAt) slotExpiresAt = new Date(Date.now() + days * 24 * 60 * 60 * 1000).toISOString();

  const publishedByUserId = existing?.published_by_user_id ? Number(existing.published_by_user_id) : null;

  const offer = CFG.VERIFICATION_ENABLED
    ? await safeUserVerifications(() => db.getBarterOfferPublicWithVerified(offerId), () => db.getBarterOfferPublic(offerId))
    : await db.getBarterOfferPublic(offerId);

  if (!offer) throw new Error('Offer not found');
  if (String(offer.status || '').toUpperCase() !== 'ACTIVE') throw new Error('Offer is not active');
  if (!offer.network_enabled) throw new Error('Offer is not in network');

  // Build message
  const hasMedia = !!(offer.media_file_id && String(offer.media_type || '').trim());
  const built = await buildOfficialOfferPost(offer, { forCaption: hasMedia });
  const text = built.text;
  const replyMarkup = built.kb;

  // If message_id already exists (e.g., UPDATE), prefer edit.
  let messageId = existing?.message_id ? Number(existing.message_id) : null;

  // If DB is still missing message_id but we have a Redis breadcrumb (send succeeded earlier),
  // prefer editing/attaching instead of sending a duplicate.
  if (!messageId) {
    try {
      const mid = Number(await redis.get(officialPublishMsgIdKey(offerId))) || 0;
      if (mid > 0) messageId = mid;
    } catch {}
  }

  let tgDone = false;
  let tgSource = '';

  async function tryEditExisting() {
    if (!messageId) return false;
    try {
      await api.editMessageText(channelId, messageId, text, { parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
      return true;
    } catch {}
    try {
      await api.editMessageCaption(channelId, messageId, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
      return true;
    } catch {}
    return false;
  }

  const edited = await tryEditExisting();
  if (edited && messageId) {
    tgDone = true;
    tgSource = 'edit';
    // Breadcrumb message_id ASAP (helps self-heal if DB write fails).
    await writeOfficialPublishMsgIdBreadcrumb(offerId, messageId, 'edit');
  }
  if (!edited) {
    // Send new message
    let sent;
    const mt = String(offer.media_type || '').toLowerCase();
    const fid = String(offer.media_file_id || '').trim();

    if (hasMedia && fid) {
      if (mt === 'photo') {
        sent = await api.sendPhoto(channelId, fid, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal(OFFICIAL_TG_MEDIA_CALL_TIMEOUT_MS));
      } else if (mt === 'video') {
        sent = await api.sendVideo(channelId, fid, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal(OFFICIAL_TG_MEDIA_CALL_TIMEOUT_MS));
      } else if (mt === 'animation' || mt === 'gif') {
        sent = await api.sendAnimation(channelId, fid, { caption: text, parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal(OFFICIAL_TG_MEDIA_CALL_TIMEOUT_MS));
      } else {
        sent = await api.sendMessage(channelId, text, { parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
      }
    } else {
      sent = await api.sendMessage(channelId, text, { parse_mode: 'HTML', reply_markup: replyMarkup }, tgTimeoutSignal());
    }

    const newId = sent?.message_id ? Number(sent.message_id) : null;
    if (!newId) throw new Error('Failed to publish: missing message_id');

    // Breadcrumb message_id in Redis ASAP (helps self-heal if DB write fails).
    await writeOfficialPublishMsgIdBreadcrumb(offerId, newId, 'send');

    tgDone = true;
    tgSource = 'send';

    // Remove old message (best-effort) if it existed.
    if (messageId && newId !== messageId) {
      try { await api.deleteMessage(channelId, messageId, tgTimeoutSignal()); } catch {}
    }
    messageId = newId;
  }

  // Ensure we always have a breadcrumb before the DB finalize step.
  // (If DB write fails, self-heal can still attach.)
  await writeOfficialPublishMsgIdBreadcrumb(offerId, messageId, 'pre_db');

  // Persist ACTIVE post record
  await safeOfficialPosts(
    () => db.setOfficialPostActive(offerId, {
      channelChatId: channelId,
      messageId,
      placementType,
      paymentId,
      slotDays: days,
      slotExpiresAt,
      publishedByUserId
    }),
    async () => null
  );

  // Keep breadcrumb even after DB write (helps on webhook/DB glitches).
  await writeOfficialPublishMsgIdBreadcrumb(offerId, messageId, 'db_active');

  // If this was a paid placement, mark payment as "applied" (best-effort).
  if (placementType === 'PAID' && paymentId && publishedByUserId) {
    try {
      await db.markPaymentApplied(paymentId, publishedByUserId, `official_publish:${offerId}`);
    } catch {
      // ignore
    }
  }

  return { ok: true, messageId, placementType, days, slotExpiresAt };

  } catch (e) {
    const errMsg = String(e && (e.message || e) || 'publish_failed');

    // If Telegram operation already succeeded (send/edit), do NOT revert to PENDING.
    // Keep PUBLISHING + breadcrumb, schedule verify, and ACK to avoid QStash immediate retries.
    if (tgDone && messageId) {
      try {
        await writeOfficialPublishMsgIdBreadcrumb(offerId, messageId, `tg_${tgSource || 'done'}_db_error`);
      } catch {}

      try {
        await safeOfficialPosts(
          () => db.setOfficialPostStatus(offerId, 'PUBLISHING', { lastError: `post_sent_db_error:${errMsg}` }),
          async () => null
        );
      } catch {}

      try {
        await enqueueOfficialPublishVerifyJob({
          offerId,
          wsId: offer?.workspace_id || 0,
          offerTitle: offer?.title || '',
          channelChatId: channelId,
          delaySec: 20,
        });
      } catch {}

      return { ok: true, partial: true, messageId, reason: 'db_finalize_failed', will_selfheal: true };
    }

    // Otherwise: best-effort revert publishing marker (unblock UI) and let QStash retry.
    try {
      await safeOfficialPosts(
        () => db.setOfficialPostStatus(offerId, prevStatus || 'PENDING', { lastError: errMsg }),
        async () => null
      );
    } catch {}
    throw e;
  } finally {
    await releaseLock(lockKey, lock.token);
  }
}

async function removeOfficialOfferPost(api, offerId, reason = 'REMOVED') {
  const existing = await safeOfficialPosts(() => db.getOfficialPostByOfferId(offerId), async () => null);
  if (!existing) return { removed: false };
  const lockKey = k(['lock', 'official', String(offerId)]);
  const lock = await acquireLock(lockKey, OFFICIAL_OFFER_LOCK_TTL_SEC);
  if (!lock) return { removed: false, locked: true, reason: 'busy' };
  try {
  const channelId = Number(existing.channel_chat_id || 0);
  const msgId = Number(existing.message_id || 0);
  if (channelId && msgId) {
    try {
      const text = reason === 'EXPIRED'
        ? '⌛️ Размещение истекло.'
        : '📴 Размещение снято.';
      try {
        await api.editMessageText(channelId, msgId, text, { parse_mode: 'HTML' }, tgTimeoutSignal());
      } catch (_) {
        try { await api.editMessageCaption(channelId, msgId, { caption: text, parse_mode: 'HTML' }, tgTimeoutSignal()); } catch (_) {}
      }
    } catch (_) {}
  }

  await safeOfficialPosts(
    () => db.setOfficialPostStatus(offerId, reason, { lastError: null }),
    async () => null,
  );

  return { removed: true };
  } finally {
    await releaseLock(lockKey, lock.token);
  }
}

async function renderOfficialManageView(ctx, userId, wsId, offerId, page = 0, back = '') {
  if (!CFG.OFFICIAL_PUBLISH_ENABLED) {
    if (ctx.callbackQuery) await ctx.answerCallbackQuery({ text: 'Официальный канал выключен.', show_alert: true });
    return;
  }

  const offer = CFG.VERIFICATION_ENABLED
    ? await safeUserVerifications(() => db.getBarterOfferPublicWithVerified(offerId), () => db.getBarterOfferPublic(offerId))
    : await db.getBarterOfferPublic(offerId);

  if (!offer) {
    if (ctx.callbackQuery) await ctx.answerCallbackQuery({ text: 'Оффер не найден.', show_alert: true });
    return;
  }

  const isOwner = Number(offer.owner_user_id) === Number(userId);
  const isMod = await isModerator({ id: userId }, ctx.from?.id);
  if (!isOwner && !isMod) {
    if (ctx.callbackQuery) await ctx.answerCallbackQuery({ text: 'Нет доступа.', show_alert: true });
    return;
  }

  const post = await safeOfficialPosts(() => db.getOfficialPostByOfferId(offerId), async () => null);
  const st = String(post?.status || 'NONE').toUpperCase();
  const isPendingLike = (st === 'PENDING' || st === 'PUBLISHING');

  const statusLabel = {
    NONE: '—',
    PENDING: '⏳ Pending',
    PUBLISHING: '⏳ Публикуется',
    ACTIVE: '✅ Active',
    REMOVED: '📴 Removed',
    EXPIRED: '⌛️ Expired',
    ERROR: '⚠️ Error',
  }[st] || st;

  const expiresLine = post?.slot_expires_at ? `
Слот до: <b>${escapeHtml(new Date(post.slot_expires_at).toLocaleString('ru-RU'))}</b>` : '';
  const mode = String(CFG.OFFICIAL_PUBLISH_MODE || 'manual').toLowerCase();

  const rawU = String(CFG.OFFICIAL_CHANNEL_USERNAME || '').trim();
  const chU = rawU.replace(/^@/, '');
  const chHandle = chU ? `@${chU}` : String(CFG.OFFICIAL_CHANNEL_ID || '').trim();
  const chUrl = chU ? `https://t.me/${chU}` : '';

  const modeHint = mode === 'paid'
    ? 'paid — слот покупается за Stars, модератор публикует.'
    : (mode === 'manual'
      ? 'manual — заявка в очередь, модератор публикует.'
      : (mode === 'mixed' ? 'mixed — можно заявкой или покупкой за Stars.' : ''));

  const pricesLine = (mode === 'paid' || mode === 'mixed')
    ? OFFICIAL_DURATIONS.map((d) => `${d.label}: ${d.price} Stars`).join(' · ')
    : '';
  const pricesBlock = pricesLine ? `

Тарифы: <b>${escapeHtml(pricesLine)}</b>` : '';

  const chHtml = chUrl ? `<a href="${escapeHtml(chUrl)}">${escapeHtml(chHandle)}</a>` : escapeHtml(chHandle);

  const text = `📣 <b>Официальный канал</b>

Оффер: <b>#${offerId}</b>
Статус: <b>${escapeHtml(statusLabel)}</b>${expiresLine}

Режим: <b>${escapeHtml(mode)}</b>
<i>${escapeHtml(modeHint)}</i>
Канал: <b>${chHtml}</b>${pricesBlock}`;

  const kb = new InlineKeyboard();

  if (chUrl) kb.url('📢 Открыть канал', chUrl).row();


  const canRequest = isOwner && (mode === 'manual' || mode === 'mixed');
  if (canRequest) {
    if (st === 'PENDING') {
      kb.text('⏳ В очереди (отменить)', `a:off_req_cancel|ws:${wsId}|o:${offerId}|p:${page}|back:${back}`).row();
    } else if (st === 'PUBLISHING') {
      // publishing in progress: hide queue actions
    } else if (st !== 'ACTIVE') {
      kb.text('📝 В очередь публикаций', `a:off_req_home|ws:${wsId}|o:${offerId}|p:${page}|back:${back}`).row();
    }
  }

  if (isOwner && (mode === 'paid' || mode === 'mixed')) {
    kb.text('💳 Купить размещение', `a:off_buy_home|ws:${wsId}|o:${offerId}|p:${page}|back:${back}`).row();
  }
  const canPublishManual = isMod && (mode === 'manual' || mode === 'mixed');
  // Commit F: in paid mode allow publish only if there is a paid PENDING record
  const canPublishPaid = isMod && (mode === 'paid' || mode === 'mixed') && isPendingLike && post?.payment_id;
  if (canPublishManual || canPublishPaid) {
    kb.text('✅ Опубликовать сейчас', `a:off_pub|ws:${wsId}|o:${offerId}|p:${page}|back:${back}`).row();
  }

  if (isMod && st === 'PUBLISHING') {
    kb.text('🩺 Проверить статус', `a:off_verify|ws:${wsId}|o:${offerId}|p:${page}|back:${back}`).row();
  }

  if (isMod && st === 'ACTIVE') {
    kb.text('♻️ Обновить пост', `a:off_upd|ws:${wsId}|o:${offerId}|p:${page}|back:${back}`).row();
  }

  if (isMod && (st === 'ACTIVE' || isPendingLike)) {
    kb.text('🗑 Снять', `a:off_rm|ws:${wsId}|o:${offerId}|p:${page}|back:${back}`).row();
  }

  const backSafe = String(back || '').trim();
  const backToOfferCb = (backSafe === 'my' || backSafe === 'arch' || backSafe === 'feed')
    ? `a:bx_view|ws:${wsId}|o:${offerId}|back:${backSafe}|p:${page}`
    : `a:bx_pub|ws:${wsId}|o:${offerId}|p:${page}|h:bo`;
  kb.text('⬅️ Назад к офферу', backToOfferCb);

  const send = (text, extra) => safeEditOrReply(ctx, text, extra, true);
  await send(text, { parse_mode: 'HTML', reply_markup: kb });
}


