      const ws = await db.getWorkspace(u.id, wsId);
      if (!ws) return ctx.answerCallbackQuery({ text: 'Нет доступа.' });

      const cur = Array.isArray(ws.profile_verticals) ? ws.profile_verticals.map(String) : [];
      const has = cur.includes(key);
