      const req = await db.createMatchingRequest(u.id, tier.id, 0);
      await setExpectText(ctx.from.id, { type: 'match_brief', requestId: req.id, wsId, count: tier.count, ret: String(p.ret || ''), bpr: String(p.bpr || '') });

