async function adminGetBroadcastPendingSnapshot() {
  try {
    const snapRaw = await redis.get(k(['broadcast', 'pending_deliveries']));
    if (!snapRaw) return { ok: true, snap: null };
    let snap = snapRaw;
    if (typeof snapRaw === 'string') {
      try { snap = JSON.parse(snapRaw); } catch { snap = null; }
    }
    if (!snap || typeof snap !== 'object') return { ok: true, snap: null };
    const bid = Number(snap.broadcast_id ?? snap.broadcastId) || 0;
    const pc = Number(snap.pending_count ?? snap.pendingCount ?? snap.pending) || 0;
    return {
      ok: true,
      snap: {
        ts: snap.ts ? String(snap.ts) : '',
        broadcast_id: bid > 0 ? bid : 0,
        pending_count: pc,
      },
    };
  } catch (e) {
    return { ok: false, error: String(e?.message || e) };
  }
}

async function adminClearBroadcastPendingSnapshot() {
  try {
    await redis.del(k(['broadcast', 'pending_deliveries']));
    return { ok: true };
  } catch (e) {
    return { ok: false, error: String(e?.message || e) };
  }
}


async function renderAdminOps(ctx, { banner = '' } = {}) {
  // Access is checked in the callback handler via isSuperAdminTg().
  let r = null;
  let key = null;
  let redisState = null;
  let paymentsState = null;
  const opsState = { items: [] };
  let pendingSnapshot = { visible: false };

  // Redis status banner (best-effort). This screen must stay reachable even when Redis is degraded.
  try {
    if (!CFG.UPSTASH_REDIS_REST_URL || !CFG.UPSTASH_REDIS_REST_TOKEN) {
      redisState = { configured: false };
    } else {
      r = redis;
      key = k;
      const t0 = Date.now();
      const probeKey = k(['health', 'redis_probe']);
      let writeOk = false;
      let readOk = false;
      let lastErr = null;

      try {
        await redis.set(probeKey, new Date().toISOString(), { ex: 60 });
        writeOk = true;
      } catch (e) {
        lastErr = String(e?.message || e);
      }

      try {
        const v = await redis.get(probeKey);
        readOk = v !== null && v !== undefined;
      } catch (e) {
        lastErr = lastErr || String(e?.message || e);
      }

      redisState = {
        configured: true,
        ok: writeOk && readOk,
        latencyMs: Math.max(0, Date.now() - t0),
        error: lastErr,
      };
    }

    // Payments safety banners (ENV + runtime). No DB reads.
    try {
      paymentsState = {
        hmacKey: String(CFG.PAYMENTS_PAYLOAD_HMAC_KEY || '').trim(),
        fallbackState: await getPaymentsFallbackApplyState(),
      };
    } catch {
      // ignore
    }

    // Extra ops banners (best-effort; Redis-only)
    if (r && key) {
      // Broadcast DB overload banner (metrics emitted by QStash delivery load-shedding).
      try {
        const day = new Date().toISOString().slice(0, 10).replace(/-/g, ''); // YYYYMMDD UTC
        const [cntRaw, lastAt, lastWhere] = await Promise.all([
          r.get(key(['ops', 'reasons', 'broadcast_db_overload', 'd', day])),
          r.get(key(['ops', 'reasons', 'broadcast_db_overload', 'last_at'])),
          r.get(key(['ops', 'reasons', 'broadcast_db_overload', 'last_where'])),
        ]);
        opsState.items.push({
          kind: 'broadcast_db_overload',
          count: Number(cntRaw) || 0,
          lastAt: lastAt ? String(lastAt) : '',
          lastWhere: lastWhere ? String(lastWhere) : '',
        });
      } catch {
        // ignore
      }

      // Broadcast tick deferred due to Redis degraded (cron fail-closed for mass ops).
      try {
        const day = new Date().toISOString().slice(0, 10).replace(/-/g, ''); // YYYYMMDD UTC
        const [cntRaw, lastAt, lastWhere] = await Promise.all([
          r.get(key(['ops', 'reasons', 'broadcast_tick_deferred_redis', 'd', day])),
          r.get(key(['ops', 'reasons', 'broadcast_tick_deferred_redis', 'last_at'])),
          r.get(key(['ops', 'reasons', 'broadcast_tick_deferred_redis', 'last_where'])),
        ]);
        opsState.items.push({
          kind: 'broadcast_tick_deferred_redis',
          count: Number(cntRaw) || 0,
          lastAt: lastAt ? String(lastAt) : '',
          lastWhere: lastWhere ? String(lastWhere) : '',
        });
      } catch {
        // ignore
      }

      // QStash reschedule failures (when delayed retries failed to enqueue).
      try {
        const day = new Date().toISOString().slice(0, 10).replace(/-/g, ''); // YYYYMMDD UTC
        const [cntRaw, lastAt, lastWhere, lastPayload] = await Promise.all([
          r.get(key(['ops', 'reasons', 'qstash_reschedule_failed', 'd', day])),
          r.get(key(['ops', 'reasons', 'qstash_reschedule_failed', 'last_at'])),
          r.get(key(['ops', 'reasons', 'qstash_reschedule_failed', 'last_where'])),
          r.get(key(['ops', 'reasons', 'qstash_reschedule_failed', 'last_payload'])),
        ]);
        opsState.items.push({
          kind: 'qstash_reschedule_failed',
          count: Number(cntRaw) || 0,
          lastAt: lastAt ? String(lastAt) : '',
          lastWhere: lastWhere ? String(lastWhere) : '',
          lastPayload: lastPayload ? String(lastPayload) : '',
        });
      } catch {
        // ignore
      }

      // OFFICIAL publish stuck (self-heal was triggered).
      try {
        const day = new Date().toISOString().slice(0, 10).replace(/-/g, ''); // YYYYMMDD UTC
        const [cntRaw, lastAt, lastOfferId, lastAgeSec, lastVia] = await Promise.all([
          r.get(key(['ops', 'reasons', 'official_publish_stuck', 'd', day])),
          r.get(key(['ops', 'reasons', 'official_publish_stuck', 'last_at'])),
          r.get(key(['ops', 'reasons', 'official_publish_stuck', 'last_offer_id'])),
          r.get(key(['ops', 'reasons', 'official_publish_stuck', 'last_age_sec'])),
          r.get(key(['ops', 'reasons', 'official_publish_stuck', 'last_via'])),
        ]);
        opsState.items.push({
          kind: 'official_publish_stuck',
          count: Number(cntRaw) || 0,
          lastAt: lastAt ? String(lastAt) : '',
          lastOfferId: lastOfferId ? String(lastOfferId) : '',
          lastAgeSec: Number(lastAgeSec) || 0,
          lastVia: lastVia ? String(lastVia) : '',
        });
      } catch {
        // ignore
      }
    }
  } catch {
    redisState = { configured: true, ok: false, probeFailed: true };
  }

  if (r && key) {
    pendingSnapshot = { visible: true };
    try {
      const pending = await adminGetBroadcastPendingSnapshot();
      if (!pending.ok) {
        pendingSnapshot = { visible: true, ok: false };
      } else if (!pending.snap) {
        pendingSnapshot = { visible: true, ok: true, snap: null };
      } else {
        pendingSnapshot = { visible: true, ok: true, snap: pending.snap };
      }
    } catch {
      pendingSnapshot = { visible: true, ok: false };
    }
  }

  const text = buildAdminOpsText({
    banner,
    redisState,
    paymentsState,
    opsState,
    pendingSnapshot,
  });

  const kb = new InlineKeyboard()
    .text('👥 Пользователи', 'a:admin_users|f:all|p:0')
    .text('💰 Платежи', 'a:admin_payments')
    .row()
    .text('📣 Рассылка', 'a:bc_list|p:0')
    .text('📜 Аудит', 'a:aud|h:24|p:0')
    .row()
    .text('📈 Метрики', 'a:admin_metrics|d:14')
    .row();

  kb.text('🧾 Flush ops digest', 'a:admin_ops_flush').row();
  kb.text('🧹 Clear pending snapshot', 'a:admin_ops_pending_clear').row();

  // Quick health link (if PUBLIC_BASE_URL is configured)
  if (CFG.PUBLIC_BASE_URL) {
    try {
      kb.url('🩺 /api/health', `${CFG.PUBLIC_BASE_URL}/api/health`).row();
    } catch {}
  }

  kb
    .text('⬅️ Админка', 'a:admin_home')
    .row()
    .text('📋 Меню', 'a:menu')
    .text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
}



