async function renderAdminSystem(ctx) {
  // Access is checked in the callback handler via isSuperAdminTg().
  const payAccept = await getSysBool(SYS_KEYS.pay_accept, CFG.PAYMENTS_ACCEPT_DEFAULT);
  const payAutoApply = await getSysBool(SYS_KEYS.pay_auto_apply, CFG.PAYMENTS_AUTO_APPLY_DEFAULT);
  const mfAutoApply = await getSysBool(SYS_KEYS.matchfeat_auto_apply, true);
  const bcFanout = await getSysBool(SYS_KEYS.broadcast_qstash_fanout, false);

  const payFb = await getPaymentsFallbackApplyState();
  const fbEnv = !!payFb.envEnabled;
  const fbRt = payFb.runtime || {};
  const fbRtOn = !!payFb.runtimeEnabled;
  const fbEff = !!payFb.effective;

  let fbRtLabel = 'OFF';
  if (fbRtOn) {
    let leftSec = null;
    if (Number.isFinite(fbRt.ttlSec) && fbRt.ttlSec !== null) leftSec = Number(fbRt.ttlSec);
    if (leftSec === null && fbRt.expAt) {
      try {
        const ms = Date.parse(String(fbRt.expAt));
        if (Number.isFinite(ms) && ms > 0) leftSec = Math.max(0, Math.round((ms - Date.now()) / 1000));
      } catch {}
    }
    fbRtLabel = leftSec === null ? 'ON' : `ON (~${fmtWait(leftSec)})`;
  }

  const founderState = await getFounderSaleState();
  const founderOn = !!founderState.effective?.enabled;
  const founderActive = !!founderState.active;
  const founderUntil = founderState.deadlineLabel || '—';

  let text = '⚙️ Админка → Система\n\n';
  text += `Платежи: прием ${payAccept ? 'ON' : 'OFF'} • автовыдача ${payAutoApply ? 'ON' : 'OFF'}\n`;
  text += `Match/Feat auto-apply: ${mfAutoApply ? 'ON' : 'OFF'}\n`;
  text += `Payments fallback apply: ${fbEff ? 'ON' : 'OFF'} (env ${fbEnv ? 'ON' : 'OFF'} • runtime ${fbRtLabel})\n`;
  text += `Broadcast fan-out (QStash): ${bcFanout ? 'ON' : 'OFF'}\n`;
  text += `Founder Sale: ${founderOn ? 'ON' : 'OFF'} • ${founderActive ? 'ACTIVE' : 'INACTIVE'} • до ${founderUntil}${founderState.hasOverride ? ' (ADMIN)' : ''}\n`;

  const kb = new InlineKeyboard()
    .text(`💳 Прием: ${payAccept ? 'ON' : 'OFF'}`, 'a:admin_pay_accept_toggle')
    .text(`⚙️ Автовыдача: ${payAutoApply ? 'ON' : 'OFF'}`, 'a:admin_pay_auto_toggle')
    .row()
    .text(`🎯🔥 Match/Feat: ${mfAutoApply ? 'ON' : 'OFF'}`, 'a:admin_matchfeat_auto_toggle')
    .text(`🧯 Fallback: ${fbEff ? 'ON' : 'OFF'}`, 'a:admin_pay_fb')
    .row()
    .text(`📣 QStash fan-out: ${bcFanout ? 'ON' : 'OFF'}`, 'a:admin_bc_qstash_toggle')
    .text('🛰 QStash статус', 'a:admin_qstash_status')
    .row()
    .text('🧱 Hard-skip (dead chats)', 'a:hs_home|p:0')
    .row()
    .text('🔥 Founder Sale', 'a:admin_founder')
    .row()
    .text('➕ Модератор', 'a:admin_mod_add')
    .text('📋 Модераторы', 'a:admin_mod_list')
    .row()
    .text('🎁 Подарить подписку', 'a:adm_gift')
    .row()
    .text('⬅️ Админка', 'a:admin_home')
    .row()
    .text('📋 Меню', 'a:menu')
    .text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, text, { reply_markup: kb });
}


// =====================================================
// Admin tool: Payments fallback apply (runtime TTL override)
// - Goal: allow temporary recovery when Redis pay_* sessions are missing/expired.
// - Storage: Redis-only key with TTL (see src/lib/paymentsOps.js).
// - Effective: ENV OR runtime.
// =====================================================

async function renderAdminPaymentsFallback(ctx, toast = '') {
  const st = await getPaymentsFallbackApplyState();
  const envOn = !!st.envEnabled;
  const rt = st.runtime || {};
  const rtOn = !!st.runtimeEnabled;
  const eff = !!st.effective;

  let leftSec = null;
  if (rtOn) {
    if (Number.isFinite(rt.ttlSec) && rt.ttlSec !== null) leftSec = Number(rt.ttlSec);
    if (leftSec === null && rt.expAt) {
      try {
        const ms = Date.parse(String(rt.expAt));
        if (Number.isFinite(ms) && ms > 0) leftSec = Math.max(0, Math.round((ms - Date.now()) / 1000));
      } catch {}
    }
  }

  let text = `🧯 <b>Payments fallback apply</b>\n\n`;
  if (toast) text += `<b>${escapeHtml(String(toast))}</b>\n\n`;

  text += `EFFECTIVE: <b>${eff ? 'ON' : 'OFF'}</b>\n`;
  text += `ENV: <b>${envOn ? 'ON' : 'OFF'}</b>\n`;
  text += `RUNTIME: <b>${rtOn ? 'ON' : 'OFF'}</b>`;
  if (rtOn && leftSec !== null) text += ` (ещё ~${escapeHtml(fmtWait(leftSec))})`;
  text += `\n\n`;

  text += `Когда включено: при успешном Stars-платеже, если Redis pay_* сессия истекла, бот может применить оплату по invoice payload (строго по правилам безопасности).\n\n`;
  text += `Рекомендация: держать <b>OFF</b> и включать <b>временно</b> только при инциденте.\n\n`;

  if (rtOn) {
    const by = rt.byUser ? String(rt.byUser) : (rt.byTgId ? `tg:${rt.byTgId}` : '—');
    const at = rt.at ? String(rt.at).slice(0, 19) : '—';
    const exp = rt.expAt ? String(rt.expAt).slice(0, 19) : '—';
    const reason = rt.reason ? String(rt.reason) : '—';
    text += `Enabled by: <b>${escapeHtml(by)}</b>\n`;
    text += `At: <code>${escapeHtml(at)}</code>\n`;
    text += `Until: <code>${escapeHtml(exp)}</code>\n`;
    text += `Reason: <b>${escapeHtml(reason)}</b>\n`;
  }

  const kb = new InlineKeyboard();
  kb.text('🟢 2h (incident)', 'a:admin_pay_fb_set|ttl:7200|r:incident')
    .text('🟢 12h (backlog)', 'a:admin_pay_fb_set|ttl:43200|r:backlog')
    .row()
    .text('🟢 24h (migration)', 'a:admin_pay_fb_set|ttl:86400|r:migration');
  if (rtOn) kb.text('🧹 Disable', 'a:admin_pay_fb_off');
  kb.row()
    .text('⬅️ Система', 'a:admin_sys')
    .row()
    .text('⬅️ Админка', 'a:admin_home')
    .row()
    .text('📋 Меню', 'a:menu')
    .text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}


// =====================================================
// Admin tool: Broadcast hard-skip list (dead chats)
// - Redis-only storage: k(['broadcast','hard_skip','tg', tgId]) -> { r, at }
// - Recent index (no SCAN/KEYS): k(['broadcast','hard_skip','recent']) as an LPUSH list of JSON lines.
// =====================================================

const ADMIN_HS_RECENT_KEY = k(['broadcast', 'hard_skip', 'recent']);
const ADMIN_HS_HIT_RECENT_KEY = k(['broadcast', 'hard_skip', 'hit_recent']);
const ADMIN_HS_PAGE_SIZE = 8;

const ADMIN_HS_HITS_SAMPLE_LIMIT = 800; // bounded scan window for filters/pagination (Redis-only)
const ADMIN_HS_HITS_EXPORT_LIMIT = 200;

function normalizeHardSkipReasonKey(reason) {
  const raw = String(reason || 'unknown').toLowerCase();
  if (raw.includes('bot_blocked') || raw.includes('bot was blocked') || raw.includes('blocked')) return 'bot_blocked';
  if (raw.includes('chat_not_found') || raw.includes('chat not found') || raw.includes('not found')) return 'chat_not_found';
  if (raw.includes('user_deactivated') || raw.includes('deactivated')) return 'user_deactivated';
  const slug = raw.replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40);
  if (!slug) return 'unknown';
  if (slug === 'unknown') return 'unknown';
  return 'other';
}

function adminHardSkipHitReasonDayKey(day, reasonKey) {
  return k(['broadcast', 'hard_skip', 'hit_reason', 'd', String(day || 'na'), String(reasonKey || 'unknown')]);
}

async function adminHardSkipHitReasonStatsToday() {
  const day = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const reasons = ['bot_blocked', 'chat_not_found', 'user_deactivated', 'unknown', 'other'];
  const keys = reasons.map((r) => adminHardSkipHitReasonDayKey(day, r));

  try {
    let vals = null;
    if (typeof redis.mget === 'function') {
      vals = await redis.mget(keys);
    } else {
      vals = [];
      for (const kk of keys) {
        // eslint-disable-next-line no-await-in-loop
        vals.push(await redis.get(kk));
      }
    }
    const out = [];
    for (let i = 0; i < reasons.length; i++) {
      const c = Number(vals?.[i] || 0) || 0;
      if (c > 0) out.push([reasons[i], c]);
    }
    out.sort((a, b) => Number(b[1]) - Number(a[1]));
    const total = out.reduce((s, x) => s + Number(x[1] || 0), 0);
    return { ok: true, day, total, by_reason: out };
  } catch {
    return { ok: false, day, total: 0, by_reason: [] };
  }
}


function adminHardSkipTgKey(tgId) {
  return k(['broadcast', 'hard_skip', 'tg', String(tgId)]);
}

function parseHardSkipObj(v) {
  if (!v) return null;
  if (typeof v === 'object') {
    const r = v.r || v.reason;
    const at = v.at || v.ts || v.time;
    return { r: r ? String(r) : 'unknown', at: at ? String(at) : null };
  }
  if (typeof v === 'string') {
    try {
      const o = JSON.parse(v);
      if (o && typeof o === 'object') return parseHardSkipObj(o);
    } catch {}
    const s = v.split('|')[0];
    return { r: s ? String(s) : 'unknown', at: null };
  }
  return { r: String(v), at: null };
}

async function adminHardSkipGet(tgId) {
  const id = Number(tgId || 0);
  if (!id) return { exists: false };
  try {
    const key = adminHardSkipTgKey(id);
    const v = await redis.get(key);
    if (!v) return { exists: false };
    const o = parseHardSkipObj(v);
    let ttlSec = null;
    try {
      if (typeof redis.ttl === 'function') ttlSec = Number(await redis.ttl(key));
    } catch {}
    return { exists: true, tgId: id, reason: o?.r || 'unknown', at: o?.at || null, ttlSec: Number.isFinite(ttlSec) ? ttlSec : null };
  } catch {
    return { exists: false, error: 'redis_unavailable' };
  }
}

async function adminHardSkipUnskip(tgId) {
  const id = Number(tgId || 0);
  if (!id) return false;
  try {
    await redis.del(adminHardSkipTgKey(id));
    // Best-effort: operator counter for /api/health
    try {
      const day = new Date().toISOString().slice(0, 10).replace(/-/g, '');
      await incrWithExpire(k(['broadcast', 'hard_skip', 'unskip', 'd', day]), 14 * 24 * 60 * 60);
    } catch {}
    return true;
  } catch {
    return false;
  }
}

async function adminHardSkipRecent(page = 0) {
  const p = Math.max(0, Number(page || 0) || 0);
  const start = p * ADMIN_HS_PAGE_SIZE;
  const stop = start + ADMIN_HS_PAGE_SIZE - 1;
  try {
    const raw = await redis.lrange(ADMIN_HS_RECENT_KEY, start, stop);
    const items = Array.isArray(raw) ? raw : [];
    const parsed = [];
    for (const it of items) {
      try {
        const s = typeof it === 'string' ? it : JSON.stringify(it);
        const o = JSON.parse(s);
        const tgId = Number(o?.tgId || 0);
        const r = String(o?.r || 'unknown').slice(0, 60);
        const at = o?.at ? String(o.at) : null;
        if (tgId) parsed.push({ tgId, r, at });
      } catch {
        // ignore
      }
    }
    return { ok: true, page: p, items: parsed };
  } catch {
    return { ok: false, page: p, items: [] };
  }
}



async function adminHardSkipHits(page = 0, reasonFilter = 'all') {
  const p = Math.max(0, Number(page || 0) || 0);
  const rf = String(reasonFilter || 'all').trim().toLowerCase();

  // Bounded window: we intentionally scan only the latest N hits (Redis-only).
  // This keeps the endpoint fast and avoids SCAN/KEYS.
  const scanN = ADMIN_HS_HITS_SAMPLE_LIMIT;

  try {
    const raw = await redis.lrange(ADMIN_HS_HIT_RECENT_KEY, 0, scanN - 1);
    const items = Array.isArray(raw) ? raw : [];
    const parsed = [];
    for (const it of items) {
      try {
        const s = typeof it === 'string' ? it : JSON.stringify(it);
        const o = JSON.parse(s);
        const tgId = Number(o?.tgId || 0);
        const r = String(o?.r || 'unknown').slice(0, 60);
        const at = o?.at ? String(o.at) : null;
        const broadcastId = Number(o?.broadcastId || 0) || 0;
        const userId = Number(o?.userId || 0) || 0;
        const via = o?.via ? String(o.via).slice(0, 40) : '';
        if (tgId) parsed.push({ tgId, r, at, broadcastId, userId, via });
      } catch {
        // ignore
      }
    }

    let filtered = parsed;
    if (rf && rf !== 'all') {
      filtered = parsed.filter((x) => normalizeHardSkipReasonKey(x.r) === normalizeHardSkipReasonKey(rf));
    }

    const start = p * ADMIN_HS_PAGE_SIZE;
    const slice = filtered.slice(start, start + ADMIN_HS_PAGE_SIZE);
    const hasNext = (start + ADMIN_HS_PAGE_SIZE) < filtered.length;

    return {
      ok: true,
      page: p,
      reason: rf || 'all',
      scanN,
      total: filtered.length,
      hasNext,
      items: slice,
    };
  } catch {
    return { ok: false, page: p, reason: rf || 'all', scanN: ADMIN_HS_HITS_SAMPLE_LIMIT, total: 0, hasNext: false, items: [] };
  }
}

async function adminHardSkipHitsExport(reasonFilter = 'all', limit = ADMIN_HS_HITS_EXPORT_LIMIT) {
  const rf = String(reasonFilter || 'all').trim().toLowerCase();
  const scanN = Math.max(200, Math.min(2000, ADMIN_HS_HITS_SAMPLE_LIMIT));
  try {
    const raw = await redis.lrange(ADMIN_HS_HIT_RECENT_KEY, 0, scanN - 1);
    const items = Array.isArray(raw) ? raw : [];
    const parsed = [];
    for (const it of items) {
      try {
        const s = typeof it === 'string' ? it : JSON.stringify(it);
        const o = JSON.parse(s);
        const tgId = Number(o?.tgId || 0);
        const r = String(o?.r || 'unknown').slice(0, 60);
        const at = o?.at ? String(o.at) : null;
        const broadcastId = Number(o?.broadcastId || 0) || 0;
        const userId = Number(o?.userId || 0) || 0;
        const via = o?.via ? String(o.via).slice(0, 40) : '';
        if (tgId) parsed.push({ tgId, r, at, broadcastId, userId, via });
      } catch {
        // ignore
      }
    }

    let filtered = parsed;
    if (rf && rf !== 'all') {
      filtered = parsed.filter((x) => normalizeHardSkipReasonKey(x.r) === normalizeHardSkipReasonKey(rf));
    }
    const out = filtered.slice(0, Math.max(1, Number(limit || 200) || 200));
    return { ok: true, reason: rf || 'all', scanN, total: filtered.length, items: out };
  } catch {
    return { ok: false, reason: rf || 'all', scanN: ADMIN_HS_HITS_SAMPLE_LIMIT, total: 0, items: [] };
  }
}


async function renderAdminHardSkipHome(ctx, page = 0) {
  const p = Math.max(0, Number(page || 0) || 0);
  const recent = await adminHardSkipRecent(p);
  let text = '🧱 <b>Hard-skip (dead chats)</b>\n\n';
  text += 'Это список TG ID, для которых рассылка пропускает отправку (permanent errors: blocked / chat not found / deactivated).\n';
  text += `TTL configured: <b>${ttlDays}</b> дн.\n\n`;
  if (!recent.ok) {
    text += '⚠️ Redis недоступен — список временно недоступен.\n';
  } else if (!recent.items.length) {
    text += 'Пока пусто.\n';
  } else {
    text += `<b>Недавние (стр. ${p + 1}):</b>\n`;
    for (const it of recent.items) {
      const when = it.at ? ` · <code>${escapeHtml(String(it.at).slice(0, 19))}</code>` : '';
      text += `• <code>${it.tgId}</code> — <b>${escapeHtml(it.r)}</b>${when}\n`;
    }
  }

  const kb = new InlineKeyboard();
  kb.text('🔎 Найти TG ID', `a:hs_find|p:${p}`).row();
  kb.text('🧾 Последние пропуски', `a:hs_hits|p:${p}|r:all`).row();
  if (recent.ok && recent.items.length) {
    for (const it of recent.items) {
      kb.text(`tg:${it.tgId}`, `a:hs_view|tg:${it.tgId}`).row();
    }
  }
  kb.row();
  if (p > 0) kb.text('⬅️', `a:hs_home|p:${p - 1}`);
  kb.text('➡️', `a:hs_home|p:${p + 1}`);
  kb.row().text('⬅️ Система', 'a:admin_sys').row().text('⬅️ Админка', 'a:admin_home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}



async function renderAdminHardSkipHits(ctx, page = 0, reasonFilter = 'all', opts = {}) {
  const p = Math.max(0, Number(page || 0) || 0);
  const rf = String(reasonFilter || 'all').trim().toLowerCase() || 'all';
  const toast = opts?.toast ? String(opts.toast) : '';

  const hits = await adminHardSkipHits(p, rf);
  const stats = await adminHardSkipHitReasonStatsToday();

  let text = `🧾 <b>Hard-skip HITs (пропуски)</b>

`;
  text += `Показывает последние случаи, когда рассылка <b>пропустила</b> отправку из‑за hard-skip (dead chats).

`;
  if (toast) text += `<b>${escapeHtml(toast)}</b>

`;
const filterLabel = rf === 'all' ? 'ALL' : escapeHtml(rf);
  text += `Фильтр: <b>${filterLabel}</b> · окно: последние <code>${hits.scanN || ADMIN_HS_HITS_SAMPLE_LIMIT}</code> HITs

`;

  if (stats.ok && stats.by_reason.length) {
    const top = stats.by_reason.slice(0, 4).map(([r, c]) => `${escapeHtml(r)}:<code>${c}</code>`).join(' · ');
    text += `Сегодня: ${top}

`;
  }

  if (!hits.ok) {
    text += '⚠️ Redis недоступен — список временно недоступен.\n';
  } else if (!hits.items.length) {
    text += 'Пока пусто (по текущему фильтру/окну).\n';
  } else {
    const pageLabel = hits.total ? `${p + 1}` : `${p + 1}`;
    text += `<b>Недавние (стр. ${pageLabel}):</b>
`;
    for (const it of hits.items) {
      const when = it.at ? ` · <code>${escapeHtml(String(it.at).slice(0, 19))}</code>` : '';
      const bc = it.broadcastId ? ` · bc:<b>#${escapeHtml(String(it.broadcastId))}</b>` : '';
      const uid = it.userId ? ` · uid:<code>${escapeHtml(String(it.userId))}</code>` : '';
      const via = it.via ? ` · <code>${escapeHtml(String(it.via))}</code>` : '';
      text += `• <code>${it.tgId}</code> — <b>${escapeHtml(it.r)}</b>${bc}${uid}${via}${when}
`;
    }
  }

  const kb = new InlineKeyboard();
  kb.text('🧱 Список (set)', `a:hs_home|p:0`).text('🔎 Найти TG ID', `a:hs_find|p:0`).row();

  // Filters with today counters (best-effort).
  const reasonCounts = new Map();
  if (stats.ok) {
    for (const [r, c] of stats.by_reason) reasonCounts.set(String(r), Number(c) || 0);
  }

  const fAll = rf === 'all' ? '✅ ALL' : 'ALL';
  kb.text(fAll, `a:hs_hits|p:0|r:all`);
  const filters = ['bot_blocked', 'chat_not_found', 'user_deactivated', 'unknown', 'other'];
  for (const f of filters) {
    const labelBase = f.replace(/_/g, ' ');
    const c = reasonCounts.get(f) || 0;
    const label = (rf === f ? '✅ ' : '') + (c > 0 ? `${labelBase}(${c})` : labelBase);
    kb.text(label.slice(0, 20), `a:hs_hits|p:0|r:${f}`);
    if (['chat_not_found', 'unknown', 'other'].includes(f)) kb.row();
  }
  kb.row();

  kb.text('🗒 Export last 200', `a:hs_hits_export|p:${p}|r:${rf}`).row();

  if (hits.ok && hits.items.length) {
    const seen = new Set();
    for (const it of hits.items) {
      if (seen.has(it.tgId)) continue;
      seen.add(it.tgId);
      kb.text(`tg:${it.tgId}`, `a:hs_view|tg:${it.tgId}`).row();
      if (seen.size >= 6) break;
    }
  }
  kb.row();
  if (p > 0) kb.text('⬅️', `a:hs_hits|p:${p - 1}|r:${rf}`);
  kb.text('➡️', `a:hs_hits|p:${p + 1}|r:${rf}`);
  kb.row().text('⬅️ Система', 'a:admin_sys').row().text('⬅️ Админка', 'a:admin_home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}


async function renderAdminHardSkipView(ctx, tgId, opts = {}) {
  const id = Number(tgId || 0);
  let text = `🧱 <b>Hard-skip status</b>\n\nTG ID: <code>${id || 0}</code>\n`;
  if (opts && opts.toast) {
    text += `\n<b>${escapeHtml(String(opts.toast))}</b>\n`;
  }

  const st = await adminHardSkipGet(id);
  if (st.error === 'redis_unavailable') {
    text += '\n⚠️ Redis недоступен.\n';
  } else if (!st.exists) {
    text += '\nСтатус: ✅ <b>нет hard-skip</b>\n';
  } else {
    text += `\nСтатус: 🧱 <b>hard-skip</b>\n`;
    text += `Причина: <b>${escapeHtml(st.reason || 'unknown')}</b>\n`;
    if (st.at) text += `Время: <code>${escapeHtml(String(st.at).slice(0, 19))}</code>\n`;
    if (Number.isFinite(st.ttlSec) && st.ttlSec !== null) {
      const days = Math.max(0, Math.round((st.ttlSec || 0) / 86400));
      text += `TTL: ~${days}d\n`;
    }
  }

  const kb = new InlineKeyboard();
  if (st.exists) kb.text('🧹 Снять hard-skip', `a:hs_unskip|tg:${id}`).row();
  kb.text('⬅️ Назад', 'a:hs_home|p:0').row();
  kb.text('⬅️ Система', 'a:admin_sys').row().text('📋 Меню', 'a:menu').text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}

async function renderAdminSysNotice(ctx) {
  const n = await getSysNotice();

  const verLabel = n.version > 0 ? `v${n.version}` : '—';
  const sev = normalizeNoticeSeverity(n.severity);
  const tgt = normalizeNoticeTarget(n.target);

  const nowSec = Math.floor(Date.now() / 1000);
  let expLabel = '—';
  if (n.expiresAt && Number(n.expiresAt) > 0) {
    const exp = Number(n.expiresAt);
    const iso = new Date(exp * 1000).toISOString();
    const left = exp - nowSec;
    expLabel = left <= 0 ? `${iso} (EXPIRED)` : `${iso} (ещё ${fmtWait(left)})`;
  }

  let ctaLabel = '—';
  if (n.ctaUrl) {
    const lbl = n.ctaLabel ? String(n.ctaLabel) : '🔗 Подробнее';
    ctaLabel = `${escapeHtml(lbl)} → <code>${escapeHtml(String(n.ctaUrl).slice(0, 180))}</code>`;
  }

  let text = `📣 <b>Системное объявление</b>

`;
  text += `STATUS: <b>${n.active ? 'ON' : 'OFF'}</b>
`;
  text += `SEVERITY: <b>${escapeHtml(sev)}</b>
`;
  text += `TARGET: <b>${escapeHtml(tgt)}</b>
`;
  text += `EXPIRES: <code>${escapeHtml(String(expLabel))}</code>
`;
  text += `CTA: ${ctaLabel}
`;
  text += `VERSION: <b>${escapeHtml(String(verLabel))}</b>
`;
  if (n.updatedAt) {
    text += `UPDATED: <code>${escapeHtml(String(n.updatedAt).slice(0, 64))}</code>
`;
  }

  text += `
<b>Текст</b>
`;
  const preview = n.text ? (n.text.length > 900 ? (n.text.slice(0, 900) + '…') : n.text) : '';
  text += preview ? `<pre>${escapeHtml(preview)}</pre>` : '—';

  text += `

ℹ️ Показывается пользователям <b>1 раз на версию</b> при входе в «📋 Меню» / «🏠 Home».
Таргетинг: <code>all/brand/creator</code>. Авто‑expire: после дедлайна не показываем.
Чтобы показать снова — жми «🚀 Опубликовать» (увеличит версию).`;

  const kb = new InlineKeyboard()
    .text(n.active ? '⚫ Выключить' : '🟢 Включить', 'a:admin_notice_toggle')
    .text(`🎚 Уровень: ${sev}`, 'a:admin_notice_sev')
    .row()
    .text(`🎯 Кому: ${tgt}`, 'a:admin_notice_target')
    .text('⏰ Expire', 'a:admin_notice_expire')
    .row()
    .text('🔗 CTA', 'a:admin_notice_cta')
    .text('✍️ Текст', 'a:admin_notice_text')
    .row()
    .text('🧹 Очистить текст', 'a:admin_notice_clear')
    .text('🚀 Опубликовать (новая версия)', 'a:admin_notice_publish')
    .row()
    .text('⬅️ Коммуникации', 'a:admin_comms')
    .row()
    .text('📋 Меню', 'a:menu')
    .text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
}

async function renderAdminQStashStatus(ctx) {
  const fanout = await getSysBool(SYS_KEYS.broadcast_qstash_fanout, false);

  const lib = getQStashLibHealth();
  const envTokenOk = !!(process.env.QSTASH_TOKEN || '');
  const envSignOk = !!(process.env.QSTASH_CURRENT_SIGNING_KEY || '');
  const envBaseOk = !!(CFG.PUBLIC_BASE_URL || '');

  let lastTick = null;
  let lastDeliveryAt = null;
  let lastPingAt = null;
  let lastPingNonce = null;
  let lastPingBy = null;
  let lastPingEnqAt = null;
  let lastPingEnqNonce = null;

  // Redis-only metrics (best-effort).
  try { lastTick = await redis.get(k(['cron', 'broadcast_tick', 'last_run'])); } catch {}
  try { lastDeliveryAt = await redis.get(k(['qstash', 'broadcast_deliver', 'last_at'])); } catch {}
  try { lastPingAt = await redis.get(k(['qstash', 'ping', 'last_at'])); } catch {}
  try { lastPingNonce = await redis.get(k(['qstash', 'ping', 'last_nonce'])); } catch {}
  try { lastPingBy = await redis.get(k(['qstash', 'ping', 'last_by_tg_id'])); } catch {}
  try { lastPingEnqAt = await redis.get(k(['qstash', 'ping', 'last_enqueued_at'])); } catch {}
  try { lastPingEnqNonce = await redis.get(k(['qstash', 'ping', 'last_enqueued_nonce'])); } catch {}

  // Broadcast cooldown (Redis-only).
  let cooldownUntilMs = 0;
  let cooldownBid = 0;
  let cooldownLast429At = null;
  let cooldownReason = null;
  try { cooldownUntilMs = Number(await redis.get(k(['broadcast', 'cooldown_until']))) || 0; } catch {}
  try { cooldownBid = Number(await redis.get(k(['broadcast', 'cooldown_broadcast_id']))) || 0; } catch {}
  try { cooldownLast429At = await redis.get(k(['broadcast', 'last_429_at'])); } catch {}
  try { cooldownReason = await redis.get(k(['broadcast', 'last_429_reason'])); } catch {}

  function fmtAgo(iso) {
    const raw = iso ? String(iso) : '';
    if (!raw) return '—';
    const t = Date.parse(raw);
    if (!Number.isFinite(t)) return escapeHtml(raw);
    const sec = Math.max(0, Math.floor((Date.now() - t) / 1000));
    return `${escapeHtml(raw)}  ( ${fmtWait(sec)} назад )`;
  }

  const tickTs = (lastTick && typeof lastTick === 'object') ? (lastTick.ts || lastTick.at || lastTick.time || null) : null;
  const tickMode = (lastTick && typeof lastTick === 'object') ? (lastTick.mode || null) : null;

  const nowMs = Date.now();
  const cdActive = cooldownUntilMs && cooldownUntilMs > nowMs;
  const cdLeftSec = cdActive ? Math.ceil((cooldownUntilMs - nowMs) / 1000) : 0;

  const pingOk = (lastPingEnqNonce && lastPingNonce && String(lastPingEnqNonce) === String(lastPingNonce))
    ? 'OK'
    : (lastPingEnqNonce ? 'WAIT' : '—');

  let text = `🛰 <b>QStash — статус</b>

`;

  text += `Lib (@upstash/qstash): <b>${lib.available ? 'OK' : 'MISSING'}</b>
`;
  if (!lib.available && lib?.error?.message) {
    text += `• error: <code>${escapeHtml(String(lib.error.message).slice(0, 160))}</code>
`;
  }

  text += `ENV: token <b>${envTokenOk ? 'OK' : 'MISS'}</b> · signing <b>${envSignOk ? 'OK' : 'MISS'}</b> · base_url <b>${envBaseOk ? 'OK' : 'MISS'}</b>

`;

  text += `Fan-out (Redis): <b>${fanout ? 'ON' : 'OFF'}</b>
`;
  text += `Broadcast tick last_run: ${tickTs ? fmtAgo(tickTs) : '—'}${tickMode ? `
• mode: <b>${escapeHtml(String(tickMode))}</b>` : ''}

`;
  text += `Worker last delivery: ${lastDeliveryAt ? fmtAgo(lastDeliveryAt) : '—'}
`;
  text += `Ping received: ${lastPingAt ? fmtAgo(lastPingAt) : '—'}
`;
  if (lastPingNonce) text += `• nonce: <code>${escapeHtml(String(lastPingNonce))}</code>
`;
  if (lastPingBy) text += `• by tg_id: <code>${escapeHtml(String(lastPingBy))}</code>
`;
  if (lastPingEnqAt) text += `Ping enqueued: ${fmtAgo(lastPingEnqAt)}
`;
  if (lastPingEnqNonce) text += `• enqueued nonce: <code>${escapeHtml(String(lastPingEnqNonce))}</code>
`;
  if (lastPingEnqNonce) text += `• ping status: <b>${pingOk}</b>
`;

  text += `
Broadcast cooldown: <b>${cdActive ? 'ACTIVE' : 'OFF'}</b>`;
  if (cdActive) text += ` (ещё ${fmtWait(cdLeftSec)})`;
  text += `
`;
  if (cooldownBid) text += `• broadcast_id: <code>${cooldownBid}</code>
`;
  if (cooldownLast429At) text += `• last_429_at: ${fmtAgo(cooldownLast429At)}
`;
  if (cooldownReason) text += `• reason: <code>${escapeHtml(String(cooldownReason))}</code>
`;

  const kb = new InlineKeyboard()
    .text('🧪 Send signed ping', 'a:admin_qstash_ping')
    .row()
    .text(`📣 Fan-out: ${fanout ? 'ON' : 'OFF'}`, 'a:admin_bc_qstash_toggle')
    .text('⬅️ Система', 'a:admin_sys')
    .row()
	    .text('📋 Меню', 'a:menu')
    .text('🏠 Home', 'a:home');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}

async function renderAdminDmTemplates(ctx, page = 0) {
  const { tpls, isCustom } = await getAdminDmTemplatesWithMeta();
  const items = Array.isArray(tpls.items) ? tpls.items : [];
  const perPage = 8;
  const total = items.length;
  const pages = Math.max(1, Math.ceil(total / perPage));
  const p = Math.min(Math.max(0, Number(page) || 0), pages - 1);
  const slice = items.slice(p * perPage, p * perPage + perPage);

  let text =
    `📌 <b>Шаблоны сообщений (DM)</b>\n\n` +
    `Источник: <b>${isCustom ? 'custom (Redis)' : 'default'}</b>\n` +
    `Версия: <b>v${Number(tpls.version || 0)}</b>\n` +
    `Обновлено: <code>${escapeHtml(tpls.updatedAt || '—')}</code>\n\n`;

  if (!slice.length) {
    text += 'Пока нет шаблонов. Добавь первый через “➕ Новый шаблон”.';
  } else {
    text += 'Список (страница ' + (p + 1) + '/' + pages + '):\n\n';
    for (const it of slice) {
      const lbl = escapeHtml(String(it.label || '—'));
      const sn = clipText(String(it.text || '').replace(/\n+/g, ' / '), 80);
      text += `• <b>${lbl}</b> — <i>${escapeHtml(sn)}</i>\n`;
    }
  }

  const kb = new InlineKeyboard();
  for (const it of slice) {
    kb.text(String(it.label || '—'), `a:admin_umsg_tpl_view|tid:${String(it.id || '')}|p:${p}`).row();
  }

  kb.text('➕ Новый шаблон', `a:admin_umsg_tpl_add|p:${p}`)
    .text('♻️ Сбросить к дефолту', `a:admin_umsg_tpl_reset_q|p:${p}`)
    .row();

  if (pages > 1) {
    const prev = (p - 1 + pages) % pages;
    const next = (p + 1) % pages;
    kb.text('⬅️', `a:admin_umsg_tpls|p:${prev}`)
      .text(`${p + 1}/${pages}`, `a:admin_umsg_tpls|p:${p}`)
      .text('➡️', `a:admin_umsg_tpls|p:${next}`)
      .row();
  }

  kb.text('📎 Вставить', `a:adm_ph|r:tpl_list|p:${p}`).row();

  kbAdminFooter(kb, '⬅️ Коммуникации', 'a:admin_comms');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
}

