  text += `<pre>${escapeHtml(lines || '—')}</pre>

`;

  const line = buildStartLink('fs_offers_a');
  if (line) text += `⚡ Быстро: вставляй в конец поста: <code>🔥 Founder Sale: ${escapeHtml(line)}</code>`;

