// Admin: Users directory state (search query stored in Redis per admin)
function adminUsersQueryKey(tgId) {
  return k(['admin', 'users', 'q', String(tgId)]);
}

async function getAdminUsersQuery(tgId) {
  try {
    const v = await redis.get(adminUsersQueryKey(tgId));
    return String(v || '').trim();
  } catch {
    return '';
  }
}

async function setAdminUsersQuery(tgId, q) {
  const val = String(q || '').trim();
  if (!val) return clearAdminUsersQuery(tgId);
  try {
    // Keep for 7 days (so admin can continue work).
    await redis.set(adminUsersQueryKey(tgId), val, { ex: 7 * 24 * 60 * 60 });
  } catch {
    // ignore
  }
}

async function clearAdminUsersQuery(tgId) {
  try {
    await redis.del(adminUsersQueryKey(tgId));
  } catch {
    // ignore
  }
}

// --- Admin Audit Redis helpers ---
function adminAuditQueryKey(tgId) { return k(['admin', 'aud', 'q', String(tgId)]); }

async function getAdminAuditQuery(tgId) {
  try {
    const v = await redis.get(adminAuditQueryKey(tgId));
    if (!v) return null;
    return typeof v === 'object' ? v : null;
  } catch { return null; }
}

async function setAdminAuditQuery(tgId, q) {
  try {
    await redis.set(adminAuditQueryKey(tgId), q, { ex: 7 * 24 * 60 * 60 });
  } catch {}
}

async function clearAdminAuditQuery(tgId) {
  try { await redis.del(adminAuditQueryKey(tgId)); } catch {}
}

async function renderAdminAudit(ctx, { afterHours = 24, page = 0 } = {}) {
  const h = Number(afterHours) || 24;
  const limit = 15;
  const p = Math.max(0, Number(page) || 0);
  const offset = p * limit;

  const tgId = Number(ctx.from?.id || 0);
  const sq = tgId ? await getAdminAuditQuery(tgId) : null;
  const action = sq?.action || '';
  const wsId = Number(sq?.wsId || 0);
  const userId = Number(sq?.userId || 0);

  const opts = { action, wsId, userId, afterHours: h, limit: limit + 1, offset };
  const rowsAll = await db.searchGlobalAudit(opts);
  const hasNext = rowsAll.length > limit;
  const rows = rowsAll.slice(0, limit);

  const msk = (d) => d ? new Date(d).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }) : '—';

  const timeLabels = { 24: '24ч', 168: '7д', 720: '30д', 0: 'Всё' };
  const timeLabel = timeLabels[h] || `${h}ч`;

  // Search info
  let searchLine = '';
  if (action) searchLine = `\n🔎 Action: <code>${escapeHtml(action)}</code>`;
  else if (wsId) searchLine = `\n🔎 Workspace: <code>${wsId}</code>`;
  else if (userId) searchLine = `\n🔎 User: <code>${userId}</code>`;

  let text = `📜 <b>Audit Log</b> · ${timeLabel} · стр ${p + 1}${searchLine}\n\n`;

  if (!rows.length) {
    text += 'Событий нет.';
  } else {
    for (const r of rows) {
      const who = r.tg_username ? '@' + r.tg_username : (r.tg_id ? 'tg:' + r.tg_id : '?');
      const ws = r.ws_channel ? '@' + r.ws_channel : (r.ws_title || 'ws:' + r.workspace_id);
      text += `• <code>${escapeHtml(r.action)}</code>\n  ${escapeHtml(who)} · ${escapeHtml(ws)} · ${msk(r.created_at)}\n`;
    }
  }

  const kb = new InlineKeyboard();

  // Time filters
  const tb = (label, hours) => (h === hours ? `✅ ${label}` : label);
  kb.text(tb('24ч', 24), `a:aud|h:24|p:0`)
    .text(tb('7д', 168), `a:aud|h:168|p:0`)
    .text(tb('30д', 720), `a:aud|h:720|p:0`)
    .text(tb('Всё', 0), `a:aud|h:0|p:0`)
    .row();

  // Search / Reset
  kb.text('🔎 Поиск', `a:aud_search|h:${h}`);
  if (sq) kb.text('🧹 Сброс', `a:aud_reset|h:${h}`);
  kb.row();

  // Export
  kb.text('📤 Export TXT', `a:aud_export|h:${h}`).row();

  // Pagination
  if (p > 0) kb.text('⬅️', `a:aud|h:${h}|p:${p - 1}`);
  if (hasNext) kb.text('➡️', `a:aud|h:${h}|p:${p + 1}`);
  if (p > 0 || hasNext) kb.row();

  kb.text('⬅️ Операции', 'a:admin_ops');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}

async function sendAdminAuditExport(ctx, afterHours = 24) {
  const tgId = Number(ctx.from?.id || 0);
  const sq = tgId ? await getAdminAuditQuery(tgId) : null;

  const opts = {
    action: sq?.action || '',
    wsId: Number(sq?.wsId || 0),
    userId: Number(sq?.userId || 0),
    afterHours: Number(afterHours) || 0,
  };

  const { rows, truncated } = await db.exportGlobalAudit(opts);

  const mskLong = (d) => {
    if (!d) return '—';
    try {
      return new Date(d).toLocaleString('ru-RU', {
        timeZone: 'Europe/Moscow',
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
      }) + ' MSK';
    } catch { return new Date(d).toISOString(); }
  };

  const filterDesc = [];
  if (opts.action) filterDesc.push(`action=${opts.action}`);
  if (opts.wsId) filterDesc.push(`ws=${opts.wsId}`);
  if (opts.userId) filterDesc.push(`user=${opts.userId}`);
  if (opts.afterHours) filterDesc.push(`last_${opts.afterHours}h`);

  const header = [
    'Collabka PR — Global Audit Export',
    `Exported: ${mskLong(Date.now())}`,
    `Filters: ${filterDesc.length ? filterDesc.join(', ') : 'none'}`,
    `Rows: ${rows.length}${truncated ? ' (TRUNCATED — max 5000)' : ''}`,
    '---',
  ].join('\n');

  const body = rows.map((r) => {
    const who = r.tg_username ? '@' + r.tg_username : (r.tg_id || '?');
    const ws = r.ws_channel ? '@' + r.ws_channel : (r.ws_title || 'ws:' + r.workspace_id);
    let payload = '';
    try { payload = r.payload ? JSON.stringify(r.payload) : ''; } catch {}
    if (payload.length > 500) payload = payload.slice(0, 500) + '…';
    return `${mskLong(r.created_at)} | ${r.action} | ${who} | ${ws}${payload ? ' | ' + payload : ''}`;
  }).join('\n');

  const txt = header + '\n' + (body || 'EMPTY');
  const ts = new Date().toISOString().slice(0, 10);
  const filename = `audit_${filterDesc.join('_') || 'all'}_${ts}.txt`;

  let caption = `📤 Audit export: ${rows.length} событий`;
  if (truncated) caption += '\n⚠️ Лимит 5000 — сузьте фильтр.';

  await ctx.replyWithDocument(
    new InputFile(Buffer.from(txt, 'utf-8'), filename),
    {
      caption,
      reply_markup: new InlineKeyboard()
        .text('⬅️ Аудит', `a:aud|h:${afterHours}|p:0`)
        .text('⬅️ Админка', 'a:admin_home')
        .row()
        .text('📋 Меню', 'a:menu')
        .text('🏠 Home', 'a:home')
    }
  );
}



async function renderAdminUsers(ctx, filterRaw = 'all', page = 0) {
  const filter = String(filterRaw || 'all').toLowerCase();
  const limit = 12;
  const p = Math.max(0, Number(page) || 0);
  const offset = p * limit;

  const tgId = Number(ctx.from?.id || 0);
  const q = tgId ? await getAdminUsersQuery(tgId) : '';

  // Fetch one extra row to detect next page.
  const rowsAll = await db.listUsersDirectory(filter, limit + 1, offset, q);
  const hasNext = rowsAll.length > limit;
  const rows = rowsAll.slice(0, limit);

  const labelMap = {
    all: 'Все',
    brands: 'Бренды',
    creators: 'Креаторы',
    curators: 'Кураторы',
    managers: 'Менеджеры',
  };
  const label = labelMap[filter] || labelMap.all;

  function roleBadges(r) {
    const badges = [];
    if (isSuperAdminTg(Number(r.tg_id))) badges.push('👑');
    if (r.is_manager) badges.push('🧑‍💼');
    if (r.is_moderator || r.is_curator) badges.push('🧩');
    if (r.is_creator) badges.push('🧑‍🎤');
    const isBrand = !!r.has_brand_profile || !!r.brand_plan || Number(r.brand_credits || 0) > 0;
    if (isBrand) badges.push('🏢');
    if (!badges.length) badges.push('👤');
    return badges.join('');
  }

  const qLine = q ? `\n🔎 Поиск: <tg-spoiler>${escapeHtml(q)}</tg-spoiler>\n` : '';

  let text = `👥 <b>Пользователи</b> · <b>${escapeHtml(label)}</b> · стр <b>${p + 1}</b>${qLine}

`;
  const kb = new InlineKeyboard();

  // STEP196: show admin note marker in directory only in DM to avoid accidental leaks in group chats.
  const inPrivate = String(ctx.chat?.type || '') === 'private';
  const notesMap = inPrivate ? await getAdminUserNotesBulk(rows.map((r) => r.user_id)) : new Map();

  if (!rows.length) {
    text += 'Пользователей нет по этому фильтру.';
  } else {
    for (const r of rows) {
      const who = r.tg_username ? '@' + r.tg_username : 'id ' + r.tg_id;
      const when = r.created_at ? new Date(r.created_at).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }) : '—';

      let noteSuffix = '';
      if (inPrivate) {
        const note = notesMap.get(Number(r.user_id || 0));
        if (note) {
          const tags = Array.isArray(note.tags) ? note.tags : [];
          const tagTitles = tags.map(adminUserNoteTagTitle).filter(Boolean);
          const short = tagTitles.slice(0, 2);
          const tagPart = short.length
            ? ` 🏷 ${escapeHtml(short.join(', '))}${tagTitles.length > 2 ? '…' : ''}`
            : '';
          noteSuffix = ` · 📝${tagPart}`;
        }
      }

      text += `• ${roleBadges(r)} <b>${escapeHtml(who)}</b> · ${escapeHtml(when)}${noteSuffix}\n`;
    }
  }

  // STEP197: If small result set — show quick actions right in the list (DM only).
  // Helps support flows without opening the card first.
  if (inPrivate && rows.length >= 1 && rows.length <= 5) {
    for (const r of rows) {
      const who = r.tg_username ? '@' + r.tg_username : 'id ' + r.tg_id;
      const hasNote = notesMap.has(Number(r.user_id || 0));
      kb.text(`👤 ${who}${hasNote ? ' 📝' : ''}`, `a:adm_ucard|id:${r.user_id}|f:${filter}|p:${p}`);
      kb.text('✉️', `a:adm_umsg|id:${r.user_id}|f:${filter}|p:${p}`);
      kb.text('📝', `a:adm_unote|id:${r.user_id}|f:${filter}|p:${p}`);
      kb.row();
    }
  }

  const filters = [
    { id: 'all', title: 'Все' },
    { id: 'brands', title: 'Бренды' },
    { id: 'creators', title: 'Креаторы' },
    { id: 'curators', title: 'Кураторы' },
    { id: 'managers', title: 'Менеджеры' },
  ];

  const btn = (id, title) => (filter === id ? `✅ ${title}` : title);

  kb.text(btn('all', 'Все'), 'a:admin_users|f:all|p:0')
    .text(btn('brands', 'Бренды'), 'a:admin_users|f:brands|p:0')
    .row()
    .text(btn('creators', 'Креаторы'), 'a:admin_users|f:creators|p:0')
    .text(btn('curators', 'Кураторы'), 'a:admin_users|f:curators|p:0')
    .row()
    .text(btn('managers', 'Менеджеры'), 'a:admin_users|f:managers|p:0')
    .row();

  kb.text('🔎 Поиск', `a:admin_users_search|f:${filter}`);
  if (q) kb.text('🧹 Сброс', `a:admin_users_reset|f:${filter}|p:0`);
  kb.row();
  kb.text('📤 Export CSV', `a:adm_ucsv|f:${filter}`).row();

  if (p > 0) kb.text('⬅️ Назад', `a:admin_users|f:${filter}|p:${p - 1}`);
  if (hasNext) kb.text('➡️ Далее', `a:admin_users|f:${filter}|p:${p + 1}`);
  if (p > 0 || hasNext) kb.row();

  kb.text('⬅️ Операции', 'a:admin_ops');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}

async function renderAdminUserCard(ctx, userId, backFilter = 'all', backPage = 0) {
  const card = await db.getUserCardById(Number(userId));
  if (!card) {
    await safeEditOrReply(ctx, '⚠️ Пользователь не найден.', {
      reply_markup: new InlineKeyboard().text('⬅️ К списку', `a:admin_users|f:${backFilter}|p:${backPage}`),
    });
    return;
  }

  const msk = (d) => d ? new Date(d).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }) : '—';

  // Role badges
  const roles = [];
  if (isSuperAdminTg(Number(card.tg_id))) roles.push('👑 Super Admin');
  if (card.is_manager) roles.push('🧑‍💼 Менеджер');
  if (card.is_moderator || card.is_curator) roles.push('🧩 Куратор/Модератор');
  if (card.is_creator) roles.push('🧑‍🎤 Креатор');
  const isBrand = !!card.has_brand_profile || !!card.brand_plan || Number(card.brand_credits || 0) > 0;
  if (isBrand) roles.push('🏢 Бренд');
  if (!roles.length) roles.push('👤 Пользователь');

  let text = `👤 <b>Карточка пользователя</b>\n\n`;
  text += `<b>ID:</b> <code>${card.id}</code>\n`;
  text += `<b>TG ID:</b> <code>${card.tg_id}</code>\n`;
  text += `<b>Username:</b> ${card.tg_username ? '@' + escapeHtml(card.tg_username) : '—'}\n`;
  text += `<b>Роли:</b> ${roles.join(', ')}\n`;
  text += `<b>Регистрация:</b> ${msk(card.created_at)}\n`;
  text += `<b>Обновлён:</b> ${msk(card.updated_at)}\n`;
  if (card.banned_at) text += `🚫 <b>ЗАБЛОКИРОВАН:</b> ${msk(card.banned_at)}\n`;

  // Admin note (Redis-only, STEP194/195). Show snippet+tags only in DM to avoid leaks in group chats.
  const inPrivate = String(ctx.chat?.type || '') === 'private';
  if (inPrivate) {
    const note = await getAdminUserNote(card.id);
    const tags = Array.isArray(note?.tags) ? note.tags : [];
    const tagTitles = tags.map(adminUserNoteTagTitle).filter(Boolean);

    if (note?.text) {
      const sn = clipText(String(note.text).replace(/\n+/g, ' / '), 180);
      text += `📝 <b>Заметка:</b> ${escapeHtml(sn)}\n`;
    } else {
      text += `📝 <b>Заметка:</b> —\n`;
    }

    text += `🏷 <b>Теги:</b> ${tagTitles.length ? escapeHtml(tagTitles.join(', ')) : '—'}\n`;
  } else {
    text += `📝 <b>Заметка:</b> <i>(только в DM)</i>\n`;
    text += `🏷 <b>Теги:</b> <i>(только в DM)</i>\n`;
  }

  // Brand info
  if (isBrand) {
    text += `\n<b>— Бренд —</b>\n`;
    text += `<b>Brand Plan:</b> ${card.brand_plan ? escapeHtml(String(card.brand_plan)) : '—'}`;
    if (card.brand_plan_until) text += ` (до ${msk(card.brand_plan_until)})`;
    text += `\n`;
    const totalCr = Number(card.brand_credits || 0);
    const spentCr = Number(card.brand_credits_spent || 0);
    const giftedCr = Number(card.brand_credits_gifted || 0);
    const giftedPart = giftedCr > 0 ? `, подарочные: ${giftedCr}` : '';
    text += `<b>Credits:</b> ${totalCr} (потрачено: ${spentCr}${giftedPart})\n`;
    if (card.brand_trial_granted) text += `<b>Trial:</b> ✅ выдан ${msk(card.brand_trial_granted_at)}\n`;
    if (card._brand_profile) {
      const bp = card._brand_profile;
      text += `<b>Профиль:</b> ${escapeHtml(bp.brand_name || '—')}`;
      if (bp.niche) text += ` · ${escapeHtml(bp.niche)}`;
      text += `\n`;
    }
  }

  // Workspaces
  if (card._workspaces && card._workspaces.length) {
    text += `\n<b>— Воркспейсы (${card._workspaces.length}) —</b>\n`;
    for (const ws of card._workspaces.slice(0, 5)) {
      text += `• <b>${escapeHtml(ws.title || 'ws#' + ws.id)}</b>`;
      if (ws.channel_username) text += ` @${escapeHtml(ws.channel_username)}`;
      text += ` · ${msk(ws.created_at)}\n`;
    }
    if (card._workspaces.length > 5) text += `<i>... и ещё ${card._workspaces.length - 5}</i>\n`;
  }

  // Curator in
  if (card._curator_in && card._curator_in.length) {
    text += `\n<b>— Куратор в (${card._curator_in.length}) —</b>\n`;
    for (const c of card._curator_in.slice(0, 5)) {
      text += `• <b>${escapeHtml(c.title || 'ws#' + c.id)}</b>`;
      if (c.channel_username) text += ` @${escapeHtml(c.channel_username)}`;
      text += ` · с ${msk(c.joined_at)}\n`;
    }
    if (card._curator_in.length > 5) text += `<i>... и ещё ${card._curator_in.length - 5}</i>\n`;
  }

  const isBanned = !!card.banned_at;

  const kb = new InlineKeyboard();
  kb.text(`📋 Скопировать ID: ${card.tg_id}`, `a:adm_ucopy|id:${card.id}`).row();

  kb.text('✉️ Написать', `a:adm_umsg|id:${card.id}|f:${backFilter}|p:${backPage}`).row();
  kb.text('📝 Заметка', `a:adm_unote|id:${card.id}|f:${backFilter}|p:${backPage}`).row();

  // Quick gift from card
  kb.text('🎁 Подарить подписку', `a:adm_ugift|id:${card.id}|f:${backFilter}|p:${backPage}`).row();

  // Revoke actions
  if (card.brand_plan) {
    kb.text('⛔ Забрать Brand Plan', `a:adm_urevoke_q|id:${card.id}|t:bp|f:${backFilter}|p:${backPage}`);
    kb.text('⛔+🧾 Забрать Plan + подарочные', `a:adm_urevoke_q|id:${card.id}|t:bp_gcr|f:${backFilter}|p:${backPage}`);
  }
  if (Number(card.brand_credits || 0) > 0) {
    kb.text('⛔ Обнулить кредиты', `a:adm_urevoke_q|id:${card.id}|t:cr|f:${backFilter}|p:${backPage}`);
  }
  if (Number(card.brand_credits_gifted || 0) > 0) {
    kb.text('🧾 Забрать подарочные кредиты', `a:adm_urevoke_q|id:${card.id}|t:gcr|f:${backFilter}|p:${backPage}`);
  }
  if (card.brand_plan || Number(card.brand_credits || 0) > 0 || Number(card.brand_credits_gifted || 0) > 0) kb.row();

  if (card._workspaces?.some(ws => ws.plan === 'pro')) {
    kb.text('⛔ Забрать PRO', `a:adm_urevoke_q|id:${card.id}|t:pro|f:${backFilter}|p:${backPage}`).row();
  }

  // Ban/unban
  if (isBanned) {
    kb.text('✅ Разбанить', `a:adm_uban_q|id:${card.id}|v:0|f:${backFilter}|p:${backPage}`).row();
  } else {
    kb.text('🚫 Заблокировать', `a:adm_uban_q|id:${card.id}|v:1|f:${backFilter}|p:${backPage}`).row();
  }

  kb.text('⬅️ К списку', `a:admin_users|f:${backFilter}|p:${backPage}`).row();
  kbAdminFooter(kb, '⬅️ Операции', 'a:admin_ops');

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}

async function renderAdminUserNote(ctx, userId, backFilter = 'all', backPage = 0) {
  const uid = Number(userId || 0);
  const f = String(backFilter || 'all').toLowerCase();
  const page = Math.max(0, Number(backPage) || 0);

const adminTgId = Number(ctx.from?.id || 0);
const ret = await getAdminUserNoteReturn(adminTgId);
const hasRet = !!(ret && Number(ret.uid || 0) === uid && String(ret.backCb || '').trim());
const sectionBackText = hasRet ? String(ret.sectionBackText || '⬅️ Коммуникации') : '⬅️ Операции';
const sectionBackCb = hasRet ? String(ret.sectionBackCb || 'a:admin_comms') : 'a:admin_ops';

const backKb = new InlineKeyboard();
backKb.text('⬅️ К карточке', `a:adm_ucard|id:${uid}|f:${f}|p:${page}`);
if (hasRet) backKb.text(String(ret.backText || '⬅️ Outbox'), String(ret.backCb));
backKb.row();
kbAdminFooter(backKb, sectionBackText, sectionBackCb);

  if (!uid) {
    await safeEditOrReply(ctx, '⚠️ Нет user_id.', { reply_markup: backKb });
    return;
  }

  // Safety: keep admin notes in DM to avoid accidental leaks in group chats.
  const chatType = String(ctx.chat?.type || '');
  if (chatType !== 'private') {
    await safeEditOrReply(
      ctx,
      `📝 <b>Заметка админа</b>\n\nЭта функция доступна только в <b>личном чате</b> с ботом (DM), чтобы заметки не светились в группах.\n\nОткрой бота в личке и зайди в карточку пользователя ещё раз.`,
      { parse_mode: 'HTML', reply_markup: backKb }
    );
    return;
  }

  const card = await db.getUserCardById(uid);
  if (!card) {
    await safeEditOrReply(ctx, '⚠️ Пользователь не найден.', { reply_markup: backKb });
    return;
  }

  const note = await getAdminUserNote(uid);

  const uname = card.tg_username ? '@' + String(card.tg_username) : '—';
  const tags = Array.isArray(note?.tags) ? note.tags : [];
  const tagTitles = tags.map(adminUserNoteTagTitle).filter(Boolean);

  const updated = note?.updatedAt
    ? (new Date(note.updatedAt).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }))
    : '—';
  const by = note?.byAdminTgId
    ? (note.byAdminUsername ? ('@' + String(note.byAdminUsername).replace(/^@/, '')) : ('tg:' + String(note.byAdminTgId)))
    : '—';

  let text = `📝 <b>Заметка (admin)</b>\n\n` +
    `User ID: <code>${uid}</code>\n` +
    `TG ID: <code>${escapeHtml(String(card.tg_id || '—'))}</code>\n` +
    `Username: ${escapeHtml(uname)}\n\n` +
    `🏷 <b>Теги</b>: ${tagTitles.length ? escapeHtml(tagTitles.join(', ')) : '—'}\n` +
    `<i>Нажимай на кнопки тегов ниже — включить/выключить.</i>\n\n`;

  if (note?.text) {
    text += `<b>Текст</b>\n<pre>${escapeHtml(String(note.text))}</pre>\n\n`;
  } else {
    text += `<i>Текст заметки пока пуст.</i>\n\n`;
  }

  text += `Updated: <code>${escapeHtml(String(updated))}</code>\n` +
    `By: <code>${escapeHtml(String(by))}</code>\n`;

  const kb = new InlineKeyboard();

  kb.text('✏️ Изменить текст', `a:adm_unote_edit|id:${uid}|f:${f}|p:${page}`).row();

  // Tag toggles (strict allowlist)
  for (let i = 0; i < ADMIN_USER_NOTE_TAGS.length; i++) {
    const t = ADMIN_USER_NOTE_TAGS[i];
    const on = tags.includes(t.id);
    const label = on ? `✅ ${t.title}` : `🏷 ${t.title}`;
    kb.text(label, `a:adm_unote_tag|id:${uid}|t:${t.id}|f:${f}|p:${page}`);
    if (i % 2 === 1) kb.row();
  }
  if (ADMIN_USER_NOTE_TAGS.length % 2 === 1) kb.row();

  if (hasAdminUserNoteData(note)) {
    kb.text('🧹 Очистить всё', `a:adm_unote_clear_q|id:${uid}|f:${f}|p:${page}`).row();
  }

kb.text('⬅️ К карточке', `a:adm_ucard|id:${uid}|f:${f}|p:${page}`);
if (hasRet) kb.text(String(ret.backText || '⬅️ Outbox'), String(ret.backCb));
kb.row();
kbAdminFooter(kb, sectionBackText, sectionBackCb);

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb, disable_web_page_preview: true });
}

function renderAdminDmUserMessageHtml(bodyHtml, opts = {}) {
  const withNext = opts.withNext !== false;
  const header = `🟦 <b>Сообщение от администратора Collabka PR</b>`;
  if (!withNext) return `${header}

${bodyHtml}`;
  return `${header}

${bodyHtml}

<b>Что дальше:</b>
• Вернуться к действиям бота — «📋 Меню»
• Вопросы/ошибка — «💬 Поддержка»
• Прочитано — «✅ Понятно»`;
}

async function sendAdminMessageToUser(ctx, payload, nav = {}) {
  const adminTgId = Number(payload?.byAdminTgId || ctx.from?.id || 0);
  const targetUserId = Number(payload?.targetUserId || 0);
  const targetTgId = Number(payload?.targetTgId || 0);
  const targetUsername = String(payload?.targetUsername || '').trim();
  const templateRaw = String(payload?.templateRaw || payload?.tplRaw || payload?.plain || '').trim();
  const bodyHtmlFallback = String(payload?.bodyHtml || '').trim();
  const templateId = String(payload?.templateId || payload?.tplId || '').trim();
  const templateLabel = String(payload?.templateLabel || '').trim();
const f = String(nav.f || 'all').toLowerCase();
const page = Math.max(0, Number(nav.page) || 0);
const backUid = Number(nav.backUid || targetUserId || 0);

  const withNext = nav.withNext !== false;

// Optional return route (used by Outbox quick actions, STEP204)
const retCb = String(payload?.retCb || nav.retCb || '').trim();
const retText = String(payload?.retText || nav.retText || '⬅️ Назад').trim();
const sectionBackText = String(payload?.sectionBackText || nav.sectionBackText || '').trim();
const sectionBackCb = String(payload?.sectionBackCb || nav.sectionBackCb || '').trim();
const sectionText = sectionBackText || (retCb ? '⬅️ Коммуникации' : '⬅️ Операции');
const sectionCb = sectionBackCb || (retCb ? 'a:admin_comms' : 'a:admin_ops');

  // Expand placeholders (best-effort) — both in preview and at send time.
  let expandedPlain = '';
  let phUsed = [];
  let phUnknown = [];
  if (templateRaw) {
    try {
      const vals = await buildAdminDmPlaceholderValues(ctx, targetTgId, { username: targetUsername });
      const res = applyAdminDmPlaceholders(templateRaw, vals);
      expandedPlain = String(res.text || '').trim();
      phUsed = Array.isArray(res.used) ? res.used : [];
      phUnknown = Array.isArray(res.unknown) ? res.unknown : [];
    } catch {
      expandedPlain = templateRaw;
      phUsed = [];
      phUnknown = [];
    }
  }

  // Fallback (older payloads)
  if (!expandedPlain) expandedPlain = String(payload?.plain || '').trim();

  const expandedMeta = clipCodepoints(expandedPlain, TG_SAFE_BODY_MAX);
  const expandedSafe = expandedMeta.text;
  const bodyHtml = bodyHtmlFallback || escapeHtml(expandedSafe);

  if (!adminTgId || !targetTgId || !bodyHtml) {
    await safeEditOrReply(ctx, '⚠️ Не удалось отправить: не хватает данных.', {
      reply_markup: (() => {
        const cardCb = `a:adm_ucard|id:${backUid}|f:${f}|p:${page}`;
        const kb = new InlineKeyboard();
        if (retCb) kb.text(retText || '⬅️ Назад', retCb).text('👤 Карточка', cardCb);
        else kb.text('⬅️ К карточке', cardCb);
        kb.row();
        kbAdminFooter(kb, sectionText, sectionCb);
        return kb;
      })()
    });
    return;
  }

  // Dedup (best-effort): prevent accidental double-send (double click / retries)
  let textHash = '';
  try {
    textHash = crypto.createHash('sha1').update(String(expandedSafe || bodyHtml)).digest('hex').slice(0, 12);
    const dkey = k(['adm_umsg_dedup', String(adminTgId), String(targetTgId), textHash]);
    const ok = await redis.set(dkey, '1', { nx: true, ex: 60 });
    if (!ok) {
      await safeEditOrReply(ctx, '⏳ Это сообщение уже отправлялось недавно (anti-двойной клик).', {
        reply_markup: (() => {
          const cardCb = `a:adm_ucard|id:${backUid}|f:${f}|p:${page}`;
          const kb = new InlineKeyboard();
          if (retCb) kb.text(retText || '⬅️ Назад', retCb).text('👤 Карточка', cardCb);
          else kb.text('⬅️ К карточке', cardCb);
          kb.row();
          kbAdminFooter(kb, sectionText, sectionCb);
          return kb;
        })()
      });
      return;
    }
  } catch {
    // If Redis is degraded — skip dedup.
  }

  const userMsg = renderAdminDmUserMessageHtml(bodyHtml, { withNext });
  const userKb = new InlineKeyboard()
    .text('📋 Меню', 'a:menu_push|src:admmsg')
    .text('💬 Поддержка', 'a:support_push|src:admmsg')
    .row()
    .text('✅ Понятно', 'a:usr_ack|src:admmsg');

  let ok = false;
  let err = '';
  try {
    await ctx.api.sendMessage(targetTgId, userMsg, { parse_mode: 'HTML', reply_markup: userKb, disable_web_page_preview: true });
    ok = true;
  } catch (e) {
    ok = false;
    err = String(e?.message || e).slice(0, 160);
  }



// Outbox log (Redis-only) — record send result (ok/failed). Best-effort.
try {
  const snippet = expandedSafe.length > 900 ? (String(expandedSafe).slice(0, 900) + '…') : String(expandedSafe || '');
  const preview = clipText(String(expandedSafe || '').replace(/\n+/g, ' / '), 160);
  await appendAdminOutbox({
    ts: new Date().toISOString(),
    status: ok ? 'ok' : 'failed',
    admin_tg_id: adminTgId,
    admin_username: String(ctx.from?.username || ''),
    target_user_id: targetUserId,
    target_tg_id: targetTgId,
    target_username: targetUsername,
    template_id: templateId,
    template_label: templateLabel,
    placeholders_used: phUsed,
    placeholders_unknown: phUnknown,
    text_hash: textHash,
    preview,
    snippet,
    error: ok ? '' : err,
  });
} catch {}
  const uname = targetUsername ? '@' + targetUsername : '—';
  if (!ok) {
    await safeEditOrReply(ctx, `❌ <b>Не удалось отправить</b>\n\nПользователь: <b>${escapeHtml(uname)}</b> (tg:<code>${targetTgId}</code>)\n\nОшибка: <code>${escapeHtml(err || 'unknown')}</code>`, {
      parse_mode: 'HTML',
      reply_markup: (() => {
        const cardCb = `a:adm_ucard|id:${backUid}|f:${f}|p:${page}`;
        const msgCb = `a:adm_umsg|id:${backUid}|f:${f}|p:${page}`;
        const kb = new InlineKeyboard();
        if (retCb) {
          kb.text(retText || '⬅️ Назад', retCb).text('👤 Карточка', cardCb).row();
          kb.text('✉️ Написать', msgCb).row();
        } else {
          kb.text('⬅️ Назад', msgCb).text('⬅️ К карточке', cardCb).row();
        }
        kbAdminFooter(kb, sectionText, sectionCb);
        return kb;
      })(),

      disable_web_page_preview: true,
    });
    return;
  }

// Admin confirm
const cardCb = `a:adm_ucard|id:${backUid}|f:${f}|p:${page}`;
const msgCb = `a:adm_umsg|id:${backUid}|f:${f}|p:${page}`;
const kbDone = new InlineKeyboard();
if (retCb) {
  kbDone.text(retText || '⬅️ Назад', retCb).text('👤 Карточка', cardCb).row();
  kbDone.text('✉️ Ещё сообщение', msgCb).row();
} else {
  kbDone.text('✉️ Ещё сообщение', msgCb).text('👤 Карточка', cardCb).row();
}
kbAdminFooter(kbDone, sectionText, sectionCb);
  await safeEditOrReply(ctx, `✅ <b>Отправлено</b> пользователю ${escapeHtml(uname)} (tg:<code>${targetTgId}</code>).`, { parse_mode: 'HTML', reply_markup: kbDone });

  // Ops/admin log (best-effort): send to support chat if configured, else to super-admins.
  try {
    const supportChatIdRaw = String(CFG.SUPPORT_CHAT_ID || '').trim();
    const admins = Array.isArray(CFG.SUPER_ADMIN_TG_IDS) ? CFG.SUPER_ADMIN_TG_IDS : [];
    const targets = [];
    if (supportChatIdRaw) targets.push(supportChatIdRaw);
    else {
      for (const a of admins) {
        const aid = Number(a || 0);
        if (aid) targets.push(aid);
      }
    }

    const by = ctx.from?.username ? '@' + String(ctx.from.username) : ('tg:' + String(adminTgId));
    const snippet = expandedSafe.length > 900 ? (String(expandedSafe).slice(0, 900) + '…') : String(expandedSafe || '');
    const logText = `📨 <b>Admin message</b>\n\nTo: <b>${escapeHtml(uname)}</b> (tg:<code>${targetTgId}</code>)\nBy: <b>${escapeHtml(by)}</b>\nTime: <code>${new Date().toISOString()}</code>\n\n<b>Text:</b>\n${escapeHtml(snippet)}`;
    const logKb = new InlineKeyboard()
      .text('👤 Карточка', `a:adm_ucard|id:${backUid}|f:${f}|p:${page}`)
      .text('✉️ Ещё', `a:adm_umsg|id:${backUid}|f:${f}|p:${page}`);

    for (const t of targets) {
      if (!t) continue;
      try {
        await ctx.api.sendMessage(t, logText, { parse_mode: 'HTML', disable_web_page_preview: true, reply_markup: logKb });
      } catch {}
    }
  } catch {}
}

async function sendAdminUsersCsv(ctx, filter = 'all', q = '') {
  const { rows, truncated } = await db.exportUsersDirectory(filter, q);

  const msk = (d) => d ? new Date(d).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }) : '';

  function userRoles(r) {
    const roles = [];
    if (isSuperAdminTg(Number(r.tg_id))) roles.push('super_admin');
    if (r.is_manager) roles.push('manager');
    if (r.is_moderator || r.is_curator) roles.push('curator');
    if (r.is_creator) roles.push('creator');
    const isBrand = !!r.has_brand_profile || !!r.brand_plan || Number(r.brand_credits || 0) > 0;
    if (isBrand) roles.push('brand');
    if (!roles.length) roles.push('user');
    return roles.join(';');
  }

  // BOM for Excel UTF-8
  const BOM = '\uFEFF';
  const header = 'user_id,tg_id,username,roles,created_at_msk,updated_at_msk,brand_plan,brand_plan_until_msk,brand_credits,brand_credits_spent';

  const csvRows = rows.map((r) => {
    const fields = [
      r.user_id,
      r.tg_id,
      csvEsc(r.tg_username || ''),
      csvEsc(userRoles(r)),
      csvEsc(msk(r.created_at)),
      csvEsc(msk(r.updated_at)),
      csvEsc(r.brand_plan || ''),
      csvEsc(msk(r.brand_plan_until)),
      Number(r.brand_credits || 0),
      Number(r.brand_credits_spent || 0),
    ];
    return fields.join(',');
  });

  const csv = BOM + header + '\n' + csvRows.join('\n');

  const labelMap = { all: 'all', brands: 'brands', creators: 'creators', curators: 'curators', managers: 'managers' };
  const tag = labelMap[filter] || 'all';
  const ts = new Date().toISOString().slice(0, 10);
  const filename = `users_${tag}${q ? '_search' : ''}_${ts}.csv`;

  let caption = `📤 Export: ${rows.length} записей · фильтр: ${tag}`;
  if (q) caption += ` · поиск: "${q}"`;
  if (truncated) caption += `\n⚠️ Лимит 10 000 — сузьте фильтр для полной выгрузки.`;

  await ctx.replyWithDocument(
    new InputFile(Buffer.from(csv, 'utf-8'), filename),
    {
      caption,
      reply_markup: new InlineKeyboard()
        .text('⬅️ К списку', `a:admin_users|f:${filter}|p:0`)
        .text('⬅️ Админка', 'a:admin_home')
    }
  );
}

function csvEsc(val) {
  const s = String(val ?? '');
  if (s.includes(',') || s.includes('"') || s.includes('\n') || s.includes(';')) {
    return '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
}

async function renderAdminPayments(ctx, statusRaw = 'ORPHANED', page = 0) {
  const status = String(statusRaw || 'ORPHANED').toUpperCase();
  const limit = 10;
  const offset = Math.max(0, Number(page) || 0) * limit;

  const fbOn = await isPaymentsFallbackApplyEnabled();

  const rows = await db.listPaymentsByStatus(status, limit, offset);
  const lines = rows
    .map((r) => {
      const when = new Date(r.created_at).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' });
      const who = r.username ? '@' + r.username : 'id ' + r.tg_id;
      return `#${r.id} • ${r.kind} • ${who} • ${r.total_amount} ${r.currency} • ${when}`;
    })
    .join('\n') || 'Платежей нет.';

  const kb = new InlineKeyboard();
  if (status === 'ORPHANED' && CFG.PAYMENTS_ORPHANED_AUTOHEAL_ENABLED && fbOn) {
    kb.text('🔁 Auto-heal missing_session', `a:admin_pay_autoheal|st:${status}|p:${Math.max(0, Number(page) || 0)}`).row();
  }
  for (const r of rows) {
    kb.text(`#${r.id} • ${r.kind}`, `a:admin_pay_view|id:${r.id}|st:${status}|p:${Math.max(0, Number(page) || 0)}`).row();
  }
  if ((Number(page) || 0) > 0) kb.text('⬅️ Назад', `a:admin_payments|st:${status}|p:${Number(page) - 1}`);
  if (rows.length === limit) kb.text('➡️ Далее', `a:admin_payments|st:${status}|p:${Number(page) + 1}`);
    kb.row().text('⬅️ Операции', 'a:admin_ops');

  await safeEditOrReply(ctx, 
    `💳 <b>Payments</b> • <b>${escapeHtml(status)}</b>

${escapeHtml(lines)}`,
    { parse_mode: 'HTML', reply_markup: kb }
  );
}

async function renderAdminPaymentView(ctx, paymentId, backStatus = 'ORPHANED', page = 0) {
  const p = await db.getPaymentById(Number(paymentId));
  if (!p) {
    await safeEditOrReply(ctx, '⚠️ Платеж не найден.', { reply_markup: navKb(`a:admin_payments|st:${backStatus}|p:${page}`) });
    return;
  }

  const payload = String(p.invoice_payload || '');
  const when = new Date(p.created_at).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' });
  const who = p.username ? '@' + p.username : 'id ' + p.tg_id;
  const canApply = (p.status === 'ORPHANED' || p.status === 'ERROR' || p.status === 'RECEIVED') &&
    (payload.startsWith('pro_') || payload.startsWith('brand_') || payload.startsWith('bplan_') || payload.startsWith('offpub_'));

  const kb = new InlineKeyboard();
  if (canApply) kb.text('✅ Apply (manual)', `a:admin_pay_apply|id:${p.id}|st:${backStatus}|p:${page}`).row();
  kb.text('⬅️ К списку', `a:admin_payments|st:${backStatus}|p:${page}`).row();
  kb.text('⬅️ Операции', 'a:admin_ops');

  const text = `💳 <b>Payment #${p.id}</b>

Status: <b>${escapeHtml(p.status)}</b>
Kind: <b>${escapeHtml(p.kind)}</b>
User: <b>${escapeHtml(who)}</b>
Amount: <b>${p.total_amount} ${escapeHtml(p.currency)}</b>
Created: <b>${escapeHtml(when)}</b>

Charge:
<tg-spoiler>${escapeHtml(String(p.telegram_payment_charge_id || '—'))}</tg-spoiler>

Payload:
<tg-spoiler>${escapeHtml(payload)}</tg-spoiler>

Note:
<tg-spoiler>${escapeHtml(String(p.note || '—'))}</tg-spoiler>`;

  await safeEditOrReply(ctx, text, { parse_mode: 'HTML', reply_markup: kb });
}

async function adminApplyPayment(ctx, adminUserRow, paymentId, backStatus = 'ORPHANED', page = 0) {
  const row = await db.getPaymentById(Number(paymentId));
  if (!row) {
    await ctx.answerCallbackQuery({ text: 'Платеж не найден.', show_alert: true });
    await renderAdminPayments(ctx, backStatus, page);
    return;
  }

  if (row.status === 'APPLIED') {
    await ctx.answerCallbackQuery({ text: 'Уже применён ✅', show_alert: true });
    await renderAdminPaymentView(ctx, row.id, backStatus, page);
    return;
  }

  const payload = String(row.invoice_payload || '');

  // Hardening: do not apply payments if amount/currency/payload do not match the current product catalog.
  try {
    const v = await _validateStarsPaymentStrict({
      payload,
      currency: String(row.currency || 'XTR'),
      totalAmount: Number(row.total_amount || 0),
      payerUserId: Number(row.user_id || 0) || null,
    });
    if (!v.ok) {
      const note = `manual_apply_blocked:${String(v.reason || 'unknown')} exp:${Number(v.expected || 0)} got:${Number(v.paid || row.total_amount || 0)} cur:${String(row.currency || 'XTR')}`;
      try { await db.setPaymentStatus(row.id, 'ERROR', note.slice(0, 240)); } catch {}
      await ctx.answerCallbackQuery({ text: '⛔️ Apply заблокирован: счёт невалидный/не совпадает сумма.', show_alert: true });
      await renderAdminPaymentView(ctx, row.id, backStatus, page);
      return;
    }
  } catch {
    // If we cannot validate, block apply (fail-safe).
    try { await db.setPaymentStatus(row.id, 'ERROR', 'manual_apply_blocked: validation_exception'); } catch {}
    await ctx.answerCallbackQuery({ text: '⛔️ Apply заблокирован: ошибка валидации.', show_alert: true });
    await renderAdminPaymentView(ctx, row.id, backStatus, page);
    return;
  }

  // Claim fulfillment in DB to prevent double-apply (retries / parallel admins / cron).
  const claimed = await db.claimPaymentApplying(row.id, adminUserRow.id);
  if (!claimed) {
    await ctx.answerCallbackQuery({ text: '⏳ Платёж уже обрабатывается или применён.', show_alert: true });
    await renderAdminPaymentView(ctx, row.id, backStatus, page);
    return;
  }

  try {
    if (payload.startsWith('pro_')) {
      const parts = payload.split('_');
      const wsId = Number(parts[1]);
      if (!wsId) throw new Error('Bad wsId');
      await db.activateWorkspacePro(wsId, CFG.PRO_DURATION_DAYS);
      await db.auditWorkspace(wsId, adminUserRow.id, 'pro.activated.manual', {
        payment_id: row.id,
        telegram_payment_charge_id: row.telegram_payment_charge_id
      });
      await db.markPaymentApplied(row.id, adminUserRow.id, 'manual_apply_pro');
      await ctx.answerCallbackQuery({ text: 'PRO применён ✅', show_alert: true });
      await renderAdminPaymentView(ctx, row.id, backStatus, page);
      return;
    }

    if (payload.startsWith('brand_')) {
      const parts = payload.split('_');
      const userId = Number(parts[1]);
      const packToken = String(parts[2] || '').trim();

      // New format: brand_<userId>_<S|M|L>_<token>
      // Legacy safety: if somehow a numeric token is present, try resolve by credits.
      let pack = getBrandPack(packToken);
      if (!pack && /^\d+$/.test(packToken)) {
        const n = Number(packToken);
        pack = BRAND_PACKS.find(p => Number(p.credits) === n) || null;
      }

      if (!userId || !pack) throw new Error('Bad userId/pack');
      const newBalance = await db.addBrandCredits(userId, Number(pack.credits));
      try { await setBrandCreditsCache(userId, newBalance); } catch {}
      await db.markPaymentApplied(row.id, adminUserRow.id, `manual_apply_brand_pass:+${pack.credits}`);
      await ctx.answerCallbackQuery({ text: 'Кредиты начислены ✅', show_alert: true });
      await renderAdminPaymentView(ctx, row.id, backStatus, page);
      return;
    }

    if (payload.startsWith('bplan_')) {
      const parts = payload.split('_');
      const userId = Number(parts[1]);
      const planRaw = String(parts[2] || 'start').toLowerCase();
      const plan = (planRaw === 'basic') ? 'start' : (planRaw === 'max') ? 'pro' : planRaw;

      if (!userId) throw new Error('Bad userId');
      if (plan !== 'start' && plan !== 'pro') throw new Error('Bad plan');

      await db.activateBrandPlan(userId, plan, CFG.BRAND_PLAN_DURATION_DAYS);
      // Credit bonus
      const planDef = BRAND_PLANS.find(pl => pl.id === plan) || null;
      if (planDef?.credits) {
        const newBalance = await db.addBrandCredits(userId, planDef.credits);
        try { await setBrandCreditsCache(userId, newBalance); } catch {}
      }
      await db.markPaymentApplied(row.id, adminUserRow.id, `manual_apply_brand_plan:${plan}${planDef?.credits ? `:+${planDef.credits}cr` : ''}`);
      await ctx.answerCallbackQuery({ text: 'Brand Plan применён ✅', show_alert: true });
      await renderAdminPaymentView(ctx, row.id, backStatus, page);
      return;
    }

    if (payload.startsWith('offpub_')) {
      const parts = payload.split('_');
      const offerId = Number(parts[2]);
      const days = Number(parts[3] || CFG.OFFICIAL_MANUAL_DEFAULT_DAYS);
      if (!CFG.OFFICIAL_PUBLISH_ENABLED) throw new Error('Official publishing disabled');
      if (!offerId) throw new Error('Bad offerId');
            const pubRes = await queueOfficialPublishToOfficialChannel(ctx.api, offerId, {
        placementType: 'PAID',
        paymentId: row.id,
        days,
        publishedByUserId: adminUserRow.id,
        keepExpiry: false
      });
      if (pubRes && pubRes.locked) {
        await ctx.answerCallbackQuery({ text: '⏳ Уже публикуется. Попробуй чуть позже.', show_alert: true });
        await renderAdminPaymentView(ctx, row.id, backStatus, page);
        return;
      }
      if (pubRes && pubRes.queued) {
        await ctx.answerCallbackQuery({ text: 'Поставлено в очередь ✅', show_alert: true });
      } else {
        await ctx.answerCallbackQuery({ text: 'Опубликовано ✅', show_alert: true });
      }
      await renderAdminPaymentView(ctx, row.id, backStatus, page);
      return;
    }

    // match/feat or unknown
    await ctx.answerCallbackQuery({ text: 'Эта услуга не поддерживает apply.', show_alert: true });
    await renderAdminPaymentView(ctx, row.id, backStatus, page);
    return;
  } catch (e) {
    const msg = String(e?.message || e);
    try {
      await db.setPaymentStatus(row.id, 'ERROR', `manual_apply_error: ${msg.slice(0, 160)}`);
    } catch {
      // ignore
    }
    await ctx.answerCallbackQuery({ text: `Ошибка apply: ${msg.slice(0, 64)}`, show_alert: true });
    await renderAdminPaymentView(ctx, row.id, backStatus, page);
  }
}


async function adminAutoHealPayments(ctx, adminUserRow, backStatus = 'ORPHANED', page = 0) {
  const fbOn = await isPaymentsFallbackApplyEnabled();
  if (!fbOn || !CFG.PAYMENTS_ORPHANED_AUTOHEAL_ENABLED) {
    try { await ctx.answerCallbackQuery({ text: 'Auto-heal отключён (fallback apply OFF).', show_alert: true }); } catch {}
    await renderAdminPayments(ctx, backStatus, page);
    return;
  }

  const batch = Math.max(0, Number(CFG.PAYMENTS_ORPHANED_AUTOHEAL_BATCH || 20) || 0);
  if (batch <= 0) {
    try { await ctx.answerCallbackQuery({ text: 'Auto-heal batch=0.', show_alert: true }); } catch {}
    await renderAdminPayments(ctx, backStatus, page);
    return;
  }

  // Only heal ORPHANED missing_session (safe, intended to be auto-applied).
  // Safety: ignore very fresh payments to avoid races with late webhook/session reconciliation.
  const rows = await db.listPaymentsByStatus('ORPHANED', 50, 0);
  const minAgeSec = Math.max(0, Number(CFG.PAYMENTS_ORPHANED_AUTOHEAL_MIN_AGE_SEC || 0) || 0);
  const nowMs = Date.now();
  const miss = (rows || []).filter(r => String(r.note || '').includes('missing_session'));
  const eligible = miss.filter(r => {
    if (minAgeSec <= 0) return true;
    try {
      const t = new Date(r.created_at).getTime();
      if (!t) return true;
      return (nowMs - t) / 1000 >= minAgeSec;
    } catch { return true; }
  });
  const skippedYoung = Math.max(0, miss.length - eligible.length);
  const cand = eligible.slice(0, batch);

    let applied = 0;
  let failed = 0;
  let skipped = 0;
  let validationFailed = 0;
  let manualRequired = 0;

  for (const r of cand) {
    try {
      // Hardening: strict-validate Stars payment before any apply.
      let v = null;
      try {
        v = await _validateStarsPaymentStrict({
          payload: String(r.invoice_payload || ''),
          currency: String(r.currency || 'XTR'),
          totalAmount: Number(r.total_amount || 0),
          payerUserId: Number(r.user_id || 0) || null,
        });
      } catch {
        v = { ok: false, reason: 'validation_exception' };
      }

      // Extra safety: do not auto-heal PRO without embedded payer userId (legacy payload).
      const needsPayer = String(r.invoice_payload || '').startsWith('pro_');
      if (!v || !v.ok || (needsPayer && !(v?.meta && v.meta.userId))) {
        const rr = (!v || !v.ok) ? String(v?.reason || 'validation_failed') : 'missing_payer_in_payload';
        validationFailed += 1;
        try { await db.setPaymentStatus(Number(r.id), 'ORPHANED', `autoheal_manual_required:${rr}`); } catch {}
        skipped += 1;
        continue;
      }

      // Claim fulfillment in DB to prevent double-apply (cron/admin parallelism).
      const claimed = await db.claimPaymentApplying(Number(r.id), adminUserRow?.id || Number(r.user_id));
      if (!claimed) {
        skipped += 1;
        continue;
      }

      const fb = await applyPaymentFallbackNoSession({
        paymentId: Number(r.id),
        paymentUserId: Number(r.user_id),
        invoicePayload: String(r.invoice_payload || ''),
        appliedByUserId: adminUserRow?.id || Number(r.user_id),
        totalAmount: Number(r.total_amount || 0),
        currency: String(r.currency || 'XTR'),
        telegramPaymentChargeId: String(r.telegram_payment_charge_id || ''),
      });

      if (fb && fb.applied) {
        applied += 1;
        // Best-effort notify user that payment was applied after recovery.
        try {
          const tgId = Number(r.tg_id || 0);
          if (tgId) {
            let msg = '✅ Оплата найдена и применена автоматически.';
            if (fb.kind === 'brand_pass') msg += `\n\n💳 Кредиты начислены: +${Number(fb.credits || 0)}.`;
            if (fb.kind === 'brand_plan') msg += `\n\n⭐️ Brand Plan активирован (${String(fb.plan || '')}).`;
            if (fb.kind === 'pro') msg += `\n\n⭐️ PRO активирован.`;
            if (fb.kind === 'founder_brand') msg += `\n\n⭐️ Founder Sale применён.`;
            await ctx.api.sendMessage(tgId, msg);
          }
        } catch {}
      } else {
        skipped += 1;

        // Avoid retry loops for permanent non-applied cases.
        const rr = String(fb?.reason || '');
        if (rr === 'unsupported_payload' || rr === 'missing_userid_or_wsid' || rr === 'bad_input' || rr === 'user_mismatch' || rr === 'amount_mismatch') {
          manualRequired += 1;
          try { await db.setPaymentStatus(Number(r.id), 'ORPHANED', `autoheal_manual_required:${rr}`); } catch {}
        }
      }
    } catch {
      failed += 1;
    }
  }

  try {
    await ctx.answerCallbackQuery({
      text: `Auto-heal: applied ${applied}, failed ${failed}, skipped ${skipped}, validation ${validationFailed}, manual ${manualRequired}${skippedYoung ? `, young ${skippedYoung}` : ''}`,
      show_alert: true
    });
  } catch {}

  await renderAdminPayments(ctx, backStatus, page);
}

